const char *PHOTOS = "/M5RETRO/fotos";

// O canvas da TV (`tv`) mora em fj/Display.cpp: é um LGFX_Sprite apontado para
// o framebuffer do DVI. No firmware original era o M5ModuleRCA do CVBS.
JPEGDEC jpeg;
