void InputManager::begin() {
  _queued = NavAction::NONE;
  _heldZone = _highlightedButton = -1;
  _down = _longSent = _homeSent = _sideLongSent = _repeatSent = false;
  _chord = _chordSent = false;
}
void InputManager::queue(NavAction action, int8_t button) {
  if (_queued == NavAction::NONE)
    _queued = action;
  if (button >= 0) {
    _highlightedButton = button;
    _highlightUntil = millis() + HIGHLIGHT_MS;
  }
}
void InputManager::highlightButton(int8_t button) {
  if (button >= 0 && button < 3) {
    _highlightedButton = button;
    _highlightUntil = millis() + HIGHLIGHT_MS;
  }
}
void InputManager::inject(NavAction action, InputSource source) {
  (void)source;
  int8_t button =
      (action == NavAction::LEFT || action == NavAction::PREVIOUS || action == NavAction::SEEK_BACKWARD) ? 0
      : (action == NavAction::RIGHT || action == NavAction::NEXT || action == NavAction::SEEK_FORWARD)   ? 2
                                                                                                         : 1;
  queue(action, button);
}
NavAction InputManager::getAction() {
  NavAction action = _queued;
  _queued = NavAction::NONE;
  return action;
}
bool InputManager::anyDown() {
  return board::buttonDown(0) || board::buttonDown(1) || board::buttonDown(2);
}

void InputManager::update() {
  const uint32_t now = millis();
  // Botoes fisicos do Fruit Jam. O board ja desconta a logica invertida (ativos
  // em nivel baixo) e o pull-up interno; o repique mecanico e absorvido pelos
  // limiares de tempo abaixo, todos muito maiores que ele.
  const bool pressed[3] = {board::buttonDown(0), board::buttonDown(1), board::buttonDown(2)};

  // A+C juntos: atalho para o inicio. Vem antes do caminho de um botao so
  // porque apertar os dois nunca e exatamente simultaneo: o primeiro a descer
  // ja abriu um gesto de A ou de C, e ele precisa ser engolido aqui.
  if (pressed[0] && pressed[2]) {
    if (!_chord) {
      _chord = true;
      _chordSent = false;
      _chordAt = now;
    }
    if (!_chordSent && now - _chordAt >= CHORD_MS) {
      _chordSent = true;
      queue(NavAction::HOME, 1);
    }
    return;
  }
  if (_chord) {
    // Acorde disparado ou abortado: nada mais sai ate soltar TUDO. Sem isto,
    // soltar o C um instante antes do A virava um LEFT depois do HOME.
    if (!pressed[0] && !pressed[1] && !pressed[2]) {
      _chord = _chordSent = false;
      _down = _longSent = _homeSent = _sideLongSent = _repeatSent = false;
      _heldZone = -1;
    }
    return;
  }

  int8_t zone = pressed[0] ? 0 : pressed[1] ? 1 : pressed[2] ? 2 : -1;
  if (zone < 0) {
    if (_down) {
      uint32_t elapsed = now - _downAt;
      if (_heldZone == 1)
        queue((_homeSent || elapsed >= HOME_MS)   ? NavAction::HOME
              : (_longSent || elapsed >= LONG_MS) ? NavAction::BACK
                                                  : NavAction::SELECT,
              1);
      else if (!_sideLongSent && !_repeatSent)
        queue(_heldZone == 0 ? NavAction::LEFT : NavAction::RIGHT, _heldZone);
    }
    _down = _longSent = _homeSent = _sideLongSent = _repeatSent = false;
    _heldZone = -1;
    return;
  }
  if (!_down) {
    _down = true;
    _heldZone = zone;
    _downAt = now;
    _nextRepeatAt = now + REPEAT_DELAY_MS;
    _longSent = _homeSent = _sideLongSent = _repeatSent = false;
    highlightButton(zone);
    return;
  }
  if (zone != _heldZone)
    return;
  uint32_t elapsed = now - _downAt;
  if (_heldZone == 1) {
    if (!_homeSent && elapsed >= HOME_MS)
      _homeSent = true;
    else if (!_longSent && elapsed >= LONG_MS)
      _longSent = true;
    return;
  }
  if (!_repeatEnabled && !_sideLongSent && elapsed >= LONG_MS) {
    _sideLongSent = true;
    queue(_heldZone == 0 ? NavAction::PREVIOUS : NavAction::NEXT, _heldZone);
  } else if (_repeatEnabled && !_sideLongSent && timeReached(now, _nextRepeatAt)) {
    _repeatSent = true;
    queue(_heldZone == 0 ? NavAction::LEFT : NavAction::RIGHT, _heldZone);
    _nextRepeatAt = now + REPEAT_MS;
  }
}

#include "NetworkManager.h"
#include "UiLogic.h"
#include "fj/Net.h"
#include <WiFiNINA.h>

// Tempo que uma tentativa tem para chegar a WL_CONNECTED antes de contar como
// falha. Associação WPA2 + DHCP no ESP32-C6 leva 2 a 5 s.
static const uint32_t ATTEMPT_MS = 10000;
// O RSSI muda devagar e cada leitura é uma transação SPI.
static const uint32_t RSSI_PERIOD_MS = 2000;

void NetworkManager::begin(const SecretsConfig &config) {
  _config = config;
  _failures = 0;
  _attemptActive = false;
  _enabled = config.valid();
  _retryAt = millis();
  forget();
  _state = _enabled ? NetworkState::CONNECTING : NetworkState::OFFLINE;
}
void NetworkManager::setConfiguration(const SecretsConfig &config) {
  disconnect();
  begin(config);
}
void NetworkManager::forget() {
  _ip = String();
  _rssi = 0;
}
// Com o ESP32-C6 ausente, qualquer chamada da WiFiNINA espera para sempre.
void NetworkManager::dropRadio() {
  if (!net::radioReady())
    return;
  net::Lock l;
  WiFi.disconnect();
}
void NetworkManager::disconnect() {
  dropRadio();
  _attemptActive = false;
  _enabled = false;
  forget();
  _state = NetworkState::OFFLINE;
}
void NetworkManager::reconnectNow() {
  dropRadio();
  begin(_config);
}
void NetworkManager::startAttempt() {
  // net::startStation só manda o comando: o WiFi.begin() da biblioteca ficaria
  // em delay(5000) até 50 s dentro do loop().
  net::startStation(_config.ssid.c_str(), _config.password.c_str());
  _attemptStarted = millis();
  _attemptActive = true;
  _state = NetworkState::CONNECTING;
}
void NetworkManager::update() {
  if (!_enabled || !_config.valid())
    return;
  if (!net::radioReady()) {
    _state = NetworkState::FAILED;
    return;
  }
  // Rádio ocupado por uma tarefa de rede = rádio funcionando. Tenta na próxima.
  net::TryLock lock;
  if (!lock)
    return;
  const uint32_t now = millis();
  bool up = WiFi.status() == WL_CONNECTED;
  if (up && _state != NetworkState::CONNECTED) {
    // Chegou agora. Pode ser a rede que o portal testou, não a configurada.
    if (String(WiFi.SSID()) != _config.ssid) {
      WiFi.disconnect();
      _attemptActive = false;
      _retryAt = now;
      up = false;
    } else {
      _ip = WiFi.localIP().toString();
      _rssi = WiFi.RSSI();
      _rssiAt = now;
    }
  }
  if (up) {
    _state = NetworkState::CONNECTED;
    _failures = 0;
    _attemptActive = false;
    _retryAt = now;
    if (now - _rssiAt >= RSSI_PERIOD_MS) {
      _rssi = WiFi.RSSI();
      _rssiAt = now;
    }
    return;
  }
  if (_state == NetworkState::CONNECTED)
    forget(); // caiu; o _retryAt de quando estava conectado dispara a volta já
  if (_attemptActive && now - _attemptStarted >= ATTEMPT_MS) {
    WiFi.disconnect();
    _attemptActive = false;
    const uint8_t exponent = _failures < 3 ? _failures : 3;
    if (_failures < 255)
      ++_failures;
    _retryAt = now + (5000UL << exponent);
    _state = NetworkState::FAILED;
  }
  if (!_attemptActive && timeReached(now, _retryAt))
    startAttempt();
}

#include "SecretsManager.h"
