    "<h2>M5 RETRO TV - enviar para o cartao</h2>"
    "<p>Destino <select id=k><option>videos<option>music<option>fotos</select> "
    "pasta <input id=p size=14 placeholder=meu-filme></p>"
    "<p><input type=file id=f multiple></p><button onclick=go()>Enviar</button><div id=l></div>"
    "<script>async function go(){var a=[].slice.call(f.files);"
    "a.sort(function(x,y){return (x.name=='meta.json')-(y.name=='meta.json')});l.textContent='';"
    "for(var i=0;i<a.length;i++){var x=a[i],d=document.createElement('div');"
    "d.textContent=x.name+': enviando';l.appendChild(d);"
    "var u='/upload/'+k.value+'/'+(p.value?encodeURIComponent(p.value)+'/':'')+encodeURIComponent(x.name);"
    "try{var h=await fetch(u,{method:'HEAD'}),o=0;"
    "if(h.ok)o=parseInt(h.headers.get('X-Resume-Offset')||'0',10)||0;if(o>x.size)o=0;"
    "var g=o?{'Range':'bytes='+o+'-','X-Upload-Offset':''+o}:{};"
    "var r=await fetch(u,{method:'PUT',headers:g,body:o?x.slice(o):x});"
    "d.textContent=x.name+': '+(r.ok?'ok':'ERRO '+r.status+' '+await r.text());}"
    "catch(e){d.textContent=x.name+': falhou';}}}</script>";

class FileTransfer {
public:
  // ---- ciclo de vida -------------------------------------------------------

  // `sdMutex` vem de fora porque mora em main.cpp. Passar nullptr e aceito (o
  // acesso ao cartao fica sem protecao), mas nao e o que o firmware faz.
  bool begin(SemaphoreHandle_t sdMutex, uint16_t port = 80);
  void stop();

  // Nao bloqueante. Chamar do loop(); trabalha no maximo SLICE_MS por chamada.
  void handle();

  // ---- getters para a tela desenhar sem conhecer o interior ---------------
  bool active() const { return _active; }
  TransferStatus status() const { return _status; }
  uint16_t port() const { return _port; }
  // Guardado, e nao perguntado ao NINA a cada chamada: a tela chama isto a cada
  // repintura (4x/s recebendo), e cada pergunta seria uma transacao no SPI1
  // tomando o net::Lock do loop(). handle() refresca de tempos em tempos.
  String ip() const { return String(_ip); }
  const char *user() const { return "m5retro"; }
  const char *password() const { return _password; }
  const char *fileName() const { return _name; }   // nome curto do arquivo em curso
  uint64_t received() const { return _received; }
  uint64_t total() const { return _total; }
  uint16_t filesInstalled() const { return _installed; }
  const char *lastError() const { return _error; }
  // Diagnóstico: o socket de escuta realmente subiu? (lido do NINA no begin())
  bool listening() const { return _listening; }
  uint8_t percent() const {
    if (!_total)
      return 0;
    if (_received >= _total)
      return 100;
    return uint8_t((_received * 100) / _total);
  }

  static const size_t BLOCK = 8192;          // ver decisao 5
  static const uint32_t SLICE_MS = 12;       // fatia maxima por handle()
  static const uint32_t IDLE_MS = 20000;     // conexao parada e abandonada
  // Conexao aceita que nao mandou NENHUM byte. Navegadores abrem conexoes
  // especulativas e nao usam; como aqui ha uma conexao por vez, esperar os 20 s
  // do IDLE_MS por uma delas travaria o envio de verdade que esta na fila.
  static const uint32_t FIRST_BYTE_MS = 3000;
  // De quanto em quanto tempo perguntar ao NINA se o socket ainda esta de pe
  // quando nao chega nada. Cada pergunta e uma transacao no SPI1.
  static const uint32_t ALIVE_CHECK_MS = 250;
  // Escrita por transacao SPI. O buffer de comando do NINA e de ~4 KB (o maximo
  // do DMA do SPI escravo do C6); 2 KB deixam folga para o cabecalho do comando
  // e ainda mandam a pagina inteira em uma ou duas idas.
  static const size_t WRITE_CHUNK = 2048;
  static const uint32_t IP_REFRESH_MS = 10000; // DHCP pode trocar o endereco
  static const uint32_t SD_WAIT_MS = 1000;   // espera pelo sdMutex por bloco
  static const uint32_t MAX_HEADER = 2048;   // teto do bloco de cabecalhos
  static const size_t LINE_CAP = 512;        // linha de pedido / cabecalho
  static const size_t PASSWORD_LEN = 8;
  static const uint64_t RESERVE = 1024u * 1024u; // folga exigida no cartao

private:
  enum class Phase : uint8_t { OCIOSA, CABECALHO, CORPO };
  enum class Method : uint8_t { OUTRO, GET, HEAD, PUT };
  enum class Route : uint8_t { DESCONHECIDA, RAIZ, UPLOAD, CONTROLE, COMANDO };

  WiFiClient _client;
  File _file;
  SemaphoreHandle_t _sd = nullptr;
  // PSRAM, BLOCK bytes. Tres usos que nunca se sobrepoem: bytes crus do
  // cabecalho (_hdrPos.._hdrLen), acumulador do corpo ate um bloco inteiro
  // (_fill) e leitura de volta do cabecalho JPEG em completeBody().
  uint8_t *_buffer = nullptr;
  size_t _hdrPos = 0, _hdrLen = 0;
  size_t _fill = 0;
  char _ip[16] = {0};
  uint32_t _ipCheckMs = 0;
  uint32_t _aliveCheckMs = 0;
  uint32_t _acceptedMs = 0;
  bool _listening = false;

  bool _active = false;
  TransferStatus _status = TransferStatus::PARADO;
  Phase _phase = Phase::OCIOSA;
  const char *_error = "";
  uint16_t _port = 80;
  uint16_t _installed = 0;

  char _password[PASSWORD_LEN + 1];
  char _path[PATH_CAP];
  char _part[PATH_CAP];
  char _name[MAX_SEGMENT + 1];
  char _line[LINE_CAP];
  char _authUser[MAX_SECRET + 1];
  char _authPass[MAX_SECRET + 1];

  size_t _lineLen = 0;
  uint32_t _headerBytes = 0;
  bool _haveRequestLine = false, _hasAuth = false, _hasLength = false, _hasOffset = false;
  Method _method = Method::OUTRO;
  Route _route = Route::DESCONHECIDA;
  PathError _pathError = PathError::VAZIO;
  uint64_t _length = 0, _offset = 0, _received = 0, _total = 0;
  uint32_t _deadline = 0;

  // ---- cartao --------------------------------------------------------------
  bool sdTake(uint32_t ms) {
    if (!_sd)
      return true;
    return xSemaphoreTake(_sd, pdMS_TO_TICKS(ms)) == pdTRUE;
  }
  void sdGive() {
    if (_sd)
      xSemaphoreGive(_sd);
  }

  // ---- rede (toda chamada WiFiNINA com net::Lock, uma operacao por vez) ------
  //
  // Nada de WiFiClient::connected() aqui. No WiFiNINA ele poe o socket em 255
  // quando ve a conexao caida — e depois disso stop() nao faz nada. Para um
  // socket ACEITO pelo servidor o firmware NINA nao libera o slot sozinho
  // (so libera os abertos por connect), entao o slot vazaria a cada navegador
  // que fechasse primeiro, e em poucas conexoes o C6 pararia de aceitar. Por
  // isso a vida do socket e lida com status() e o fim e sempre stop().
  bool peerAlive();
  int netRead(uint8_t *dst, size_t cap);
  bool netWriteAll(const uint8_t *data, size_t len);
  void refreshIp();
  bool flushFill();

  // ---- conexao -------------------------------------------------------------
  void beginRequest();
  void closeConnection(bool discardPartial);
  bool expired() const { return int32_t(millis() - _deadline) >= 0; }
  void touch() { _deadline = millis() + IDLE_MS; }

  bool pumpHeader();
  bool pumpBody();
  void parseRequestLine();
  void parseHeaderLine();
  void finishHeaders();
  bool authorized() const;
  void startBody();
  void completeBody();
  void abortBody(const char *reason);

  void respond(int code, const char *reason, const char *type, const char *body, const char *extra = NULL);
  void respondPage(bool bodyToo);
  void respondControl(bool bodyToo);
  void respondResume();
  void makePassword();
  uint32_t partSize();

  // Quem trata o comando do controle remoto. Ponteiro de funcao de proposito:
  // este header nao conhece NavAction nem a maquina de telas, e nao deve
  // conhecer. Devolve false para comando desconhecido, o que vira 400.
  CommandFn _cmd = NULL;
  void *_cmdUser = NULL;
  char _acao[16] = {0};

public:
  // Liga o controle remoto. Sem isto as rotas /controle e /cmd respondem 404,
  // e o servidor se comporta exatamente como antes.
  void setCommandHandler(CommandFn fn, void *user) {
    _cmd = fn;
    _cmdUser = user;
  }
};

// ---------------------------------------------------------------------------
// Implementacao
// ---------------------------------------------------------------------------

inline bool FileTransfer::begin(SemaphoreHandle_t sdMutex, uint16_t port) {
  if (_active)
    return true;
  _sd = sdMutex;
  _port = port ? port : 80;
  _error = "";
  bool conectado;
  {
    net::Lock lock;
    conectado = WiFi.status() == WL_CONNECTED;
  }
  if (!conectado) {
    _error = "sem Wi-Fi";
    _status = TransferStatus::FALHA;
    return false;
  }
  // PSRAM, nunca SRAM: o framebuffer do DVI ja leva 153.600 B da interna e o
  // upstream ja estourou pilha duas vezes com buffer grande no lugar errado.
  // Sem PSRAM, falhar e mais honesto do que roubar SRAM.
  if (!_buffer)
    _buffer = (uint8_t *)ps_malloc(BLOCK);
  if (!_buffer) {
    _error = "sem PSRAM para o buffer";
    _status = TransferStatus::FALHA;
    return false;
  }
  _listening = net::listen(_port);
  if (!_listening) {
    _error = "servidor HTTP nao subiu";
    _status = TransferStatus::FALHA;
    return false;
  }
  refreshIp();
  makePassword();
  _installed = 0;
  _received = _total = 0;
  _fill = _hdrPos = _hdrLen = 0;
  _name[0] = '\0';
  _phase = Phase::OCIOSA;
  _active = true;
  _status = TransferStatus::AGUARDANDO;
  return true;
}

inline void FileTransfer::stop() {
  // O `.part` sobrevive de proposito: sair da tela e voltar depois retoma o
  // arquivo de onde parou em vez de reenviar 45 MB. O que estava acumulado no
  // buffer vai para o cartao antes, para a retomada perder o minimo.
  if (_phase == Phase::CORPO && _fill)
    flushFill();
  closeConnection(false);
  // O servidor NAO e fechado (o NINA nao sabe fechar, ver detail::Listener):
  // so deixa de ser atendido. Conexoes que chegarem agora esperam na fila do C6
  // ate o navegador desistir.
  if (_buffer) {
    free(_buffer);
    _buffer = NULL;
  }
  _password[0] = '\0'; // a senha morre com a sessao
  _active = false;
  _status = TransferStatus::PARADO;
  _phase = Phase::OCIOSA;
}

inline void FileTransfer::makePassword() {
  // 32 simbolos sem 0/O/1/I/l: a senha vai ser lida da tela de um tubo e
  // digitada no computador. 8 caracteres = 40 bits, de sobra para uma sessao
  // que dura minutos numa LAN.
  static const char kAlphabet[] = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ";
  for (size_t i = 0; i < PASSWORD_LEN; ++i)
    _password[i] = kAlphabet[esp_random() & 31u];
  _password[PASSWORD_LEN] = '\0';
}

inline void FileTransfer::refreshIp() {
  IPAddress addr;
  {
    net::Lock lock;
    addr = WiFi.localIP();
  }
  snprintf(_ip, sizeof(_ip), "%u.%u.%u.%u", (unsigned)addr[0], (unsigned)addr[1],
           (unsigned)addr[2], (unsigned)addr[3]);
  _ipCheckMs = millis();
}

inline bool FileTransfer::peerAlive() {
  net::Lock lock;
  if (!_client)
    return false;
  if (_client.available() > 0)
    return true; // ainda ha bytes a ler, mesmo que o outro lado ja tenha fechado
  return _client.status() == detail::NINA_TCP_ESTABLISHED;
}

inline int FileTransfer::netRead(uint8_t *dst, size_t cap) {
  net::Lock lock;
  if (!_client || !cap)
    return 0;
  // Traz no maximo o que o WiFiNINA ja tem no buffer dele (ate 1500 B por
  // transacao SPI); nao espera chegar mais.
  return _client.read(dst, cap);
}

// Escreve tudo ou devolve false. Uma transacao por pedaco de WRITE_CHUNK, com o
// lock so durante ela: a pagina de 2 KB nao segura o SPI1 de uma vez.
inline bool FileTransfer::netWriteAll(const uint8_t *data, size_t len) {
  while (len) {
    const size_t k = len > WRITE_CHUNK ? WRITE_CHUNK : len;
    size_t w;
    {
      net::Lock lock;
      if (!_client)
        return false;
      w = _client.write(data, k);
    }
    if (!w)
      return false; // o C6 recusou: conexao caiu ou buffer de envio cheio demais
    data += w;
    len -= w;
  }
  return true;
}

inline void FileTransfer::beginRequest() {
  _phase = Phase::CABECALHO;
  _lineLen = 0;
  _headerBytes = 0;
  _haveRequestLine = false;
  _hasAuth = _hasLength = _hasOffset = false;
  _method = Method::OUTRO;
  _route = Route::DESCONHECIDA;
  _pathError = PathError::VAZIO;
  _length = _offset = 0;
  _authUser[0] = _authPass[0] = '\0';
  _path[0] = _part[0] = '\0';
  _hdrPos = _hdrLen = 0;
  _fill = 0;
  _acceptedMs = _aliveCheckMs = millis();
  touch();
}

inline void FileTransfer::closeConnection(bool discardPartial) {
  if (_file) {
    // flush antes do close para que o tamanho do `.part` no cartao seja
    // exatamente `_received` — e o que faz a retomada bater.
    if (sdTake(SD_WAIT_MS)) {
      _file.flush();
      _file.close();
      if (discardPartial && _part[0])
        SD.remove(_part);
      sdGive();
    }
    _file = File();
  }
  {
    // stop() SEMPRE, mesmo com o outro lado ja fechado: e o que devolve o slot
    // do socket ao C6 (ver peerAlive). stop() do WiFiNINA espera o NINA
    // confirmar o fechamento, que no firmware atual e imediato.
    net::Lock lock;
    if (_client)
      _client.stop();
  }
  _client = WiFiClient();
  _fill = _hdrPos = _hdrLen = 0;
  _phase = Phase::OCIOSA;
  if (_status == TransferStatus::RECEBENDO)
    _status = TransferStatus::AGUARDANDO;
}

inline void FileTransfer::handle() {
  if (!_active)
    return;

  // Uma conexao por vez. O cartao e um recurso serial: atender dois envios
  // juntos so dividiria a mesma banda em dois e dobraria o estado a manter.
  if (_phase == Phase::OCIOSA) {
    if (uint32_t(millis() - _ipCheckMs) >= IP_REFRESH_MS)
      refreshIp();
    WiFiClient next;
    {
      net::Lock lock;
      next = _listening ? net::accept(_port) : WiFiClient();
    }
    if (!next)
      return;
    _client = next;
    beginRequest();
  }

  const uint32_t sliceStart = millis();
  for (;;) {
    if (millis() - sliceStart >= SLICE_MS)
      return; // devolve o loop(); o resto continua na proxima volta
    if (_phase == Phase::CABECALHO) {
      if (!pumpHeader())
        return;
    } else if (_phase == Phase::CORPO) {
      if (!pumpBody())
        return;
    } else {
      return; // ja respondeu e fechou
    }
  }
}

// Le o cabecalho em blocos para `_buffer` e interpreta byte a byte a partir
// dali. A sobra do ultimo bloco depois da linha vazia ja e CORPO: startBody()
// a aproveita como o comeco do acumulador, sem perder nem repetir byte.
inline bool FileTransfer::pumpHeader() {
  if (_hdrPos >= _hdrLen) {
    // Um bloco inteiro: o teto do cabecalho (MAX_HEADER) e conferido byte a
    // byte abaixo, e o que passar dele ja e corpo.
    const int n = netRead(_buffer, BLOCK);
    if (n <= 0) {
      const uint32_t now = millis();
      if (_headerBytes == 0 && now - _acceptedMs >= FIRST_BYTE_MS) {
        closeConnection(false); // conexao especulativa do navegador: libera a vez
        return false;
      }
      if (expired()) {
        closeConnection(false);
        return false;
      }
      if (now - _aliveCheckMs >= ALIVE_CHECK_MS) {
        _aliveCheckMs = now;
        if (!peerAlive())
          closeConnection(false);
      }
      return false;
    }
    _hdrPos = 0;
    _hdrLen = size_t(n);
  }
  while (_hdrPos < _hdrLen) {
    const char c = char(_buffer[_hdrPos++]);
    if (++_headerBytes > MAX_HEADER) {
      respond(431, "Request Header Fields Too Large", "text/plain", "cabecalho grande demais");
      return false;
    }
    if (c == '\r')
      continue;
    if (c != '\n') {
      if (_lineLen + 1 >= LINE_CAP) {
        respond(431, "Request Header Fields Too Large", "text/plain", "linha grande demais");
        return false;
      }
      _line[_lineLen++] = c;
      continue;
    }
    _line[_lineLen] = '\0';
    const size_t len = _lineLen;
    _lineLen = 0;
    if (len == 0) {
      finishHeaders();
      return _phase == Phase::CORPO;
    }
    if (!_haveRequestLine)
      parseRequestLine();
    else
      parseHeaderLine();
    if (_phase == Phase::OCIOSA)
      return false; // parseRequestLine ja respondeu e fechou
  }
  touch();
  return true;
}

inline void FileTransfer::parseRequestLine() {
  _haveRequestLine = true;
  char *space = strchr(_line, ' ');
  if (!space) {
    respond(400, "Bad Request", "text/plain", "pedido invalido");
    return;
  }
  *space = '\0';
  if (strcmp(_line, "GET") == 0)
    _method = Method::GET;
  else if (strcmp(_line, "HEAD") == 0)
    _method = Method::HEAD;
  else if (strcmp(_line, "PUT") == 0)
    _method = Method::PUT;
  else
    _method = Method::OUTRO;

  char *target = space + 1;
  char *second = strchr(target, ' ');
  if (second)
    *second = '\0';

  if (strcmp(target, "/") == 0 || strcmp(target, "/index.html") == 0) {
    _route = Route::RAIZ;
    return;
  }
  if (strcmp(target, "/controle") == 0) {
    _route = Route::CONTROLE;
    return;
  }
  if (strncmp(target, "/cmd/", 5) == 0) {
    _route = Route::COMANDO;
    sanitizeAction(target + 5, _acao, sizeof(_acao));
    return;
  }
  if (strncmp(target, "/upload/", 8) == 0) {
    _route = Route::UPLOAD;
    _pathError = sanitizePath(target + 8, _path, sizeof(_path));
    if (_pathError == PathError::OK) {
      partPath(_path, _part, sizeof(_part));
      baseName(_path, _name, sizeof(_name));
    }
    return;
  }
  _route = Route::DESCONHECIDA;
}

inline void FileTransfer::parseHeaderLine() {
  char *colon = strchr(_line, ':');
  if (!colon)
    return;
  *colon = '\0';
  char *value = colon + 1;
  while (isSpace(*value))
    ++value;
  const size_t nameLen = boundedLen(_line, LINE_CAP);

  if (nameLen == 13 && matchesToken(_line, "authorization", 13)) {
    _hasAuth = parseBasicAuth(value, _authUser, sizeof(_authUser), _authPass, sizeof(_authPass));
    return;
  }
  if (nameLen == 14 && matchesToken(_line, "content-length", 14)) {
    uint64_t n = 0;
    int digits = 0;
    for (const char *p = value; *p >= '0' && *p <= '9'; ++p) {
      n = n * 10 + uint64_t(*p - '0');
      if (++digits > 19 || n > MAX_FILE)
        return;
    }
    if (digits) {
      _length = n;
      _hasLength = true;
    }
    return;
  }
  if (nameLen == 5 && matchesToken(_line, "range", 5)) {
    uint64_t start = 0;
    if (parseRange(value, start)) {
      _offset = start;
      _hasOffset = true;
    }
    return;
  }
  // Rede de seguranca para o `Range` do fetch: ver decisao 7. Só e usado se o
  // `Range` nao chegou, para que o cabecalho padrao continue mandando.
  if (nameLen == 15 && matchesToken(_line, "x-upload-offset", 15) && !_hasOffset) {
    uint64_t n = 0;
    int digits = 0;
    for (const char *p = value; *p >= '0' && *p <= '9'; ++p) {
      n = n * 10 + uint64_t(*p - '0');
      if (++digits > 19 || n > MAX_FILE)
        return;
    }
    if (digits) {
      _offset = n;
      _hasOffset = true;
    }
  }
}

inline bool FileTransfer::authorized() const {
  if (!_hasAuth)
    return false;
  // Os dois lados sao comparados sempre, sem curto-circuito entre eles, para
  // nao vazar por tempo se foi o usuario ou a senha que errou.
  const bool userOk = secretEquals("m5retro", _authUser);
  const bool passOk = secretEquals(_password, _authPass);
  return userOk && passOk;
}

inline void FileTransfer::finishHeaders() {
  if (!authorized()) {
    respond(401, "Unauthorized", "text/plain", "autenticacao necessaria",
            "WWW-Authenticate: Basic realm=\"M5 RETRO TV\"\r\n");
    return;
  }
  if (_route == Route::RAIZ) {
    if (_method == Method::GET || _method == Method::HEAD)
      respondPage(_method == Method::GET);
    else
      respond(405, "Method Not Allowed", "text/plain", "use GET /");
    return;
  }
  if (_route == Route::CONTROLE) {
    if (!_cmd) {
      respond(404, "Not Found", "text/plain", "controle remoto desligado");
      return;
    }
    if (_method == Method::GET || _method == Method::HEAD)
      respondControl(_method == Method::GET);
    else
      respond(405, "Method Not Allowed", "text/plain", "use GET /controle");
    return;
  }
  if (_route == Route::COMANDO) {
    if (!_cmd) {
      respond(404, "Not Found", "text/plain", "controle remoto desligado");
      return;
    }
    // PUT, e nao GET: o comando muda o estado do aparelho. Um GET seria
    // disparado por qualquer pre-busca do navegador.
    if (_method != Method::PUT) {
      respond(405, "Method Not Allowed", "text/plain", "use PUT /cmd/<acao>");
      return;
    }
    if (!_acao[0] || !_cmd(_acao, _cmdUser))
      respond(400, "Bad Request", "text/plain", "acao desconhecida");
    else
      respond(200, "OK", "text/plain", "ok");
    return;
  }
  if (_route != Route::UPLOAD) {
    respond(404, "Not Found", "text/plain", "rota desconhecida");
    return;
  }
  if (_pathError != PathError::OK) {
    respond(403, "Forbidden", "text/plain", pathErrorText(_pathError));
    return;
  }
  if (_method == Method::HEAD) {
    respondResume();
    return;
  }
  if (_method != Method::PUT) {
    respond(405, "Method Not Allowed", "text/plain", "use PUT /upload/<caminho>");
    return;
  }
  startBody();
}

inline uint32_t FileTransfer::partSize() {
  uint32_t size = 0;
  if (!sdTake(SD_WAIT_MS))
    return 0;
  File f = SD.open(_part, FILE_READ);
  if (f) {
    size = uint32_t(f.size());
    f.close();
  }
  sdGive();
  return size;
}

inline void FileTransfer::respondResume() {
  char extra[48];
  snprintf(extra, sizeof(extra), "X-Resume-Offset: %lu\r\n", (unsigned long)partSize());
  respond(200, "OK", "text/plain", "", extra);
}

inline void FileTransfer::startBody() {
  if (!_hasLength) {
    // Sem Content-Length nao da para saber onde o arquivo acaba. Aceitar
    // `Transfer-Encoding: chunked` exigiria um decodificador de pedacos e mais
    // estado, para nada: a pagina embutida sempre sabe o tamanho.
    respond(411, "Length Required", "text/plain", "informe Content-Length");
    return;
  }
  const uint64_t start = _hasOffset ? _offset : 0;
  const uint64_t expected = start + _length;
  if (expected > MAX_FILE) {
    respond(413, "Payload Too Large", "text/plain", "o FAT32 nao guarda arquivo de 4 GiB");
    return;
  }
  // Foto acima do teto de decodificacao nunca sera exibida (MAX_PHOTO espelha o
  // MAX_JPEG de src/main.cpp). Recusar ANTES de abrir o `.part` evita gravar
  // megabytes que so seriam descartados — e o caso comum, porque uma foto de
  // celular tem de 500 KB a 5 MB.
  if (isPhotoPath(_path) && !fitsPhotoBudget(expected)) {
    respond(413, "Payload Too Large", "text/plain",
            "foto acima de 128 KB: reduza para 320x240");
    return;
  }

  if (!sdTake(SD_WAIT_MS)) {
    respond(503, "Service Unavailable", "text/plain", "cartao ocupado");
    return;
  }
  // O SD do arduino-pico nao tem totalBytes()/usedBytes(); o espaco vem do
  // SDFS.info(). Num cartao grande a primeira chamada varre a FAT inteira (o
  // SdFat guarda a contagem depois), entao pode segurar o sdMutex por um
  // instante — uma vez por arquivo, nao por bloco.
  FSInfo info;
  const bool infoOk = SDFS.info(info);
  sdGive();
  if (!infoOk) {
    respond(503, "Service Unavailable", "text/plain", "cartao nao respondeu");
    return;
  }
  const uint64_t freeBytes = info.totalBytes > info.usedBytes ? info.totalBytes - info.usedBytes : 0;
  if (!fitsOnCard(freeBytes, _length, RESERVE)) {
    respond(507, "Insufficient Storage", "text/plain", "sem espaco no cartao");
    return;
  }

  if (!sdTake(SD_WAIT_MS)) {
    respond(503, "Service Unavailable", "text/plain", "cartao ocupado");
    return;
  }
  char scratch[PATH_CAP];
  const bool dirs = ensureParents(SD, _path, scratch, sizeof(scratch));
  uint32_t existing = 0;
  if (dirs) {
    File probe = SD.open(_part, FILE_READ);
    if (probe) {
      existing = uint32_t(probe.size());
      probe.close();
    }
  }
  sdGive();
  if (!dirs) {
    respond(500, "Internal Server Error", "text/plain", "nao criou a pasta no cartao");
    return;
  }

  if (start && existing != start) {
    // O cliente pediu para retomar de um ponto que nao e o fim do `.part`.
    // Gravar ali deixaria um buraco no arquivo; melhor dizer onde ele esta.
    char extra[48];
    snprintf(extra, sizeof(extra), "X-Resume-Offset: %lu\r\n", (unsigned long)existing);
    respond(416, "Range Not Satisfiable", "text/plain", "retome do offset informado", extra);
    return;
  }

  if (!sdTake(SD_WAIT_MS)) {
    respond(503, "Service Unavailable", "text/plain", "cartao ocupado");
    return;
  }
  // "a" continua no fim (retomada); "w" trunca (envio do zero). Modo em TEXTO
  // de proposito: no arduino-pico FILE_WRITE e O_APPEND (PORTING.md 3.7), e um
  // envio "do zero" por cima de um `.part` velho viraria anexo — o arquivo
  // final sairia com o lixo antigo na frente.
  _file = SD.open(_part, start ? "a" : "w");
  sdGive();
  if (!_file) {
    respond(500, "Internal Server Error", "text/plain", "nao abriu o arquivo temporario");
    return;
  }

  _received = start;
  _total = expected;
  _status = TransferStatus::RECEBENDO;
  _phase = Phase::CORPO;
  // A sobra do ultimo bloco do cabecalho ja e o comeco do corpo: vira o comeco
  // do acumulador. Bytes alem do Content-Length sao de um pedido seguinte que
  // este servidor nao atende (Connection: close) e ficam de fora.
  size_t leftover = _hdrLen > _hdrPos ? _hdrLen - _hdrPos : 0;
  if (uint64_t(leftover) > _length)
    leftover = size_t(_length);
  if (leftover)
    memmove(_buffer, _buffer + _hdrPos, leftover);
  _fill = leftover;
  _hdrPos = _hdrLen = 0;
  touch();
}

// Grava o acumulador no cartao. Toma e devolve o mutex POR BLOCO — nunca
// durante o arquivo inteiro. Mesma disciplina do runVideoBenchmark: segurar
// durante 45 MB mataria de fome a tarefa de audio. Se o mutex nao vier, aborta:
// os bytes ja sairam do socket e grava-los fora de ordem corromperia o arquivo.
// O `.part` continua com exatamente `_received` bytes, entao a retomada bate.
inline bool FileTransfer::flushFill() {
  if (!_fill)
    return true;
  if (!sdTake(SD_WAIT_MS)) {
    abortBody("cartao ocupado tempo demais");
    return false;
  }
  const size_t written = _file.write(_buffer, _fill);
  sdGive();
  if (written != _fill) {
    abortBody("escrita no cartao falhou");
    return false;
  }
  _received += written;
  _fill = 0;
  return true;
}

// O socket entrega no maximo 1500 B por vez (o buffer do WiFiNINA), mas o
// cartao quer blocos de 8 KiB (decisao 5): um bloco de 16 setores vai numa
// escrita multibloco do SDIO, e 1500 B desalinhados virariam varias escritas
// de setor avulso, bem mais lentas. Entao os pedacos do socket se acumulam em
// `_buffer` e o cartao so e tocado com bloco cheio ou no fim do arquivo.
inline bool FileTransfer::pumpBody() {
  const uint64_t remaining = _total - _received; // o que ainda nao esta no cartao
  if (uint64_t(_fill) >= remaining) {
    if (!flushFill())
      return false;
    completeBody();
    return false;
  }
  if (_fill == BLOCK && !flushFill())
    return false;

  size_t want = BLOCK - _fill;
  if (uint64_t(want) > remaining - _fill)
    want = size_t(remaining - _fill);
  const int got = netRead(_buffer + _fill, want);
  if (got <= 0) {
    const uint32_t now = millis();
    bool dead = expired();
    if (!dead && now - _aliveCheckMs >= ALIVE_CHECK_MS) {
      _aliveCheckMs = now;
      dead = !peerAlive();
    }
    if (dead) {
      // Salva o que ja chegou antes de largar: a retomada perde o minimo.
      if (flushFill())
        abortBody("conexao parou no meio");
    }
    return false;
  }
  _fill += size_t(got);
  touch();
  if (_fill == BLOCK || uint64_t(_fill) == remaining) {
    if (!flushFill())
      return false;
    if (_received >= _total) {
      completeBody();
      return false;
    }
  }
  return true;
}

inline void FileTransfer::completeBody() {
  uint32_t onCard = 0;
  bool installed = false;
  const char *rejected = NULL;
  if (sdTake(SD_WAIT_MS)) {
    _file.flush();
    onCard = uint32_t(_file.size());
    _file.close();
    _file = File();
    // So renomeia se o cartao tem exatamente o que foi prometido. Renomear um
    // arquivo curto e o unico jeito de o player receber um video pela metade.
    if (uint64_t(onCard) == _total) {
      // Foto: confere o cabecalho ANTES do rename. A leitura e do `.part` ja
      // fechado, e nao do fluxo: um cabecalho JPEG pode ficar depois de um EXIF
      // de dezenas de KB e nao cabe num unico pedaco do socket, enquanto aqui o
      // arquivo inteiro esta no cartao e um `read` de BLOCK bytes ve tudo o que
      // interessa. Reusa `_buffer` (PSRAM, ja alocado) — nenhum buffer novo.
      if (isPhotoPath(_path)) {
        size_t head = 0;
        File probe = SD.open(_part, FILE_READ);
        if (probe) {
          const int n = probe.read(_buffer, BLOCK);
          if (n > 0)
            head = size_t(n);
          probe.close();
        }
        rejected = jpegRejectText(inspectJpegHeader(_buffer, head));
        // Some com o `.part` recusado: deixa-lo ali faria a proxima tentativa
        // "retomar" um arquivo que o aparelho ja disse que nao abre.
        if (rejected)
          SD.remove(_part);
      }
      if (!rejected)
        installed = installFile(SD, _part, _path);
    }
    sdGive();
  }
  _phase = Phase::OCIOSA;

  if (rejected) {
    _status = TransferStatus::FALHA;
    _error = rejected; // literal em flash: sobrevive a saida desta funcao
    respond(415, "Unsupported Media Type", "text/plain", rejected);
    return;
  }
  if (!installed) {
    _status = TransferStatus::FALHA;
    _error = uint64_t(onCard) == _total ? "rename falhou" : "arquivo incompleto no cartao";
    respond(500, "Internal Server Error", "text/plain", _error);
    return;
  }
  ++_installed;
  _status = TransferStatus::CONCLUIDO;
  _error = "";
  respond(201, "Created", "text/plain", "ok");
}

inline void FileTransfer::abortBody(const char *reason) {
  _error = reason;
  _status = TransferStatus::FALHA;
  // discardPartial = false: o `.part` fica no cartao com o que ja chegou, que e
  // o que permite retomar com Range em vez de reenviar tudo.
  closeConnection(false);
}

inline void FileTransfer::respond(int code, const char *reason, const char *type, const char *body,
                                  const char *extra) {
  const size_t len = body ? strlen(body) : 0;
  char head[224];
  const int n = snprintf(head, sizeof(head),
                         "HTTP/1.1 %d %s\r\nConnection: close\r\nContent-Type: %s\r\n"
                         "Content-Length: %u\r\n%s\r\n",
                         code, reason, type, (unsigned)len, extra ? extra : "");
  bool ok = n > 0 &&
            netWriteAll((const uint8_t *)head, size_t(n) < sizeof(head) ? size_t(n) : sizeof(head) - 1);
  if (ok && len)
    netWriteAll((const uint8_t *)body, len);
  closeConnection(false);
}

inline void FileTransfer::respondControl(bool bodyToo) {
  const size_t len = sizeof(CONTROL_PAGE) - 1;
  char head[160];
  const int n = snprintf(head, sizeof(head),
                         "HTTP/1.1 200 OK\r\nConnection: close\r\nContent-Type: text/html\r\n"
                         "Content-Length: %u\r\n\r\n",
                         (unsigned)len);
  const bool ok = n > 0 && size_t(n) < sizeof(head) && netWriteAll((const uint8_t *)head, size_t(n));
  if (ok && bodyToo)
    netWriteAll((const uint8_t *)CONTROL_PAGE, len);
  closeConnection(false);
}

inline void FileTransfer::respondPage(bool bodyToo) {
  const size_t len = sizeof(TRANSFER_PAGE) - 1;
  char head[160];
  const int n = snprintf(head, sizeof(head),
                         "HTTP/1.1 200 OK\r\nConnection: close\r\nContent-Type: text/html\r\n"
                         "Content-Length: %u\r\n\r\n",
                         (unsigned)len);
  const bool ok = n > 0 && size_t(n) < sizeof(head) && netWriteAll((const uint8_t *)head, size_t(n));
  if (ok && bodyToo)
    netWriteAll((const uint8_t *)TRANSFER_PAGE, len);
  closeConnection(false);
}

} // namespace xfer
#endif // FILETRANSFER_NO_NETWORK

#pragma once
// ============================================================================
// TransferScreen — tela do modo "receber arquivo pelo Wi-Fi".
//
// Enquanto o aparelho esta servindo HTTP, esta tela e a unica coisa que ele
// mostra. Quem esta na frente da TV precisa LER dali o endereco, o usuario e a
// senha da sessao e digitar tudo num computador do outro lado da sala. Ou
// seja: e um cartaz, nao um painel de diagnostico. Dai a hierarquia do
// desenho, que e a regra que decide todo o resto deste arquivo:
//
//   1. endereco   — o dado que a pessoa precisa copiar primeiro, em fonte
//                   grossa (VcrFont 12x16) dentro de uma moldura ciano;
//   2. usuario/senha — tambem 12x16, porque tambem sao digitados;
//   3. estado     — faixa colorida, que se le pela cor mesmo antes do texto;
//   4. progresso  — nome do arquivo, porcentagem, barra e contagem de bytes;
//   5. rede e aviso — contexto, em corpo pequeno.
//
// Por que fontes diferentes por campo (nao e capricho):
//
//   * O endereco so tem digitos, ponto, dois-pontos e barra — nada que dependa
//     de caixa. Entao vai na VcrFont, que tem traco de 2 px constante e e a
//     unica que aguenta o borrao horizontal do NTSC (ver o cabecalho da
//     VcrFont.h). Ela desenha so em caixa alta, e isso aqui e inofensivo.
//   * Usuario e senha NAO podem passar pela VcrFont: a senha e gerada por
//     sessao e diferencia maiuscula de minuscula. Uma senha "aB7k" desenhada
//     como "AB7K" faria a pessoa digitar errado e culpar o aparelho. Esses dois
//     campos saem na Font0 do M5GFX em tamanho 2 — que tem exatamente a mesma
//     celula de 12x16 e traco de 2 px depois da escala, mas preserva a caixa.
//   * SSID, nome de arquivo e bytes saem em Font0 tamanho 1 quando nao couberem
//     grandes: e preferivel ler pequeno a ler truncado.
//
// Texto de fora (SSID, nome do arquivo, mensagem de erro) passa por
// ascii::normalize antes de chegar na tela. As fontes bitmap so tem ASCII e em
// UTF-8 cada letra acentuada sao dois bytes sem glifo — "Não" viraria "N  o".
//
// Geometria: tudo dentro de crt::SAFE_* (SafeArea.h), porque um tubo esconde
// ~7% de cada borda. So o fundo sangra ate a borda do raster. O cabecalho
// (HEAD_Y / HEAD_RULE_Y) e a faixa de rodape (BAR_Y / BAR_H) sao os mesmos das
// outras telas, para esta nao destoar.
//
// LCD e saida composta usam o MESMO desenho, nas mesmas coordenadas. O LCD do
// Core2 nao tem overscan e sobraria margem, mas duas geometrias para a mesma
// tela e justamente a armadilha 8 do AGENTS.md ("duas constantes descrevendo a
// mesma geometria"): elas divergem na primeira manutencao. No LCD isto aparece
// apenas como uma margem um pouco maior, que e o que drawInfo()/drawSettings()
// ja fazem hoje.
//
// Dependencias: LovyanGFX (fj/Gfx.h, vem pela VcrFont), SafeArea.h e Ascii.h. Nada de
// Arduino, WiFi, SD ou FreeRTOS: o destino e um LovyanGFX*, entao o mesmo
// header serve ao painel CVBS do aparelho e ao painel SDL do simulador.
//
// O modulo de transferencia em si (HTTP, cartao, senha de sessao) e de outro
// arquivo: esta tela recebe um State ja pronto e so desenha. Quem integra faz
// a ponte entre os dois.
//
// Compila em -std=gnu++11 (conferir com `make -C sim cxx11`).
// ============================================================================

#include "Ascii.h"
#include "SafeArea.h"
#include "VcrFont.h"

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

namespace xfer {

// ---------------------------------------------------------------------------
//  Estado exibido
// ---------------------------------------------------------------------------

// Estagio da sessao de transferencia. E o que escolhe a cor da faixa de estado
// e o que a area de progresso mostra.
enum class Stage : uint8_t {
  Waiting,   // servidor no ar, ninguem conectou ainda
  Receiving, // recebendo um arquivo agora
  Done,      // arquivo gravado no cartao
  Error      // falhou (sem espaco, conexao caiu, senha errada...)
};

// Rotulos padrao. Ficam aqui, e nao na LocalizationPTBR.h, porque este header
// nao pode depender de nada do firmware — mas todos sao sobrescreviveis pelo
// State, entao a integracao pode apontar para as strings de la.
constexpr const char *kTitle = "TRANSFERIR ARQUIVOS";
constexpr const char *kWarning = "RESTO DO APARELHO SUSPENSO";
// Enumera o que o aparelho aceita, porque essa e a duvida de quem esta parado
// na frente da TV com o computador aberto — "envie o arquivo no PC" nao dizia
// QUAL arquivo, e agora sao tres categorias (videos/, music/, fotos/).
//
// Curto de proposito: com 21 caracteres a dica ainda cabe em corpo grande na
// largura segura (21 x 12 = 252 px, contra os 272 de crt::SAFE_W). Uma frase
// mais longa cairia para a fonte fina e viraria um rodape ilegivel no meio da
// tela — 22 caracteres e o teto absoluto. ASCII sem acento: as fontes bitmap
// nao tem glifo para acentuado (AGENTS 2.7).
constexpr const char *kHint = "VIDEO, MUSICA E FOTOS";

struct State {
  // O que a pessoa digita no navegador, ja pronto: "http://192.168.0.12".
  // Nao inventamos o prefixo aqui — quem monta a string sabe se ha porta.
  const char *address = nullptr;
  const char *ssid = nullptr;     // rede em que o aparelho esta
  const char *user = nullptr;     // usuario do acesso HTTP
  const char *password = nullptr; // senha da sessao (caixa preservada!)

  Stage stage = Stage::Waiting;
  const char *fileName = nullptr; // arquivo em transito / recebido
  // Contagem de bytes. uint32_t basta: o limite de arquivo do FAT32 e 4 GiB-1,
  // que e exatamente o alcance deste tipo.
  uint32_t bytesReceived = 0;
  uint32_t bytesTotal = 0; // 0 = tamanho desconhecido (sem Content-Length)

  // Texto da faixa de estado. Nulo usa o rotulo padrao do estagio; e por aqui
  // que passa o detalhe do erro ("SEM ESPACO NO CARTAO").
  const char *statusText = nullptr;

  const char *title = kTitle;
  const char *warning = kWarning;      // aviso de que o aparelho esta suspenso
  const char *buttonLabel = nullptr;   // legenda do botao de sair, se houver
};

// ---------------------------------------------------------------------------
//  Cores — RGB565 escritas na mao, para o header nao depender das macros TFT_*
// ---------------------------------------------------------------------------

constexpr uint16_t kBg = 0x000F;     // azul-marinho, o mesmo das outras telas
constexpr uint16_t kPanel = 0x0018;  // azul do painel do endereco (um degrau
                                     // acima do fundo: em RGB332 o azul tem so
                                     // 2 bits, e estes dois caem em indices
                                     // diferentes — 0x0010 nao cairia)
constexpr uint16_t kInk = 0xFFFF;    // branco: valores
constexpr uint16_t kAccent = 0x07FF; // ciano: rotulos e molduras
constexpr uint16_t kDim = 0x8410;    // cinza: dica e texto secundario

// Cores dos estagios. Saturadas de proposito: em RGB332 (a profundidade do
// framebuffer composto) meio-tom vira banda, e a cor tem de ser reconhecivel
// do outro lado da sala antes de a pessoa ler a palavra.
constexpr uint16_t kWaitFill = 0x07FF; // ciano
constexpr uint16_t kRecvFill = 0xFFE0; // amarelo
constexpr uint16_t kDoneFill = 0x07E0; // verde
constexpr uint16_t kErrFill = 0xF800;  // vermelho

// ---------------------------------------------------------------------------
//  Geometria — colunas e linhas fixas dentro da area segura
// ---------------------------------------------------------------------------
namespace layout {

constexpr int kRowH = 16; // altura de uma linha de valor (a celula da VcrFont)

constexpr int kTitleY = crt::HEAD_Y;      // 18 — titulo, Font0 tamanho 2
constexpr int kRuleY = crt::HEAD_RULE_Y;  // 46 — regua ciano do cabecalho

constexpr int kNetY = 52;    // linha "REDE  <ssid>", corpo pequeno
constexpr int kNetH = 8;

constexpr int kAddrY = 62;   // painel do endereco
constexpr int kAddrH = 28;

constexpr int kUserY = 94;   // "USUARIO <valor>"
constexpr int kPassY = 114;  // "SENHA   <valor>"

constexpr int kStatusY = 136; // faixa colorida de estado
constexpr int kStatusH = 20;

constexpr int kFileY = 160;   // nome do arquivo + porcentagem
constexpr int kPctW = 56;     // reserva da porcentagem ("100%" = 48 px)

constexpr int kBarY = 180;    // barra de progresso
constexpr int kBarH = 12;

constexpr int kBytesY = 194;  // "RECEBIDO 1,2 MB / 4,6 MB", corpo pequeno
constexpr int kBytesH = 8;

// Coluna dos valores de REDE/USUARIO/SENHA. 54 px = o rotulo mais longo
// ("USUARIO", 42 px na Font0 tamanho 1) mais 12 de respiro. A coluna foi
// apertada ate aqui de proposito: cada pixel que sobra a esquerda e um
// caractere a mais de senha em corpo grande, e uma senha de sessao com 16
// caracteres so cabia grande depois disso.
constexpr int kLabelX = crt::SAFE_L;           // 24
constexpr int kValueX = crt::SAFE_L + 54;      // 78
constexpr int kValueW = crt::SAFE_R - kValueX; // 218 -> 18 caracteres grandes

// Faixa que drawProgress() repinta: do topo da faixa de estado ate o fim da
// linha de bytes. Exposta porque quem integra pode querer limpar a regiao por
// conta propria (numa transicao, por exemplo).
constexpr int kDynamicY = kStatusY;                        // 136
constexpr int kDynamicH = (kBytesY + kBytesH) - kStatusY;  // 66

// Quantos caracteres cabem em corpo grosso na largura segura. E o teto do
// endereco: "http://192.168.100.130" tem 22 e cabe raspando; com porta
// ("...:8080") ja nao cabe e o painel cai para a fonte fina, que e legivel de
// perto mas nao da poltrona. Quem monta a string faz bem em evitar a porta.
constexpr int kThickChars = crt::SAFE_W / vcrfont::CELL_W; // 22

static_assert(kTitleY >= crt::SAFE_T, "titulo escapa pelo topo da area segura");
static_assert(kBytesY + kBytesH <= crt::BAR_Y, "linha de bytes invade a faixa de rodape");
static_assert(crt::BAR_Y + crt::BAR_H <= crt::SAFE_B, "rodape escapa pela base da area segura");
static_assert(kValueX + kValueW <= crt::SAFE_R, "coluna de valores escapa pela direita");
static_assert(kThickChars >= 22, "endereco IPv4 sem porta nao cabe mais em corpo grosso");

// As linhas nao podem se encavalar. Sem isto, mexer em uma constante para
// ganhar 4 px desenha texto por cima de texto e so aparece no probe — se
// alguem lembrar de olhar o PNG.
static_assert(kRuleY < kNetY, "regua do cabecalho invade a linha da rede");
static_assert(kNetY + kNetH <= kAddrY, "linha da rede invade o painel do endereco");
static_assert(kAddrY + kAddrH <= kUserY, "painel do endereco invade a linha do usuario");
static_assert(kUserY + kRowH <= kPassY, "usuario invade a senha");
static_assert(kPassY + kRowH <= kStatusY, "senha invade a faixa de estado");
static_assert(kStatusY + kStatusH <= kFileY, "faixa de estado invade a linha do arquivo");
static_assert(kFileY + kRowH <= kBarY, "linha do arquivo invade a barra");
static_assert(kBarY + kBarH <= kBytesY, "barra invade a linha de bytes");

} // namespace layout

// ---------------------------------------------------------------------------
//  Utilitarios internos
// ---------------------------------------------------------------------------
namespace detail {

// Metrica da Font0 do M5GFX (GLCDfont 6x8). Usada direto, em vez de
// gfx->textWidth(), para o calculo nao depender de qual fonte o chamador
// deixou ativa — draw() fixa a Font0 antes de qualquer medida.
constexpr int kM5W = 6;
constexpr int kM5H = 8;

// Buffer de texto normalizado. 64 bytes cobrem o pior caso util: um SSID tem no
// maximo 32 caracteres e um nome de arquivo maior que isso ja sai truncado de
// qualquer jeito. Pequeno de proposito — a pilha do loopTask e 8 KB e o
// AGENTS.md conta duas travadas causadas por array grande em pilha (2.3).
constexpr size_t kBuf = 64;

// Normaliza para ASCII no buffer do chamador. Nulo vira string vazia, para o
// resto do desenho nao precisar testar ponteiro a cada linha.
inline const char *norm(char *dst, size_t cap, const char *src) {
  if (!cap)
    return "";
  if (!src) {
    dst[0] = 0;
    return dst;
  }
  ascii::normalize(dst, cap, src);
  return dst;
}

// Desenha na Font0 escolhendo o maior tamanho (<= maxSize) que couber em `w` e,
// se nem o tamanho 1 couber, trunca com "..." no fim. Centraliza verticalmente
// na faixa de altura `h`, para que cair de tamanho 2 para 1 nao desalinhe a
// linha. Devolve a largura consumida.
inline int drawFine(LovyanGFX *gfx, const char *s, int x, int y, int w, int h, int32_t ink,
                    int maxSize) {
  if (!gfx || !s || !*s)
    return 0;
  int len = (int)strlen(s);
  int size = maxSize;
  while (size > 1 && len * kM5W * size > w)
    --size;

  char cut[kBuf];
  const int maxChars = w / (kM5W * size);
  if (len > maxChars) {
    // Trunca com reticencias: um nome de arquivo cortado em seco parece nome
    // de arquivo, e a pessoa procura no computador um arquivo que nao existe.
    int keep = maxChars - 3;
    if (keep < 1)
      keep = maxChars > 0 ? maxChars : 0;
    if (keep > (int)kBuf - 4)
      keep = (int)kBuf - 4;
    memcpy(cut, s, (size_t)keep);
    cut[keep] = 0;
    if (maxChars >= 4)
      strncat(cut, "...", kBuf - strlen(cut) - 1);
    s = cut;
    len = (int)strlen(s);
  }

  gfx->setFont(&fonts::Font0);
  gfx->setTextSize((uint8_t)size);
  gfx->setTextDatum(lgfx::textdatum::top_left);
  gfx->setTextColor(ink); // fore == back no LovyanGFX significa fundo transparente
  gfx->drawString(s, x, y + (h - kM5H * size) / 2);
  gfx->setTextSize(1);
  return len * kM5W * size;
}

// Texto grosso: VcrFont 12x16 quando couber, senao a Font0 pequena, que cabe o
// dobro de caracteres. Degradar para a fonte fina e melhor que truncar um dado
// que a pessoa precisa copiar.
inline void drawThick(LovyanGFX *gfx, const char *s, int x, int y, int w, int h, int32_t ink) {
  if (!gfx || !s || !*s)
    return;
  if (vcrfont::textWidth(s) <= w) {
    vcrfont::drawText(gfx, s, x, y + (h - vcrfont::textHeight()) / 2, ink);
    return;
  }
  drawFine(gfx, s, x, y, w, h, ink, 1);
}

// Idem, centralizado na faixa [x, x + w).
inline void drawThickCentered(LovyanGFX *gfx, const char *s, int x, int y, int w, int h, int32_t ink) {
  if (!gfx || !s || !*s)
    return;
  const int tw = vcrfont::textWidth(s);
  if (tw <= w) {
    vcrfont::drawText(gfx, s, x + (w - tw) / 2, y + (h - vcrfont::textHeight()) / 2, ink);
    return;
  }
  const int len = (int)strlen(s);
  const int fw = len * kM5W;
  drawFine(gfx, s, x + (w > fw ? (w - fw) / 2 : 0), y, w, h, ink, 1);
}

// Bytes em unidade legivel, com uma casa decimal e virgula (pt-BR).
// Aritmetica inteira: %f no newlib-nano do ESP32 depende de flag de link e ja
// imprimiu lixo neste projeto; e a divisao por 1024 aqui e um shift.
inline void formatBytes(char *dst, size_t cap, uint32_t b) {
  if (b < 1024u) {
    snprintf(dst, cap, "%lu B", (unsigned long)b);
  } else if (b < 1024u * 1024u) {
    snprintf(dst, cap, "%lu,%lu KB", (unsigned long)(b >> 10), (unsigned long)(((b & 1023u) * 10u) >> 10));
  } else if (b < 1024u * 1024u * 1024u) {
    const uint32_t k = b >> 10;
    snprintf(dst, cap, "%lu,%lu MB", (unsigned long)(k >> 10), (unsigned long)(((k & 1023u) * 10u) >> 10));
  } else {
    const uint32_t m = b >> 20;
    snprintf(dst, cap, "%lu,%lu GB", (unsigned long)(m >> 10), (unsigned long)(((m & 1023u) * 10u) >> 10));
  }
}

// Rotulo padrao de cada estagio.
inline const char *stageLabel(Stage stage) {
  return stage == Stage::Waiting     ? "AGUARDANDO CONEXAO"
         : stage == Stage::Receiving ? "RECEBENDO ARQUIVO"
         : stage == Stage::Done      ? "CONCLUIDO"
                                     : "ERRO NA TRANSFERENCIA";
}

inline uint16_t stageFill(Stage stage) {
  return stage == Stage::Waiting     ? kWaitFill
         : stage == Stage::Receiving ? kRecvFill
         : stage == Stage::Done      ? kDoneFill
                                     : kErrFill;
}

// Tinta sobre a faixa: marinho sobre ciano/amarelo/verde (claros) e branco
// sobre vermelho (escuro). O criterio e luminancia, nao gosto.
inline uint16_t stageTextInk(Stage stage) {
  return stage == Stage::Error ? kInk : kBg;
}

} // namespace detail

// Porcentagem concluida, ou -1 quando nao da para saber (sem tamanho total).
// Publica porque a integracao costuma querer o mesmo numero no log serial.
inline int percent(const State &s) {
  if (s.stage == Stage::Done)
    return 100; // concluido sem Content-Length ainda e 100%
  if (!s.bytesTotal)
    return -1;
  // 64 bits no meio do caminho: bytesReceived * 100 estoura 32 bits a partir de
  // 43 MB, e um arquivo de video passa disso na primeira tentativa.
  uint64_t p = ((uint64_t)s.bytesReceived * 100u) / s.bytesTotal;
  if (p > 100u)
    p = 100u;
  return (int)p;
}

// ---------------------------------------------------------------------------
//  Desenho
// ---------------------------------------------------------------------------

// Parte que nao muda durante a sessao: cabecalho, rede, endereco, credenciais e
// a faixa de rodape com o aviso. Separada de drawProgress() porque a senha e o
// endereco nao mudam enquanto a tela existe, e repintar tudo a cada pacote
// recebido faria a tela piscar na TV.
inline void drawStatic(LovyanGFX *gfx, const State &s) {
  if (!gfx)
    return;
  char buf[detail::kBuf];
  using namespace layout;

  // Cabecalho, igual ao das outras telas.
  gfx->setFont(&fonts::Font0);
  gfx->setTextDatum(lgfx::textdatum::top_left);
  gfx->setTextSize(2);
  gfx->setTextColor(kInk);
  gfx->drawString(detail::norm(buf, sizeof(buf), s.title ? s.title : kTitle), crt::SAFE_L, kTitleY);
  gfx->setTextSize(1);
  gfx->drawFastHLine(crt::SAFE_L, kRuleY, crt::SAFE_W, kAccent);

  // Rede: contexto, nao dado a copiar — fica pequeno de proposito.
  detail::drawFine(gfx, "REDE", kLabelX, kNetY, kValueX - kLabelX, kNetH, kAccent, 1);
  detail::drawFine(gfx, detail::norm(buf, sizeof(buf), s.ssid), kValueX, kNetY, kValueW, kNetH, kInk, 1);

  // Painel do endereco: o unico elemento com moldura, porque e o unico que a
  // pessoa procura na tela antes de ler qualquer outra coisa.
  gfx->fillRect(crt::SAFE_L, kAddrY, crt::SAFE_W, kAddrH, kPanel);
  gfx->drawRect(crt::SAFE_L, kAddrY, crt::SAFE_W, kAddrH, kAccent);
  detail::drawThickCentered(gfx, detail::norm(buf, sizeof(buf), s.address), crt::SAFE_L + 2, kAddrY + 1,
                            crt::SAFE_W - 4, kAddrH - 2, kInk);

  // Usuario e senha: valores na Font0 tamanho 2, que preserva maiuscula e
  // minuscula. A senha e gerada por sessao; desenha-la em caixa alta seria
  // entregar uma senha errada.
  detail::drawFine(gfx, "USUARIO", kLabelX, kUserY, kValueX - kLabelX, kRowH, kAccent, 1);
  detail::drawFine(gfx, detail::norm(buf, sizeof(buf), s.user), kValueX, kUserY, kValueW, kRowH, kInk, 2);
  detail::drawFine(gfx, "SENHA", kLabelX, kPassY, kValueX - kLabelX, kRowH, kAccent, 1);
  detail::drawFine(gfx, detail::norm(buf, sizeof(buf), s.password), kValueX, kPassY, kValueW, kRowH, kInk,
                   2);

  // Rodape: mesma faixa das legendas das outras telas. Aqui ela carrega o aviso
  // de que o aparelho esta suspenso — a legenda do botao entra no mesmo texto
  // quando existe, porque 20 px nao comportam duas linhas.
  gfx->fillRect(0, crt::BAR_Y, crt::W, crt::BAR_H, kBg);
  char foot[detail::kBuf * 2];
  char warn[detail::kBuf];
  detail::norm(warn, sizeof(warn), s.warning ? s.warning : kWarning);
  if (s.buttonLabel && *s.buttonLabel) {
    char btn[detail::kBuf];
    detail::norm(btn, sizeof(btn), s.buttonLabel);
    snprintf(foot, sizeof(foot), "[ %s ]  %s", btn, warn);
    // Nao cabendo os dois, o aviso tem prioridade: a legenda do botao a pessoa
    // descobre apertando, o aviso nao.
    if ((int)strlen(foot) * detail::kM5W > crt::SAFE_W)
      snprintf(foot, sizeof(foot), "%s", warn);
  } else {
    snprintf(foot, sizeof(foot), "%s", warn);
  }
  const int fw = (int)strlen(foot) * detail::kM5W;
  detail::drawFine(gfx, foot, crt::SAFE_L + (fw < crt::SAFE_W ? (crt::SAFE_W - fw) / 2 : 0), crt::BAR_Y,
                   crt::SAFE_W, crt::BAR_H, kAccent, 1);
}

// Parte viva: faixa de estado, nome do arquivo, porcentagem, barra e bytes.
// Repinta o proprio fundo, entao pode ser chamada sozinha a cada atualizacao do
// progresso sem piscar o resto da tela.
inline void drawProgress(LovyanGFX *gfx, const State &s) {
  if (!gfx)
    return;
  char buf[detail::kBuf];
  using namespace layout;

  // O fundo sangra ate a borda do raster (regra da area segura: so o conteudo
  // fica dentro da caixa), entao a limpeza vai de x=0 a x=W.
  gfx->fillRect(0, kDynamicY, crt::W, kDynamicH, kBg);

  // Faixa de estado. A cor e o primeiro sinal: da para saber de longe que algo
  // deu errado sem conseguir ler a palavra "ERRO".
  const uint16_t fill = detail::stageFill(s.stage);
  gfx->fillRect(crt::SAFE_L, kStatusY, crt::SAFE_W, kStatusH, fill);
  detail::drawThickCentered(gfx, detail::norm(buf, sizeof(buf), s.statusText ? s.statusText
                                                                             : detail::stageLabel(s.stage)),
                            crt::SAFE_L + 2, kStatusY, crt::SAFE_W - 4, kStatusH,
                            detail::stageTextInk(s.stage));

  const int pct = percent(s);

  // Linha do arquivo: nome a esquerda, porcentagem grossa a direita. A
  // porcentagem fica fora da faixa de estado para sobreviver a um statusText
  // personalizado (mensagem de erro, por exemplo).
  if (s.stage == Stage::Waiting) {
    // Sem arquivo ainda: uma dica apagada ocupa o lugar, para a metade de baixo
    // da tela nao parecer defeito.
    detail::drawFine(gfx, kHint, crt::SAFE_L, kFileY, crt::SAFE_W, kRowH, kDim, 2);
  } else {
    detail::drawThick(gfx, detail::norm(buf, sizeof(buf), s.fileName), crt::SAFE_L, kFileY,
                      crt::SAFE_W - kPctW - 8, kRowH, kInk);
    if (pct >= 0) {
      char pctText[8];
      snprintf(pctText, sizeof(pctText), "%d%%", pct);
      const int pw = vcrfont::textWidth(pctText);
      vcrfont::drawText(gfx, pctText, crt::SAFE_R - pw, kFileY, fill);
    }
  }

  // Barra: moldura sempre, para o lugar do progresso existir antes de haver
  // progresso. O miolo tem 2 px de folga de cada lado, senao o preenchimento
  // encosta na moldura e some em RGB332.
  gfx->drawRect(crt::SAFE_L, kBarY, crt::SAFE_W, kBarH, kAccent);
  const int inner = crt::SAFE_W - 4;
  if (pct > 0) {
    int w = (inner * pct) / 100;
    if (w < 1)
      w = 1; // 1% tem de aparecer; zero px passaria por "nao comecou"
    gfx->fillRect(crt::SAFE_L + 2, kBarY + 2, w, kBarH - 4, fill);
  }

  // Bytes: a unica linha da tela que sobrou em corpo pequeno (8 px de altura
  // entre a barra e a faixa de rodape). Sai em branco, e nao no cinza da dica,
  // porque 6x8 em cinza sobre marinho nao sobrevive ao borrao do NTSC. Sem
  // total conhecido, mostra so o que ja chegou — inventar um total seria mentir
  // sobre o prazo.
  if (s.stage != Stage::Waiting) {
    char got[24], all[24];
    detail::formatBytes(got, sizeof(got), s.bytesReceived);
    if (s.bytesTotal) {
      detail::formatBytes(all, sizeof(all), s.bytesTotal);
      snprintf(buf, sizeof(buf), "RECEBIDO %s / %s", got, all);
    } else {
      snprintf(buf, sizeof(buf), "RECEBIDO %s", got);
    }
    detail::drawFine(gfx, buf, crt::SAFE_L, kBytesY, crt::SAFE_W, kBytesH, kInk, 1);
  }
}

// Tela inteira. O fillScreen sangra ate a borda do raster de proposito: tarja
// preta em volta faria a imagem parecer pequena no tubo (SafeArea.h).
inline void draw(LovyanGFX *gfx, const State &s) {
  if (!gfx)
    return;
  gfx->fillScreen(kBg);
  drawStatic(gfx, s);
  drawProgress(gfx, s);
  // Deixa o contexto de texto num estado conhecido: varias telas do firmware
  // desenham logo depois assumindo tamanho 1 e datum top_left.
  gfx->setTextSize(1);
  gfx->setTextDatum(lgfx::textdatum::top_left);
}

} // namespace xfer

#pragma once
// ============================================================================
// ChannelMode.h — "modo canal" (reproducao continua) e timer de soneca.
//
// Duas pecas que transformam o player de arquivos num aparelho de TV:
//
//   1. channel::Channel   — quando um programa acaba, o proximo entra sozinho,
//                           com uma vinheta curta ("A SEGUIR") no meio. E o que
//                           separa "abrir um arquivo" de "ligar um canal".
//   2. sleeptimer::SleepTimer — o SLEEP do videocassete: 15/30/60/90/120 min e
//                           o aparelho se desliga. Quem dorme na frente da TV
//                           nao levanta para apertar nada.
//
// ---------------------------------------------------------------------------
// O que este header NAO faz (de proposito)
// ---------------------------------------------------------------------------
//
// * Nao varre o cartao SD. A biblioteca ja existe em src/main.cpp
//   (scanLibrary / libraryProgramCount / libraryProgramAt) e re-implementar
//   isso aqui seria a armadilha 8 do AGENTS.md — duas coisas descrevendo o
//   mesmo estado, divergindo na primeira manutencao. O Channel guarda so
//   INDICES e pede o caminho ao chamador por um ponteiro de funcao.
// * Nao abre, fecha nem toca nada. Ele devolve "toque o indice N agora"; quem
//   chama o startProgram() continua sendo o loop().
// * Nao desliga o aparelho. O SleepTimer so responde `expired()`.
//
// ---------------------------------------------------------------------------
// Restricoes respeitadas (ver AGENTS.md secao 2)
// ---------------------------------------------------------------------------
//
// * C++11 (-std=gnu++11). Nenhum constexpr com laco ou variavel local — foi
//   isso que quebrou a VcrFont.h uma vez. As tabelas pequenas sao arrays locais
//   de funcao inline, que o compilador resolve sem exigir C++14.
// * SRAM. O objeto Channel inteiro cabe em ~90 bytes: a ordem embaralhada e um
//   array de 64 uint8_t (indices, nao ponteiros, nao String). Nenhum sprite —
//   um sprite de 5 KB ja causou falta de memoria neste projeto, e a vinheta e
//   desenhada direto no painel.
// * Texto ASCII e sem acento. O nome da pasta vem do cartao, entao passa por
//   ascii::normalizeUpper antes de ir para a tela.
// * Nada de ciano saturado (0x07FF): o dot crawl do NTSC faz aquilo tremer. O
//   acento e o 0x96BC que o resto do firmware ja usa.
// * Tudo dentro de crt::SAFE_* (SafeArea.h); so o fundo sangra ate a borda do
//   raster, sem tarja preta.
// * Prazo com millis(): TODA conta de tempo passa por timeReached() (UiLogic.h),
//   que compara a diferenca com sinal. millis() da a volta em ~49 dias e
//   `now > deadline` cru trava o timer para sempre quando isso acontece.
//
// Dependencias: LovyanGFX (fj/Gfx.h, vem pela VcrFont), SafeArea.h, UiLogic.h, Ascii.h.
// Nada de Arduino, SD, WiFi ou FreeRTOS: o destino e um lgfx::LovyanGFX*, entao
// o mesmo header serve ao painel CVBS do aparelho e ao painel SDL do simulador.
//
// Bancada: sim/probes/channel_mode.cpp.
// ============================================================================

#include "Ascii.h"
#include "SafeArea.h"
#include "UiLogic.h" // timeReached()
#include "VcrFont.h" // traz a LovyanGFX (fj/Gfx.h) junto

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>

namespace channel {

// Acento seguro na saida composta. TFT_CYAN (0x07FF) esta proibido aqui: a
// crominancia saturada do NTSC produz dot crawl visivel em borda de texto.
constexpr uint16_t kAccent = 0x96BC;

// Mesmo teto de MAX_LIBRARY_ITEMS em src/main.cpp. Cabe em uint8_t de
// proposito: a permutacao do modo aleatorio e um array de 64 bytes.
constexpr int MAX_ITEMS = 64;

// Duracao padrao da vinheta entre programas. Curta: e respiro, nao intervalo.
constexpr uint32_t kDefaultBumperMs = 3000;

enum class Mode : uint8_t {
  Off = 0,        // comportamento atual: acabou o programa, volta para a lista
  Sequential = 1, // proximo da lista, dando a volta no fim
  Shuffle = 2     // permutacao sem repetir ate a lista esgotar
};

enum class Phase : uint8_t {
  Idle = 0,   // nada agendado
  Playing = 1,// um programa esta no ar
  Bumper = 2  // vinheta correndo; o proximo indice ja esta escolhido
};

// Como o Channel resolve um indice em caminho de pasta. O `user` e opaco: em
// src/main.cpp ele nem precisa ser usado, porque libraryProgramAt() e global.
typedef const char *(*PathFn)(int index, void *user);

// ---------------------------------------------------------------------------
//  Channel
// ---------------------------------------------------------------------------
//
// Ciclo de vida visto pelo chamador:
//
//   ch.attach(libraryProgramCount(), pathAdapter);   // ao entrar na biblioteca
//   ch.seed(millis());                               // semente da permutacao
//   ...
//   startProgram(p) deu certo  -> ch.started(index, millis());
//   playbackFinished           -> if (ch.finished(millis())) { desenha vinheta }
//                                 else { comportamento antigo: volta a lista }
//   a cada loop, em Bumper     -> ch.drawBumper(...); int n = ch.ready(millis());
//                                 if (n >= 0) startProgram(ch.pathAt(n));
//   startProgram falhou        -> if (!ch.failed(millis())) { volta a lista }
//   usuario apertou VOLTAR     -> ch.stop();
//
class Channel {
public:
  Channel()
      : pathFn_(0), user_(0), count_(0), cursor_(0), current_(-1), pending_(-1),
        failStreak_(0), mode_(Mode::Off), phase_(Phase::Idle), shuffled_(false),
        bumperMs_(kDefaultBumperMs), bumperStart_(0), bumperUntil_(0), rng_(1u), seed_(1u) {
    for (int i = 0; i < MAX_ITEMS; ++i)
      order_[i] = (uint8_t)i;
    paintDst_[0] = paintDst_[1] = 0;
    paintKey_[0] = paintKey_[1] = 0;
  }

  // -- playlist ------------------------------------------------------------

  // `count` e quantos programas a biblioteca listou; `fn` traduz indice em
  // caminho. Chamar de novo depois de re-varrer o cartao e barato.
  void attach(int count, PathFn fn, void *user = 0) {
    pathFn_ = fn;
    user_ = user;
    setCount(count);
  }

  void setCount(int count) {
    if (count < 0)
      count = 0;
    if (count > MAX_ITEMS)
      count = MAX_ITEMS;
    if (count == count_)
      return;
    count_ = count;
    shuffled_ = false; // a permutacao antiga nao vale mais
    if (current_ >= count_)
      current_ = -1;
    if (pending_ >= count_)
      pending_ = -1;
  }

  int count() const { return count_; }

  // Semente da permutacao. Deterministica de proposito: com a mesma semente a
  // ordem se repete, o que torna o modo aleatorio testavel numa bancada. Zero
  // nao serve como estado de LCG, entao vira 1.
  void seed(uint32_t s) {
    seed_ = s ? s : 1u;
    rng_ = seed_;
    shuffled_ = false;
  }

  const char *pathAt(int index) const {
    if (!pathFn_ || index < 0 || index >= count_)
      return 0;
    return pathFn_(index, user_);
  }

  const char *pendingPath() const { return pathAt(pending_); }

  // -- modo ----------------------------------------------------------------

  Mode mode() const { return mode_; }

  void setMode(Mode m) {
    if (m == mode_)
      return;
    mode_ = m;
    shuffled_ = false;
    if (mode_ == Mode::Off)
      stop();
  }

  // OFF -> SEQUENCIAL -> ALEATORIO -> OFF. Devolve o modo novo.
  Mode cycleMode() {
    setMode(mode_ == Mode::Off ? Mode::Sequential
            : mode_ == Mode::Sequential ? Mode::Shuffle
                                        : Mode::Off);
    return mode_;
  }

  // Rotulo ASCII para a tela de configuracoes.
  const char *modeLabel() const {
    return mode_ == Mode::Off ? "DESLIGADO" : mode_ == Mode::Sequential ? "EM ORDEM" : "ALEATORIO";
  }

  // -- vinheta -------------------------------------------------------------

  void setBumperMs(uint32_t ms) { bumperMs_ = ms; }
  uint32_t bumperMs() const { return bumperMs_; }

  Phase phase() const { return phase_; }
  bool bumperActive() const { return phase_ == Phase::Bumper; }
  int currentIndex() const { return current_; }
  int pendingIndex() const { return pending_; }

  // Quanto falta da vinheta, em ms. Sempre pela diferenca sem sinal — nunca
  // `deadline - now` cru sem antes checar timeReached, senao a volta do
  // millis() devolveria um numero gigante e a vinheta ficaria eterna.
  uint32_t bumperRemainingMs(uint32_t now) const {
    if (phase_ != Phase::Bumper || timeReached(now, bumperUntil_))
      return 0;
    return bumperUntil_ - now;
  }

  uint32_t bumperElapsedMs(uint32_t now) const {
    if (phase_ != Phase::Bumper)
      return 0;
    const uint32_t d = now - bumperStart_; // subtracao sem sinal: atravessa a volta
    return d > bumperMs_ ? bumperMs_ : d;
  }

  // -- transicoes ----------------------------------------------------------

  // O programa do indice `index` comecou a tocar de verdade.
  void started(int index, uint32_t now) {
    (void)now;
    current_ = (index >= 0 && index < count_) ? index : -1;
    pending_ = -1;
    failStreak_ = 0;
    phase_ = Phase::Playing;
    invalidateBumperPaint();
    // O usuario pode ter escolhido um titulo a dedo na biblioteca no meio de
    // uma rodada aleatoria. Puxar esse titulo para a posicao do cursor mantem a
    // promessa de nao repetir ninguem ate a lista esgotar.
    if (mode_ == Mode::Shuffle && shuffled_ && current_ >= 0 && cursor_ < count_ &&
        order_[cursor_] != (uint8_t)current_) {
      for (int i = cursor_; i < count_; ++i) {
        if (order_[i] == (uint8_t)current_) {
          const uint8_t t = order_[i];
          order_[i] = order_[cursor_];
          order_[cursor_] = t;
          break;
        }
      }
    }
  }

  // O programa acabou (chamar quando playbackFinished e nao houve erro de
  // midia). Devolve true quando o canal assumiu: o proximo indice ja esta
  // escolhido e a vinheta comecou — o chamador NAO deve voltar para a
  // biblioteca. Devolve false quando o comportamento antigo vale (modo
  // desligado, lista vazia ou programas demais falhando em sequencia).
  bool finished(uint32_t now) {
    if (mode_ == Mode::Off || count_ <= 0) {
      stop();
      return false;
    }
    // Portao contra laco apertado (armadilha 4 do AGENTS.md): um cartao cheio
    // de pastas quebradas nao pode fazer o aparelho girar a lista para sempre.
    if (failStreak_ > count_) {
      stop();
      return false;
    }
    const int next = nextIndex();
    if (next < 0) {
      stop();
      return false;
    }
    pending_ = next;
    bumperStart_ = now;
    bumperUntil_ = now + bumperMs_;
    phase_ = Phase::Bumper;
    invalidateBumperPaint();
    return true;
  }

  // Acabou a vinheta? Devolve o indice a tocar agora, ou -1 enquanto nao for a
  // hora. Depois de devolver um indice, ele nao volta a ser devolvido.
  int ready(uint32_t now) {
    if (phase_ != Phase::Bumper || pending_ < 0)
      return -1;
    if (!timeReached(now, bumperUntil_))
      return -1;
    phase_ = Phase::Idle; // esperando o startProgram() do chamador
    // Ja adota o pendente como atual: se o start falhar, failed() avanca a
    // partir dele e nao tenta o mesmo de novo.
    current_ = pending_;
    return pending_;
  }

  // O startProgram() do indice devolvido por ready() falhou. Reagenda o
  // seguinte; devolve false quando ja tentou a lista inteira sem sucesso.
  bool failed(uint32_t now) {
    ++failStreak_;
    return finished(now);
  }

  // Cancelamento explicito (usuario saiu do player, erro de midia, entrou
  // outra tela). Nao mexe no modo: o canal volta a valer no proximo programa.
  void stop() {
    phase_ = Phase::Idle;
    pending_ = -1;
    failStreak_ = 0;
    invalidateBumperPaint();
  }

  // -- desenho da vinheta --------------------------------------------------

  // Cartao "A SEGUIR" + titulo do proximo programa + barra de progresso da
  // vinheta. `nextTitle` pode ser 0: o titulo sai do caminho pendente.
  //
  // Repintura: o cartao inteiro so e pintado na primeira chamada de cada
  // vinheta e para cada destino (LCD e CVBS sao dois destinos). Nas chamadas
  // seguintes so a barra cresce. Nao e micro-otimizacao: repintar o fundo a
  // cada quadro deixaria o texto ausente do framebuffer nos microssegundos em
  // que o DMA do I2S0 varre aquelas linhas, e isso pisca na TV.
  void drawBumper(lgfx::LovyanGFX *dst, int ox, int oy, const char *nextTitle, uint32_t now) {
    if (!dst || phase_ != Phase::Bumper)
      return;

    char derived[kTitleCap];
    if (!nextTitle) {
      titleOf(pending_, derived, sizeof(derived));
      nextTitle = derived;
    }

    const int barX = crt::SAFE_L, barW = crt::SAFE_W;
    const int barY = crt::SAFE_B - 28, barH = 8;

    if (needsFullPaint(dst)) {
      // O fundo pode sangrar ate a borda do raster; o conteudo, nao.
      dst->fillRect(ox, oy, crt::W, crt::H, TFT_BLACK);
      vcrfont::drawTextCentered(dst, "A SEGUIR", ox + crt::SAFE_L, oy + crt::HEAD_Y, crt::SAFE_W,
                                kAccent);
      dst->drawFastHLine(ox + crt::SAFE_L, oy + crt::HEAD_RULE_Y, crt::SAFE_W, kAccent);
      drawTitle(dst, ox, oy, nextTitle);
      dst->drawRect(ox + barX, oy + barY, barW, barH, kAccent);
      vcrfont::drawTextCentered(dst, "M5 RETRO TV", ox + crt::SAFE_L, oy + crt::SAFE_B - 16,
                                crt::SAFE_W, kDim);
    }

    // A barra so cresce da esquerda para a direita: nunca apaga pixel, entao
    // repintar nao produz cintilacao.
    const uint32_t span = bumperMs_ ? bumperMs_ : 1u;
    const int inner = barW - 2;
    int fill = (int)((uint32_t)inner * bumperElapsedMs(now) / span);
    if (fill > inner)
      fill = inner;
    if (fill > 0)
      dst->fillRect(ox + barX + 1, oy + barY + 1, fill, barH - 2, kAccent);
  }

  // Forca a proxima drawBumper() a repintar o cartao inteiro. Use ao voltar
  // para a tela depois de outra coisa ter escrito por cima.
  void invalidateBumperPaint() {
    paintDst_[0] = paintDst_[1] = 0;
    paintKey_[0] = paintKey_[1] = 0;
  }

  // Titulo ASCII de um indice, a partir do ultimo segmento do caminho. Devolve
  // false (e escreve string vazia) quando nao ha caminho.
  bool titleOf(int index, char *out, size_t cap) const {
    if (!out || cap == 0)
      return false;
    out[0] = '\0';
    const char *path = pathAt(index);
    if (!path)
      return false;
    const char *base = path;
    for (const char *p = path; *p; ++p)
      if (*p == '/' || *p == '\\')
        base = p + 1;
    if (!*base)
      base = path;
    // Texto vindo do cartao: sem normalizar, um acento vira dois buracos.
    ascii::normalizeUpper(out, cap, base);
    return out[0] != '\0';
  }

private:
  static constexpr int kTitleCap = 25;  // 22 celulas de 12 px cabem em SAFE_W
  static constexpr uint16_t kDim = 0x8410; // cinza medio, luminancia segura

  // LCG de 32 bits (Numerical Recipes). Nada de rand(): a libc do ESP32 tem
  // estado global compartilhado com o resto do firmware e nao e reproduzivel
  // numa bancada.
  uint32_t nextRandom() {
    rng_ = rng_ * 1664525u + 1013904223u;
    return rng_;
  }

  // Sorteio em [0, n) pelos bits altos — o resto de um LCG tem periodo curto
  // nos bits baixos e produziria uma "aleatoriedade" que anda em ciclo.
  int below(int n) {
    if (n <= 1)
      return 0;
    return (int)(((uint64_t)nextRandom() * (uint32_t)n) >> 32);
  }

  // Fisher-Yates completo: a rodada e uma permutacao, entao ninguem se repete
  // antes de todo mundo ter tocado. `avoid` e o programa que acabou de sair,
  // que nao pode abrir a rodada seguinte (seria repeticao imediata na virada).
  void reshuffle(int avoid) {
    for (int i = 0; i < count_; ++i)
      order_[i] = (uint8_t)i;
    for (int i = count_ - 1; i > 0; --i) {
      const int j = below(i + 1);
      const uint8_t t = order_[i];
      order_[i] = order_[j];
      order_[j] = t;
    }
    if (count_ > 1 && avoid >= 0 && order_[0] == (uint8_t)avoid) {
      const uint8_t t = order_[0];
      order_[0] = order_[count_ - 1];
      order_[count_ - 1] = t;
    }
    cursor_ = 0;
    shuffled_ = true;
  }

  int nextIndex() {
    if (count_ <= 0)
      return -1;
    if (count_ == 1)
      return 0;
    if (mode_ == Mode::Shuffle) {
      if (!shuffled_)
        reshuffle(current_);
      else if (++cursor_ >= count_)
        reshuffle(current_); // lista esgotada: nova rodada
      return (int)order_[cursor_];
    }
    return current_ < 0 ? 0 : (current_ + 1) % count_;
  }

  // Titulo grande quando couber (24x32), pequeno quando nao. Truncar e melhor
  // do que deixar escapar da area segura.
  void drawTitle(lgfx::LovyanGFX *dst, int ox, int oy, const char *title) const {
    // Normaliza mesmo quando o titulo veio pronto do chamador: ele tambem pode
    // ter saido de um meta.json do cartao, e um acento em UTF-8 sao dois bytes
    // sem glifo — dois buracos, nao um (armadilha 9 do AGENTS.md).
    char buf[kTitleCap];
    int n = (int)ascii::normalizeUpper(buf, sizeof(buf), title ? title : "");
    int scale = 2;
    int maxChars = crt::SAFE_W / (vcrfont::CELL_W * 2); // 11
    if (n > maxChars) {
      scale = 1;
      maxChars = crt::SAFE_W / vcrfont::CELL_W; // 22
      if (n > maxChars) {
        // Reticencias: sem elas o corte parece nome de pasta errado, e nao
        // titulo que nao coube.
        buf[maxChars] = '\0';
        buf[maxChars - 1] = '.';
        buf[maxChars - 2] = '.';
      }
    }
    const int h = vcrfont::textHeight(scale);
    const int y = crt::SAFE_T + (crt::SAFE_H - h) / 2;
    vcrfont::drawTextCentered(dst, buf, ox + crt::SAFE_L, oy + y, crt::SAFE_W, TFT_WHITE, scale);
  }

  // Duas vagas: exatamente os dois destinos que existem (LCD e painel CVBS).
  bool needsFullPaint(const void *dst) {
    int slot = -1;
    for (int i = 0; i < 2; ++i)
      if (paintDst_[i] == dst)
        slot = i;
    if (slot < 0)
      for (int i = 0; i < 2 && slot < 0; ++i)
        if (paintDst_[i] == 0)
          slot = i;
    if (slot < 0)
      slot = 0; // mais de dois destinos: o terceiro so repinta, nunca erra
    const uint32_t key = bumperStart_ | 1u; // 0 fica reservado para "vazio"
    if (paintDst_[slot] == dst && paintKey_[slot] == key)
      return false;
    paintDst_[slot] = dst;
    paintKey_[slot] = key;
    return true;
  }

  PathFn pathFn_;
  void *user_;
  int count_;
  int cursor_;  // posicao atual dentro de order_ (modo aleatorio)
  int current_; // indice tocando agora, -1 se nenhum
  int pending_; // indice escolhido para depois da vinheta, -1 se nenhum
  int failStreak_;
  Mode mode_;
  Phase phase_;
  bool shuffled_;
  uint32_t bumperMs_;
  uint32_t bumperStart_;
  uint32_t bumperUntil_;
  uint32_t rng_;
  uint32_t seed_;
  uint8_t order_[MAX_ITEMS];
  const void *paintDst_[2];
  uint32_t paintKey_[2];
};

} // namespace channel

namespace sleeptimer {

// OFF / 15 / 30 / 60 / 90 / 120 — os mesmos degraus do SLEEP de um
// videocassete da epoca. Em minutos; 0 e "desligado".
constexpr int OPTION_COUNT = 6;

// Array local de funcao inline em vez de tabela no escopo do namespace: evita
// objeto com ligacao interna referenciado por funcao inline (e continua sendo
// C++11 — um constexpr com laco quebraria o firmware).
inline uint16_t optionAt(int i) {
  const uint16_t v[OPTION_COUNT] = {0, 15, 30, 60, 90, 120};
  return (i >= 0 && i < OPTION_COUNT) ? v[i] : 0;
}

class SleepTimer {
public:
  SleepTimer() : option_(0), start_(0), deadline_(0) {}

  bool active() const { return option_ != 0; }
  int option() const { return option_; }
  uint16_t minutes() const { return optionAt(option_); }

  void cancel() {
    option_ = 0;
    start_ = deadline_ = 0;
  }

  // Seleciona pelo indice da tabela e rearma a contagem.
  void setOption(int i, uint32_t now) {
    option_ = (uint8_t)((i >= 0 && i < OPTION_COUNT) ? i : 0);
    arm(now);
  }

  // Seleciona por valor em minutos. Valor fora da tabela desliga o timer —
  // melhor desligado do que com um prazo que a interface nao sabe mostrar.
  void setMinutes(uint16_t m, uint32_t now) {
    for (int i = 0; i < OPTION_COUNT; ++i) {
      if (optionAt(i) == m) {
        setOption(i, now);
        return;
      }
    }
    cancel();
  }

  // Proximo degrau, dando a volta. Devolve o valor novo em minutos (0 = OFF).
  uint16_t cycle(uint32_t now) {
    setOption((option_ + 1) % OPTION_COUNT, now);
    return minutes();
  }

  // Reinicia a contagem sem mudar o valor (o usuario mexeu em algo: nao e hora
  // de desligar na cara dele).
  void restart(uint32_t now) { arm(now); }

  // Venceu? Unico lugar que decide isso. timeReached() compara a DIFERENCA com
  // sinal: `now >= deadline` cru daria falso para sempre depois da volta do
  // millis(), e o aparelho nunca desligaria.
  bool expired(uint32_t now) const { return active() && timeReached(now, deadline_); }

  uint32_t remainingMs(uint32_t now) const {
    if (!active() || timeReached(now, deadline_))
      return 0;
    return deadline_ - now;
  }

  // Arredonda para cima: enquanto sobrar 1 s o mostrador diz "1", nunca "0".
  // Um "SLEEP 0" na tela por um minuto inteiro parece aparelho travado.
  uint16_t remainingMinutes(uint32_t now) const {
    return (uint16_t)((remainingMs(now) + 59999UL) / 60000UL);
  }

  uint32_t deadline() const { return deadline_; }

  // Indicador pequeno "SLEEP 30", alinhado a direita da area segura. Com
  // contorno preto por glifo (mesma ideia do VcrOsd) para continuar legivel
  // por cima da imagem, sem tarja de fundo.
  void drawBadge(lgfx::LovyanGFX *dst, int ox, int oy, uint32_t now, int y = crt::SAFE_T,
                 int32_t ink = (int32_t)channel::kAccent, int32_t outline = TFT_BLACK) const {
    if (!dst || !active())
      return;
    char text[16];
    snprintf(text, sizeof(text), "SLEEP %u", (unsigned)remainingMinutes(now));
    const int w = vcrfont::textWidth(text);
    vcrfont::drawText(dst, text, ox + crt::SAFE_R - w, oy + y, ink, 1, outline);
  }

private:
  void arm(uint32_t now) {
    start_ = now;
    // 120 min = 7.200.000 ms, folgado dentro dos 24,8 dias em que a
    // comparacao com sinal do timeReached() vale.
    deadline_ = now + (uint32_t)minutes() * 60000UL;
  }

  uint8_t option_;
  uint32_t start_;
  uint32_t deadline_;
};

} // namespace sleeptimer

#pragma once
// ============================================================================
//  PhotoShow — slideshow de fotos (.jpg/.jpeg) do cartão na saída composta.
//
//  Mostra uma foto por vez, centralizada no quadro de 320x240, avançando
//  sozinha num prazo configurável (3/5/10/30 s) e também pelos três botões.
//  A pasta é /M5RETRO/fotos.
//
//  ---------------------------------------------------------------------------
//  Regras deste aparelho que moldaram a API (ver AGENTS.md)
//  ---------------------------------------------------------------------------
//
//  1. A SRAM é o recurso escasso (o framebuffer CVBS já leva 150 KB e o heap
//     livre medido fica entre 28 e 38 KB). Por isso este header **não aloca
//     nada**, seguindo o mesmo contrato do ScreenFx.h:
//
//       * o buffer de decodificação é o `jpegBuffer` que o main.cpp já mantém
//         na PSRAM para o vídeo (128 KiB) — entra por `attachBuffer()`;
//       * a instância do JPEGDEC também é a do main.cpp (a JPEGIMAGE tem
//         dezenas de KB; duas não caberiam) — entra por `attachDecoder()`;
//       * o catálogo de nomes mora num "pool" fornecido pelo chamador
//         (`attachStorage()`), que pode ficar na PSRAM. Guardamos só o nome
//         curto de cada arquivo, nunca o caminho completo: o caminho é montado
//         num buffer de pilha, um de cada vez, na hora de abrir.
//
//     Nada de LGFX_Sprite aqui: um sprite de 5 KB já causou falta de memória
//     no Core2, e um de tela cheia (153.600 B em RGB565) não cabe na SRAM ao
//     lado do framebuffer.
//
//  2. Transições são as do include/ScreenFx.h — este arquivo não tem dither
//     próprio. **Achado importante**: `crossfade()` e `fadeIn()` exigem um
//     LGFX_Sprite 320x240 RGB565 do chamador e, recebendo `nullptr`, caem em
//     `hardCut()` — corte seco, sem nenhuma animação, devolvendo false. Já o
//     `fadeThrough()` com `nullptr` continua **visível**: ele esmaece até o
//     preto com o dither de Bayer (que não precisa de buffer nenhum) e só o
//     segundo tempo, o reacender, vira corte seco. Como o sprite é opcional,
//     `beginTransition()` usa `fadeThrough`. É de propósito.
//
//  3. `millis()` dá a volta em ~49 dias. O prazo usa `timeReached()` da
//     UiLogic.h (aritmética com sinal sobre a diferença), nunca `now > prazo`.
//
//  4. O cartão é disputado com a tarefa de áudio e é protegido pelo `sdMutex`
//     do main.cpp. **Este header nunca toma o mutex.** As duas únicas funções
//     que tocam o cartão — `scan()` e `load()` — estão marcadas com
//     "PRÉ-CONDIÇÃO: o chamador segura o sdMutex" e são curtas de propósito,
//     para o mutex ser devolvido logo (segurar mata o áudio de fome). O
//     desenho, que é a parte demorada, **não toca no cartão**: ele
//     redecodifica os bytes que já estão no `jpegBuffer`, exatamente como o
//     `redrawCurrentFrame()` do player faz.
//
//  5. Texto em ASCII maiúsculo (`ascii::normalizeUpper`), porque as fontes
//     bitmap só têm ASCII e um nome acentuado viraria buraco duplo. O nome
//     guardado no catálogo é o **cru**, do jeito que veio do cartão — é ele
//     que abre o arquivo; a normalização acontece só na hora de desenhar.
//
//  6. Sem ciano saturado (0x07FF) na saída composta: dot crawl. O acento é o
//     mesmo 0x96BC do resto do firmware.
//
//  7. Texto e faixas dentro de crt::SAFE_* (SafeArea.h). A foto em si pode
//     usar o quadro inteiro — só ela sangra até a borda do raster.
//
//  8. O JPEGDEC deste projeto não decodifica tudo o que se chama JPEG. Um
//     arquivo maior que o jpegBuffer (MAX_JPEG = 128 KiB: uma foto de câmera
//     de 4000x3168 tem ~560 KB) é recusado pelo TAMANHO, antes de ler; um
//     progressivo e um 4:4:4 são recusados pelo CABEÇALHO, antes de decodificar.
//     Ver o bloco "O que ESTA versão do JPEGDEC realmente decodifica", abaixo.
//     Em todos esses casos a tela mostra o motivo e a apresentação segue no
//     próximo prazo — nada de travar nem de deixar meia foto na tela.
//
//  ---------------------------------------------------------------------------
//  Uso (integração no main.cpp)
//  ---------------------------------------------------------------------------
//
//    photo::Show photos;
//    // storage na PSRAM, uma vez no setup():
//    photos.attachStorage((char *)ps_malloc(photo::POOL_SUGGESTED), photo::POOL_SUGGESTED,
//                         (uint16_t *)ps_malloc(photo::MAX_ENTRIES * 2), photo::MAX_ENTRIES);
//    photos.attachBuffer(jpegBuffer, MAX_JPEG);
//    photos.attachDecoder(&jpeg);
//
//    // ao entrar na tela (zera todo o estado — armadilha 6 do AGENTS.md):
//    photos.reset(millis());
//    take(sdMutex); photos.scan(SD); give(sdMutex);
//    take(sdMutex); photos.load(SD, millis()); give(sdMutex);
//    photos.paint(&tv, 0, 0);    // primeiro quadro, sem transição
//
//    // no loop():
//    if (tx.busy())            tx.tick(millis());
//    else if (photos.dueForNext(millis())) {
//      photos.advance(1, millis());
//      take(sdMutex); photos.load(SD, millis()); give(sdMutex);
//      photos.beginTransition(tx, millis(), nullptr);
//    }
//
//  Compila em -std=gnu++11. Depende da LovyanGFX (fj/Gfx.h, pelo ScreenFx.h),
//  SafeArea.h, Ascii.h e UiLogic.h. O JPEGDEC é detectado por __has_include:
//  sem ele (simulador de desktop) o arquivo continua compilando, só sem o
//  decode — o que permite testar a lógica pura em sim/probes/photo_show.cpp.
//  As funções de cartão são templates e só existem de fato quando chamadas.
// ============================================================================

#include "Ascii.h"
#include "SafeArea.h"
#include "ScreenFx.h"
#include "UiLogic.h" // timeReached()

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#if !defined(PHOTOSHOW_HAS_JPEGDEC) && defined(__has_include)
#if __has_include(<JPEGDEC.h>)
#define PHOTOSHOW_HAS_JPEGDEC 1
#endif
#endif
// As funções de cartão são templates sobre o tipo do sistema de arquivos, e
// não recebem mais um fs::FS&: no arduino-pico o `SD` é um SDClass que NÃO
// herda de fs::FS (é uma fachada sobre o SDFS), e além disso o FS::open de lá
// exige o modo. Com template, qualquer objeto que tenha open(path, "r")
// serve — o SD do arduino-pico, o do ESP32 e um falso no simulador — e o
// header não precisa de <FS.h>. PHOTOSHOW_HAS_SD continua existindo só para
// quem ainda testa por ele.
#ifndef PHOTOSHOW_HAS_SD
#define PHOTOSHOW_HAS_SD 1
#endif

#if PHOTOSHOW_HAS_JPEGDEC
#include <JPEGDEC.h>
#endif

namespace photo {

// ---------------------------------------------------------------------------
//  Limites e aparência
// ---------------------------------------------------------------------------

// Teto de fotos catalogadas. 256 já é mais do que alguém navega com três
// botões, e o custo é só o vetor de deslocamentos (2 B por entrada).
const int MAX_ENTRIES = 256;
// Maior nome de arquivo aceito. Acima disso a foto é ignorada: sem o nome
// inteiro não dá para reabrir o arquivo depois.
const int NAME_LIMIT = 63;
// Pool sugerido para os nomes. Com nome médio de ~16 caracteres cabem ~240
// fotos; quando acaba, a varredura para e `dropped()` conta o que ficou fora.
const int POOL_SUGGESTED = 4096;

constexpr const char *kDefaultDir = "/M5RETRO/fotos";
constexpr const char *kTitle = "FOTOS";
// Legendas dos três botões. O pintor desenha esta faixa ele mesmo: as
// transições repintam a tela inteira, e algo desenhado só uma vez pelo
// chamador sumiria no primeiro esmaecimento (armadilha 7 do AGENTS.md).
constexpr const char *kBtnPrev = "ANTERIOR";
constexpr const char *kBtnDwell = "TEMPO";
constexpr const char *kBtnNext = "PROXIMA";

// Mesmo acento seguro do resto do firmware. Ciano puro (0x07FF) faz dot crawl
// na composta; este azul claro tem a mesma luminância e croma baixo.
const uint16_t ACCENT = 0x96BC;

// Faixa da legenda, logo acima da barra de botões, dentro da área segura.
const int CAPTION_H = 16;
const int CAPTION_Y = crt::BAR_Y - CAPTION_H - 4; // 182 .. 198

// Prazos oferecidos pelo botão do meio, em milissegundos.
// C++11: corpo de constexpr é UM return só — nada de laço ou variável local.
constexpr uint32_t dwellMsAt(int slot) {
  return slot <= 0 ? 3000u : slot == 1 ? 5000u : slot == 2 ? 10000u : 30000u;
}
const int DWELL_SLOTS = 4;

// ---------------------------------------------------------------------------
//  Escolha do fator de redução do JPEGDEC
// ---------------------------------------------------------------------------
//
//  O JPEGDEC reduz na própria decodificação (1/2, 1/4, 1/8), sem buffer
//  intermediário: os blocos já saem menores para o callback. É o que permite
//  uma foto de câmera de 4000x3000 virar imagem na tela sem nada de 12
//  megapixels na memória.
//
//  Os valores de JPEG_SCALE_HALF/QUARTER/EIGHTH são 2, 4 e 8, e escala 1 é
//  opção 0 — por isso `option` sai daqui sem precisar do JPEGDEC.h, e esta
//  função pode ser testada no desktop.
struct Fit {
  uint8_t scale;  // 1, 2, 4 ou 8
  uint8_t option; // 0, 2, 4 ou 8 (o que vai em jpeg.decode(0,0,option))
  int16_t w, h;   // dimensões já reduzidas
  bool fits;      // false = nem 1/8 coube; desenha recortada no centro
};

// Regra: reduzir enquanto a imagem AINDA COBRIR o quadro, e parar antes do
// passo que a deixaria menor. O excesso e recortado no centro pelo desenho.
//
// A alternativa -- reduzir ate caber inteira -- parece mais segura e e pior de
// olhar. Uma foto de 1364x1080 cabe inteira so em 1/8, que da 171x135: pouco
// mais de um quarto do quadro, cercada de tarja preta. Em 1/4 ela da 341x270,
// estoura 6% e some so com as bordas. Na TV, 6% de recorte nao se nota; 171x135
// no meio de um quadro de 320x240 se nota de longe. E o CRT ja come ~7% por
// borda em overscan de qualquer jeito, entao parte desse recorte nem chega a
// ser visivel.
//
// Nao existe 1/16 no JPEGDEC, entao uma foto de camera de 4000 px para em 1/8 e
// sai recortada (500x396 -> fits=false), que e o melhor possivel sem
// redimensionar antes. tools/prepare_photos.py evita esse caso na origem.
inline Fit fitFor(int srcW, int srcH) {
  Fit f;
  int s = 1;
  while (s < 8) {
    const int nx = s * 2;
    // Para se o proximo passo derrubar qualquer um dos lados abaixo do quadro.
    if ((srcW + nx - 1) / nx < crt::W || (srcH + nx - 1) / nx < crt::H)
      break;
    s = nx;
  }
  f.scale = (uint8_t)s;
  f.option = (uint8_t)(s == 1 ? 0 : s);
  f.w = (int16_t)((srcW + s - 1) / s);
  f.h = (int16_t)((srcH + s - 1) / s);
  f.fits = (f.w <= crt::W && f.h <= crt::H);
  return f;
}

// ---------------------------------------------------------------------------
//  O que ESTA versão do JPEGDEC realmente decodifica
// ---------------------------------------------------------------------------
//
//  Medido na biblioteca do próprio projeto
//  (.pio/libdeps/m5stack-core2/JPEGDEC), não suposto:
//
//   * PROGRESSIVO FALHA EM SILÊNCIO — e é o caso perigoso. `decode()` devolve
//     sucesso e `getLastError()` devolve 0, mas só sai 1/8 da imagem: o
//     jpeg.inl, linha 4961, diz "progressive mode - we only decode the first
//     scan (DC values)". Uma foto de 320x240 vira um borrão de 40x30. Não há
//     código de erro para pegar isso DEPOIS, então a checagem é ANTES, pelo
//     `getJPEGType()` (0xC2 = SOF2 = progressivo). Exportadores web e o "Save
//     for Web" do Photoshop geram progressivo por padrão, então isto acontece
//     com foto de gente de verdade, não é caso de laboratório.
//
//   * 4:4:4 (yuvj444p) NÃO DECODIFICA: devolve JPEG_DECODE_ERROR, e pior,
//     depois de já ter chamado o callback para alguns blocos — sobra meia
//     imagem na tela. Por isso o pintor LIMPA o quadro quando o decode falha.
//     O Y do SOF sai em `getSubSample()`: 0x11 é 4:4:4 (recusado), 0x21/0x12/
//     0x22 são os 4:2:2/4:2:0 que funcionam, e 0 é escala de cinza (1 só
//     componente), que funciona e não pode ser confundida com 4:4:4.
//
//  Formato recomendado para o cartão: 320x240, baseline, yuvj420p, -q:v 5
//  (~8 KB por foto). O resto é tratado com educação, não com travamento.
enum Support : uint8_t { SUP_OK, SUP_PROGRESSIVE, SUP_SUBSAMPLE };

// `jpegType` é o que o getJPEGType() devolve (0 = baseline, 1 = progressivo) e
// `subSample` o que o getSubSample() devolve. Fora do JPEGDEC.h de propósito,
// para poder ser testado no desktop.
inline Support supportFor(int jpegType, int subSample) {
  return jpegType == 1 ? SUP_PROGRESSIVE : (subSample == 0x11 ? SUP_SUBSAMPLE : SUP_OK);
}

// ---------------------------------------------------------------------------
//  Resultado da última tentativa de carregar uma foto
// ---------------------------------------------------------------------------
enum Result : uint8_t {
  RES_NONE,        // ainda não se tentou carregar nada
  RES_OK,          // bytes no buffer, dimensões conhecidas
  RES_EMPTY,       // a pasta não tem foto nenhuma
  RES_NO_BUFFER,   // faltou attachBuffer()/attachDecoder()
  RES_UNREADABLE,  // não abriu, ou a leitura veio curta
  RES_TOO_BIG,     // arquivo maior que o jpegBuffer (MAX_JPEG = 128 KiB)
  RES_BAD_JPEG,    // cabeçalho inválido, ou o decode falhou no meio
  RES_PROGRESSIVE, // JPEG progressivo: sairia 1/8 da imagem, sem erro nenhum
  RES_SUBSAMPLE    // 4:4:4: o decodificador desiste no meio do quadro
};

// Mensagem ASCII maiúscula correspondente, para a tela.
inline const char *message(Result r) {
  return r == RES_OK            ? ""
         : r == RES_EMPTY       ? "SEM FOTOS NO CARTAO"
         : r == RES_NO_BUFFER   ? "SEM MEMORIA PARA DECODIFICAR"
         : r == RES_UNREADABLE  ? "NAO FOI POSSIVEL LER A FOTO"
         : r == RES_TOO_BIG     ? "FOTO MUITO GRANDE - PULANDO"
         : r == RES_BAD_JPEG    ? "FOTO INVALIDA - PULANDO"
         : r == RES_PROGRESSIVE ? "JPEG PROGRESSIVO - USE BASELINE"
         : r == RES_SUBSAMPLE   ? "JPEG 4:4:4 - USE 4:2:0"
                                : "CARREGANDO";
}

// ---------------------------------------------------------------------------
//  Catálogo: nomes curtos num pool do chamador, ordenados por nome
// ---------------------------------------------------------------------------
class Catalog {
public:
  Catalog()
      : pool_(nullptr), off_(nullptr), poolCap_(0), poolUsed_(0), maxEntries_(0), count_(0),
        dropped_(0) {}

  // `pool` guarda os nomes (com o \0); `offsets` tem um uint16_t por entrada.
  // Os dois podem vir da PSRAM — este header nunca aloca.
  void attachStorage(char *pool, uint16_t poolCap, uint16_t *offsets, uint16_t maxEntries) {
    pool_ = pool;
    poolCap_ = poolCap;
    off_ = offsets;
    maxEntries_ = maxEntries > (uint16_t)MAX_ENTRIES ? (uint16_t)MAX_ENTRIES : maxEntries;
    clear();
  }
  bool attached() const { return pool_ && off_ && poolCap_ > 0 && maxEntries_ > 0; }
  void clear() {
    poolUsed_ = 0;
    count_ = 0;
    dropped_ = 0;
  }

  int count() const { return count_; }
  int dropped() const { return dropped_; } // quantas ficaram de fora do pool
  int capacity() const { return maxEntries_; }
  const char *name(int i) const { return (i >= 0 && i < count_) ? pool_ + off_[i] : ""; }

  // O iterador de diretório do ESP32 às vezes devolve o caminho inteiro
  // ("/M5RETRO/fotos/a.jpg") e às vezes só o nome. Fica só o nome.
  static const char *baseName(const char *p) {
    if (!p)
      return "";
    const char *s = strrchr(p, '/');
    return s ? s + 1 : p;
  }

  // Extensão .jpg/.jpeg, sem diferenciar caixa. Ignora o que começa com '.'
  // (arquivos de recurso do macOS, "._IMG_0001.JPG", são lixo no cartão).
  static bool isJpeg(const char *name) {
    if (!name || !*name || name[0] == '.')
      return false;
    const size_t n = strlen(name);
    if (n > 4 && lowerEq(name + n - 4, ".jpg", 4))
      return true;
    return n > 5 && lowerEq(name + n - 5, ".jpeg", 5);
  }

  // Guarda o nome CRU (é ele que abre o arquivo). Devolve false quando não é
  // foto ou quando não coube. Não ordena: chame sort() no fim da varredura.
  bool add(const char *rawName) {
    if (!attached())
      return false;
    const char *n = baseName(rawName);
    if (!isJpeg(n))
      return false;
    const size_t len = strlen(n);
    if (len > (size_t)NAME_LIMIT || count_ >= maxEntries_ ||
        poolUsed_ + (uint32_t)len + 1 > (uint32_t)poolCap_) {
      ++dropped_;
      return false;
    }
    memcpy(pool_ + poolUsed_, n, len + 1);
    off_[count_++] = poolUsed_;
    poolUsed_ = (uint16_t)(poolUsed_ + len + 1);
    return true;
  }

  // Ordena por nome, sem diferenciar caixa. Inserção sobre o vetor de
  // deslocamentos: os nomes não se movem no pool, só os índices. Com 256
  // entradas o pior caso são ~32 mil comparações curtas — milissegundos, e
  // roda uma vez por visita à tela.
  void sort() {
    for (int i = 1; i < count_; ++i) {
      const uint16_t key = off_[i];
      int j = i - 1;
      while (j >= 0 && casecmp(pool_ + off_[j], pool_ + key) > 0) {
        off_[j + 1] = off_[j];
        --j;
      }
      off_[j + 1] = key;
    }
  }

  // Monta "dir/nome" num buffer do chamador. É o único lugar onde um caminho
  // completo existe, e ele vive só durante o open().
  bool path(int i, const char *dir, char *dst, size_t cap) const {
    if (!dst || cap == 0)
      return false;
    dst[0] = 0;
    const char *n = name(i);
    if (!dir || !n[0])
      return false;
    const int need = snprintf(dst, cap, "%s/%s", dir, n);
    return need > 0 && (size_t)need < cap;
  }

  static int casecmp(const char *a, const char *b) {
    while (*a && *b) {
      const int ca = up(*a), cb = up(*b);
      if (ca != cb)
        return ca - cb;
      ++a;
      ++b;
    }
    return up(*a) - up(*b);
  }

private:
  static int up(char c) { return (c >= 'a' && c <= 'z') ? c - ('a' - 'A') : (unsigned char)c; }
  static bool lowerEq(const char *s, const char *lower, size_t n) {
    for (size_t i = 0; i < n; ++i)
      if (up(s[i]) != up(lower[i]))
        return false;
    return true;
  }

  char *pool_;
  uint16_t *off_;
  uint16_t poolCap_, poolUsed_, maxEntries_;
  int count_, dropped_;
};

// ---------------------------------------------------------------------------
//  Alvo do callback do JPEGDEC
// ---------------------------------------------------------------------------
//  O JPEGDEC só aceita ponteiro de função (nada de lambda com captura), então
//  o destino do bloco vai por um contexto de arquivo — mesmo padrão do
//  `posterSprite` do main.cpp. Fica num static de função para o header
//  continuar sem .cpp (C++11 não tem variável `inline`).
struct Blit {
  lgfx::LovyanGFX *dst;
  int x0, y0;
  int32_t clipW, clipH; // tamanho do destino, para descartar bloco fora dele
};
inline Blit &blitCtx() {
  static Blit b = {nullptr, 0, 0, 0, 0};
  return b;
}

#if PHOTOSHOW_HAS_JPEGDEC
inline int blitCallback(JPEGDRAW *draw) {
  Blit &b = blitCtx();
  if (!b.dst)
    return 1;
  const int x = b.x0 + draw->x, y = b.y0 + draw->y;
  // Uma foto de 4000x3168 ainda sai 500x396 em 1/8 — o JPEGDEC não tem 1/16 —
  // então há blocos fora da tela em toda apresentação com foto de câmera.
  // Descartar o bloco inteiramente fora poupa a chamada; o parcialmente fora
  // vai para o pushImage, que recorta contra o clipRect corrente nos quatro
  // lados (LGFXBase::pushImage, ajuste de _clip_l/_clip_t + _adjust_width) e
  // corrige o ponteiro de origem. Nada é escrito fora do painel.
  if (x >= b.clipW || y >= b.clipH || x + draw->iWidth <= 0 || y + draw->iHeight <= 0)
    return 1;
  b.dst->pushImage(x, y, draw->iWidth, draw->iHeight,
                   reinterpret_cast<const lgfx::rgb565_t *>(draw->pPixels));
  return 1;
}
#endif

// ---------------------------------------------------------------------------
//  A tela
// ---------------------------------------------------------------------------
class Show {
public:
  // O que o chamador precisa fazer depois de um botão.
  enum Action : uint8_t {
    ACT_NONE,    // nada mudou
    ACT_REPAINT, // só redesenhar (mudou o prazo)
    ACT_LOAD     // trocou de foto: load() com o mutex e depois a transição
  };

  Show()
      : dir_(kDefaultDir), buf_(nullptr), bufCap_(0), index_(0), dwell_(1), deadline_(0),
        result_(RES_NONE), bytes_(0), srcW_(0), srcH_(0) {
#if PHOTOSHOW_HAS_JPEGDEC
    jpeg_ = nullptr;
#endif
    fit_ = fitFor(1, 1);
  }

  // -- ligações (uma vez, no setup) -----------------------------------------

  void attachStorage(char *pool, uint16_t poolCap, uint16_t *offsets, uint16_t maxEntries) {
    cat_.attachStorage(pool, poolCap, offsets, maxEntries);
  }
  // REUSA o jpegBuffer do vídeo (PSRAM, 128 KiB). Não alocar outro.
  void attachBuffer(uint8_t *jpegBuffer, size_t cap) {
    buf_ = jpegBuffer;
    bufCap_ = cap;
  }
#if PHOTOSHOW_HAS_JPEGDEC
  // REUSA a instância global do JPEGDEC: a JPEGIMAGE é grande demais para duas.
  void attachDecoder(JPEGDEC *dec) { jpeg_ = dec; }
#endif
  void setFolder(const char *dir) { dir_ = dir ? dir : kDefaultDir; }
  const char *folder() const { return dir_; }

  // Zera TUDO ao entrar na tela. Estado static/membro herdado da visita
  // anterior é a armadilha 6 do AGENTS.md.
  void reset(uint32_t now) {
    cat_.clear();
    index_ = 0;
    result_ = RES_NONE;
    bytes_ = 0;
    srcW_ = srcH_ = 0;
    fit_ = fitFor(1, 1);
    resetTimer(now);
  }

  // -- catálogo --------------------------------------------------------------

  Catalog &catalog() { return cat_; } // exposto para teste nativo e diagnóstico
  const Catalog &catalog() const { return cat_; }
  int count() const { return cat_.count(); }
  int index() const { return index_; }
  const char *rawName() const { return cat_.name(index_); }

  // Nome da foto corrente em ASCII maiúsculo, para desenhar.
  size_t displayName(char *dst, size_t cap) const {
    return ascii::normalizeUpper(dst, cap, cat_.name(index_));
  }

  // Fecha a varredura: ordena, prende o índice na faixa e reinicia o prazo.
  // Chamado pelo scan(); público para o probe nativo poder alimentar o
  // catálogo à mão, sem cartão.
  void afterScan(uint32_t now) {
    cat_.sort();
    if (index_ >= cat_.count())
      index_ = 0;
    result_ = cat_.count() ? RES_NONE : RES_EMPTY;
    bytes_ = 0;
    resetTimer(now);
  }

  // -- navegação e prazo -----------------------------------------------------

  int dwellSlot() const { return dwell_; }
  uint32_t dwellMs() const { return dwellMsAt(dwell_); }
  uint32_t deadline() const { return deadline_; }

  void resetTimer(uint32_t now) { deadline_ = now + dwellMs(); }

  // Prazo vencido? `timeReached` compara a DIFERENÇA com sinal, então o wrap
  // de millis() (~49 dias) não faz a foto congelar nem correr.
  bool dueForNext(uint32_t now) const { return cat_.count() > 0 && timeReached(now, deadline_); }

  // Avança `delta` fotos, dando a volta nas duas pontas. Reinicia o prazo.
  void advance(int delta, uint32_t now) {
    const int n = cat_.count();
    if (n <= 0) {
      index_ = 0;
      resetTimer(now);
      return;
    }
    int i = (index_ + delta) % n;
    if (i < 0)
      i += n; // % em C++ pode devolver negativo
    index_ = i;
    bytes_ = 0;
    result_ = RES_NONE;
    resetTimer(now);
  }

  void setIndex(int i, uint32_t now) { advance(i - index_, now); }

  void cycleDwell(uint32_t now) {
    dwell_ = (dwell_ + 1) % DWELL_SLOTS;
    resetTimer(now); // o prazo novo vale a partir de agora
  }

  // Botões: 0 = anterior, 1 = tempo, 2 = próxima.
  Action onButton(int button, uint32_t now) {
    if (button == 0) {
      advance(-1, now);
      return ACT_LOAD;
    }
    if (button == 2) {
      advance(1, now);
      return ACT_LOAD;
    }
    if (button == 1) {
      cycleDwell(now);
      return ACT_REPAINT;
    }
    return ACT_NONE;
  }

  // -- estado da foto --------------------------------------------------------

  Result result() const { return result_; }
  const char *statusText() const { return message(result_); }
  bool hasImage() const { return result_ == RES_OK && bytes_ > 0; }
  size_t bytes() const { return bytes_; }
  int srcWidth() const { return srcW_; }
  int srcHeight() const { return srcH_; }
  const Fit &fit() const { return fit_; }

  // -- cartão (PRÉ-CONDIÇÃO: o chamador segura o sdMutex) --------------------
  // Lista a pasta e ordena. Curto de propósito: só lê nomes de diretório.
  //
  // PRÉ-CONDIÇÃO: o chamador já tomou o sdMutex e o devolve logo depois.
  template <class Fs> int scan(Fs &fs, uint32_t now = 0) {
    cat_.clear();
    auto dir = fs.open(dir_, "r");
    if (!dir || !dir.isDirectory()) {
      if (dir)
        dir.close();
      afterScan(now);
      return 0;
    }
    for (auto e = dir.openNextFile(); e; e = dir.openNextFile()) {
      if (!e.isDirectory())
        cat_.add(e.name());
      e.close();
    }
    dir.close();
    afterScan(now);
    return cat_.count();
  }

  // Lê a foto corrente inteira para o jpegBuffer e mede as dimensões. O
  // decode de verdade acontece no pintor, sem cartão — assim o mutex fica
  // preso só pelo tempo da leitura.
  //
  // PRÉ-CONDIÇÃO: o chamador já tomou o sdMutex e o devolve logo depois.
  template <class Fs> Result load(Fs &fs, uint32_t now) {
    bytes_ = 0;
    srcW_ = srcH_ = 0;
    if (!cat_.count())
      return finish(RES_EMPTY, now);
    if (!buf_ || bufCap_ == 0)
      return finish(RES_NO_BUFFER, now);
    char p[160];
    if (!cat_.path(index_, dir_, p, sizeof(p)))
      return finish(RES_UNREADABLE, now);
    auto f = fs.open(p, "r");
    if (!f || f.isDirectory()) {
      if (f)
        f.close();
      return finish(RES_UNREADABLE, now);
    }
    const size_t size = (size_t)f.size();
    if (size == 0) {
      f.close();
      return finish(RES_BAD_JPEG, now);
    }
    // Maior que o buffer: pula com mensagem em vez de arriscar a memória.
    if (size > bufCap_) {
      f.close();
      return finish(RES_TOO_BIG, now);
    }
    const size_t got = f.read(buf_, size);
    f.close();
    if (got != size)
      return finish(RES_UNREADABLE, now);
    bytes_ = size;
    return measure(now);
  }

  // Mede o cabeçalho do que já está no buffer e escolhe a redução. Separado do
  // load() para o chamador poder alimentar o buffer por outro caminho.
  Result measure(uint32_t now) {
#if PHOTOSHOW_HAS_JPEGDEC
    if (!jpeg_ || !buf_ || !bytes_)
      return finish(RES_NO_BUFFER, now);
    if (!jpeg_->openRAM(buf_, (int)bytes_, blitCallback)) {
      bytes_ = 0;
      return finish(RES_BAD_JPEG, now);
    }
    srcW_ = jpeg_->getWidth();
    srcH_ = jpeg_->getHeight();
    // Formato do arquivo, ainda com o cabeçalho aberto. É a ÚNICA chance de
    // pegar o progressivo: depois do decode ele mente que deu certo.
    const Support sup = supportFor(jpeg_->getJPEGType(), jpeg_->getSubSample());
    jpeg_->close();
    if (srcW_ < 1 || srcH_ < 1) {
      bytes_ = 0;
      return finish(RES_BAD_JPEG, now);
    }
    if (sup != SUP_OK) {
      bytes_ = 0; // não chega a desenhar nada: a tela mostra o motivo
      return finish(sup == SUP_PROGRESSIVE ? RES_PROGRESSIVE : RES_SUBSAMPLE, now);
    }
    fit_ = fitFor(srcW_, srcH_);
    return finish(RES_OK, now);
#else
    (void)now;
    return finish(RES_NO_BUFFER, now);
#endif
  }

  // -- desenho ---------------------------------------------------------------

  // Pintor no formato dos outros: soma (ox, oy) a TUDO, não mexe no recorte
  // (é por ele que o ScreenFx limita o repinte) e pode ser chamado mais de uma
  // vez no mesmo quadro. Serve para o canvas `tv` e para um sprite.
  void paint(lgfx::LovyanGFX *dst, int ox, int oy) {
    if (!dst)
      return;
    dst->fillScreen(TFT_BLACK); // respeita o recorte corrente
    if (!decodeInto(dst, ox, oy))
      drawMessage(dst, ox, oy);
    if (cat_.count() > 0)
      drawCaption(dst, ox, oy);
    drawLegend(dst, ox, oy);
  }

  // Ponte para o crt::fx::Paint (que leva um void* em vez do this).
  static void paintFn(lgfx::LovyanGFX *dst, int ox, int oy, void *user) {
    if (user)
      static_cast<Show *>(user)->paint(dst, ox, oy);
  }
  crt::fx::Screen screen() { return crt::fx::screen(&Show::paintFn, this); }

  // Começa a transição para a foto corrente.
  //
  // `scratch` é o LGFX_Sprite 320x240 RGB565 que o crossfade exigiria (ver
  // ScreenFx.h: no Fruit Jam só cabe na PSRAM, via ps_malloc + setBuffer).
  // Hoje o main.cpp passa nullptr. Por isso aqui se usa `fadeThrough`, e não
  // `crossfade`: sem sprite o crossfade vira corte seco
  // puro (hardCut), enquanto o fadeThrough ainda esmaece de verdade até o
  // preto com o dither de Bayer — que não precisa de buffer nenhum — e só o
  // reacender é que vira corte. Devolve o que o ScreenFx devolveu (false =
  // degradou, que é o esperado com nullptr).
  bool beginTransition(crt::fx::Transition &tx, uint32_t now, lgfx::LGFX_Sprite *scratch = nullptr,
                       uint32_t msOut = 260, uint32_t msIn = 200) {
    return tx.fadeThrough(now, screen(), scratch, msOut, msIn, TFT_BLACK);
  }

private:
  Result finish(Result r, uint32_t now) {
    result_ = r;
    // Mesmo com erro o prazo recomeça: a foto ruim mostra a mensagem e some
    // sozinha no próximo avanço, em vez de travar a apresentação.
    resetTimer(now);
    return r;
  }

  bool decodeInto(lgfx::LovyanGFX *dst, int ox, int oy) {
#if PHOTOSHOW_HAS_JPEGDEC
    if (!hasImage() || !jpeg_)
      return false;
    if (!jpeg_->openRAM(buf_, (int)bytes_, blitCallback))
      return false;
    jpeg_->setPixelType(RGB565_LITTLE_ENDIAN);
    Blit &b = blitCtx();
    b.dst = dst;
    // Centralizado. Quando nem 1/8 coube, a origem fica negativa e o
    // pushImage recorta: aparece o centro da foto, que é o menos ruim.
    b.x0 = ox + (crt::W - fit_.w) / 2;
    b.y0 = oy + (crt::H - fit_.h) / 2;
    b.clipW = dst->width();
    b.clipH = dst->height();
    const bool ok = jpeg_->decode(0, 0, (int)fit_.option) != 0;
    b.dst = nullptr;
    jpeg_->close();
    if (!ok) {
      // O decode falha DEPOIS de ter desenhado alguns blocos (foi assim que o
      // 4:4:4 deixou uma tira de 320x80 na tela). Limpar é obrigatório, senão
      // fica meia foto sob a mensagem de erro.
      dst->fillScreen(TFT_BLACK);
      bytes_ = 0;
      result_ = RES_BAD_JPEG; // a mensagem logo abaixo já sai com o motivo certo
    }
    return ok;
#else
    (void)dst;
    (void)ox;
    (void)oy;
    return false;
#endif
  }

  // Tela de recado: título + motivo, centralizados na área segura.
  void drawMessage(lgfx::LovyanGFX *dst, int ox, int oy) {
    dst->setFont(&fonts::Font2);
    dst->setTextSize(1);
    dst->setTextDatum(top_left);
    dst->setTextColor(TFT_WHITE, TFT_BLACK);
    dst->drawString(kTitle, ox + crt::SAFE_L, oy + crt::HEAD_Y);
    dst->drawFastHLine(ox + crt::SAFE_L, oy + crt::HEAD_RULE_Y, crt::SAFE_W, ACCENT);
    dst->setTextDatum(middle_center);
    dst->setTextColor(ACCENT, TFT_BLACK);
    dst->drawString(statusText(), ox + crt::W / 2, oy + crt::H / 2 - 8);
    if (cat_.count() > 0) {
      char nm[40];
      displayName(nm, sizeof(nm));
      dst->setFont(&fonts::Font0);
      dst->setTextColor(TFT_WHITE, TFT_BLACK);
      dst->drawString(nm, ox + crt::W / 2, oy + crt::H / 2 + 14);
    }
  }

  // Faixa da legenda: nome à esquerda, "n / total" e o prazo à direita.
  void drawCaption(lgfx::LovyanGFX *dst, int ox, int oy) {
    char nm[40], right[24], shown[40];
    displayName(nm, sizeof(nm));
    snprintf(right, sizeof(right), "%d / %d  %luS", index_ + 1, cat_.count(),
             (unsigned long)(dwellMs() / 1000UL));
    // Font0 tem 6 px por caractere: o lado direito come ~14 caracteres da
    // largura segura (272 px = 45), então o nome fica com 26 e reticências.
    fitText(shown, sizeof(shown), nm, 26);
    dst->fillRect(ox + crt::SAFE_L, oy + CAPTION_Y, crt::SAFE_W, CAPTION_H, TFT_BLACK);
    dst->drawFastHLine(ox + crt::SAFE_L, oy + CAPTION_Y, crt::SAFE_W, ACCENT);
    dst->setFont(&fonts::Font0);
    dst->setTextSize(1);
    dst->setTextDatum(top_left);
    dst->setTextColor(TFT_WHITE, TFT_BLACK);
    dst->drawString(shown, ox + crt::SAFE_L + 4, oy + CAPTION_Y + 4);
    dst->setTextDatum(top_right);
    dst->setTextColor(ACCENT, TFT_BLACK);
    dst->drawString(right, ox + crt::SAFE_R - 4, oy + CAPTION_Y + 4);
  }

  // Mesma faixa de botões das outras telas. Desenhada AQUI porque a transição
  // repinta a tela toda e o que o chamador desenhasse por fora sumiria.
  void drawLegend(lgfx::LovyanGFX *dst, int ox, int oy) {
    char line[64];
    snprintf(line, sizeof(line), "[ %s ]  [ %s ]  [ %s ]", kBtnPrev, kBtnDwell, kBtnNext);
    dst->fillRect(ox, oy + crt::BAR_Y, crt::W, crt::BAR_H, TFT_NAVY);
    dst->setFont(&fonts::Font0);
    dst->setTextSize(1);
    dst->setTextDatum(middle_center);
    dst->setTextColor(ACCENT, TFT_NAVY);
    dst->drawString(line, ox + crt::W / 2, oy + crt::BAR_Y + crt::BAR_H / 2);
  }

  // Corta em `maxChars` com ".." no fim, como o truncateText do main.cpp.
  static void fitText(char *dst, size_t cap, const char *src, int maxChars) {
    if (!dst || cap == 0)
      return;
    const size_t len = strlen(src);
    if ((int)len <= maxChars || maxChars < 3) {
      snprintf(dst, cap, "%s", src);
      return;
    }
    const int keep = maxChars - 2;
    size_t n = (size_t)keep;
    if (n > cap - 3)
      n = cap - 3;
    memcpy(dst, src, n);
    dst[n] = '.';
    dst[n + 1] = '.';
    dst[n + 2] = 0;
  }

  Catalog cat_;
  const char *dir_;
  uint8_t *buf_;
  size_t bufCap_;
#if PHOTOSHOW_HAS_JPEGDEC
  JPEGDEC *jpeg_;
#endif
  int index_, dwell_;
  uint32_t deadline_;
  Result result_;
  size_t bytes_;
  int srcW_, srcH_;
  Fit fit_;
};

} // namespace photo

#pragma once
// ============================================================================
// RadioScreen — a tela do rádio pela internet do M5 RETRO TV.
//
// A especificação é curta e é a regra que decide todo o resto deste arquivo:
// **o logotipo da estação, e nada além de um relógio em hora local.** Não é uma
// tela de player. Não tem barra de progresso, não tem espectro, não tem capa,
// não tem menu. É um relógio de parede com o logotipo da rádio em cima, que por
// acaso está tocando som. Tudo que for acrescentado aqui tira dela exatamente o
// que a torna boa de deixar ligada.
//
// As duas únicas concessões são uma linha de estado (CONECTANDO / NO AR / SEM
// SINAL) e, quando o servidor manda, o nome da música num letreiro lento. Ambas
// em corpo pequeno, cinza, no rodapé — presentes para quem procurar, invisíveis
// para quem não.
//
// ---------------------------------------------------------------------------
//  Repintura parcial: por que isto não é otimização prematura
// ---------------------------------------------------------------------------
//
// A saída composta roda a ~23 quadros/s e o framebuffer do CVBS vive na SRAM.
// Repintar 320x240 uma vez por segundo, só para mudar dois dígitos, gastaria
// ciclos do core 1 e — pior — piscaria a tela inteira no tubo uma vez por
// segundo. É o mesmo motivo pelo qual o relógio do menu inicial do src/main.cpp
// redesenha só a própria faixa.
//
// Então o desenho é dividido em regiões e `tick()` repinta SÓ o que mudou:
//
//   R_LOGO    nunca, depois da primeira pintura
//   R_SEC     uma vez por segundo  (72x32 px)
//   R_HOUR    uma vez por minuto   (180x48 px)
//   R_DATE    uma vez por dia
//   R_STATUS  quando o estado da conexão muda
//   R_TICKER  um passo de caractere a cada 500 ms, e só se o título não couber
//
// `tick()` devolve a máscara das regiões repintadas e `regionRect()` dá o
// retângulo de cada uma, para quem integra saber o que sujou (útil para as
// transições do ScreenFx.h e para o espelhamento no LCD).
//
// ---------------------------------------------------------------------------
//  Restrições do tubo que este arquivo respeita
// ---------------------------------------------------------------------------
//
// * Tudo dentro de crt::SAFE_* (SafeArea.h): um CRT come ~7% de cada borda.
//   Só o fundo sangra até o limite do raster.
// * Nada de ciano saturado (TFT_CYAN / 0x07FF): na composta ele produz dot
//   crawl visível. O acento seguro do projeto é 0x96BC.
// * Texto ASCII sem acento: as fontes bitmap só têm 0x20..0x7E. O título vindo
//   do servidor já chega normalizado pelo RadioStream.h, mas esta tela
//   normaliza de novo antes de desenhar — sai mais barato do que confiar.
// * Nada de LGFX_Sprite: não há SRAM para isso (uma alocação de 5 KB já
//   derrubou o aparelho). Todo desenho vai direto no destino.
//
// A entrada de desenho é (LovyanGFX *dst, int ox, int oy), como os pintores da
// previsão do tempo: o mesmo código serve ao painel CVBS, ao LCD do Core2 e ao
// painel SDL do simulador, e o deslocamento permite usar as transições.
//
// Compila em -std=gnu++11. Todo corpo de constexpr aqui é um único return.
// ============================================================================

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "Ascii.h"
#include "SafeArea.h"
#include "UiLogic.h" // timeReached()
#include "VcrFont.h" // traz a LovyanGFX (fj/Gfx.h) junto

// ---------------------------------------------------------------------------
//  Logotipo da estação (header GERADO, fora deste arquivo)
// ---------------------------------------------------------------------------
//
// O bitmap do logotipo NÃO é criado aqui: ele é gerado a partir da arte da
// própria estação e entregue em include/DiarioLogo.h. Quando esse header não
// existe, a tela cai no nome da estação em texto ASCII e continua correta.
//
// Contrato esperado de include/DiarioLogo.h (é só isto; nada mais é lido):
//
//   #pragma once
//   #include <stdint.h>
//   namespace diariologo {
//   constexpr int      WIDTH       = 176;     // <= radioui::LOGO_MAX_W (272)
//   constexpr int      HEIGHT      =  56;     // <= radioui::LOGO_MAX_H  (64)
//   constexpr bool     HAS_TRANSPARENT = true;
//   constexpr uint16_t TRANSPARENT  = 0x0000; // cor tratada como buraco
//   const uint16_t     PIXELS[WIDTH * HEIGHT] = { ... };
//   }
//
//   * PIXELS é RGB565 na ordem NATIVA do uint16_t (o mesmo formato que o
//     src/main.cpp já empurra com pushImage e lgfx::rgb565_t), linha a linha,
//     começando pelo canto superior esquerdo, sem cabeçalho e sem padding.
//   * HAS_TRANSPARENT = false para um logotipo retangular opaco; nesse caso
//     TRANSPARENT é ignorado (mas precisa existir, para o header compilar).
//   * O gerador deve EVITAR ciano saturado (0x07FF e vizinhos) na arte: na
//     saída composta essa cor glitcha. Se a arte original tiver, puxe o
//     vermelho para cima como o RCA_ACCENT do projeto faz.
//   * WIDTH/HEIGHT são constexpr int porque o tamanho do vetor depende deles.
//
// Nada além de WIDTH, HEIGHT, HAS_TRANSPARENT, TRANSPARENT e PIXELS é usado.
#if defined(__has_include)
#if __has_include("DiarioLogo.h")
#include "DiarioLogo.h"
#define RADIOUI_HAVE_LOGO 1
#endif
#endif

namespace radioui {

// ---------------------------------------------------------------------------
//  Cores
// ---------------------------------------------------------------------------

constexpr uint16_t BG = 0x000F;     // TFT_NAVY, o fundo das outras telas
constexpr uint16_t INK = 0xFFFF;    // branco: croma zero, nunca glitcha
constexpr uint16_t ACCENT = 0x96BC; // azul-claro seguro para NTSC (ver main.cpp)
constexpr uint16_t DIM = 0x8410;    // cinza médio, também sem croma
constexpr uint16_t SHADOW = 0x0000; // contorno dos glifos grandes

// ---------------------------------------------------------------------------
//  Geometria
// ---------------------------------------------------------------------------
//
// Tudo derivado de crt::SAFE_* — duas constantes descrevendo a mesma geometria
// é a armadilha 8 do AGENTS.md.
//
//   logotipo  [20, 84)   faixa de 272x64, centralizado
//   HH:MM     [96,144)   VcrFont escala 3 (36x48 por célula), 5 células = 180
//   :SS       [112,144)  VcrFont escala 2 (24x32), 3 células = 72, base alinhada
//   data      [152,168)  escala 1
//   estado    [182,198)  escala 1
//   letreiro  [202,218)  escala 1
//
// O relógio não é HH:MM:SS do mesmo tamanho porque 8 células na escala 3 dariam
// 288 px e a largura segura tem 272. Em vez de encolher tudo para a escala 2, os
// segundos descem um degrau: o dado que se lê de longe (a hora) fica o maior
// possível e a região que repinta a cada segundo fica a MENOR possível.

struct Rect {
  int16_t x, y, w, h;
};

constexpr int LOGO_MAX_W = crt::SAFE_W; // 272
constexpr int LOGO_MAX_H = 64;

constexpr int HOUR_SCALE = 3;
constexpr int SEC_SCALE = 2;
constexpr int SMALL_SCALE = 1;

constexpr int HOUR_W = 5 * vcrfont::CELL_W * HOUR_SCALE; // "HH:MM" = 180
constexpr int SEC_W = 3 * vcrfont::CELL_W * SEC_SCALE;   // ":SS"   =  72
constexpr int CLOCK_GAP = 8;
constexpr int CLOCK_W = HOUR_W + CLOCK_GAP + SEC_W; // 260
constexpr int CLOCK_X = crt::SAFE_L + (crt::SAFE_W - CLOCK_W) / 2; // 30
constexpr int CLOCK_Y = 96;
constexpr int HOUR_H = vcrfont::CELL_H * HOUR_SCALE; // 48
constexpr int SEC_H = vcrfont::CELL_H * SEC_SCALE;   // 32

constexpr Rect LOGO_RECT = {(int16_t)crt::SAFE_L, (int16_t)(crt::SAFE_T + 2), (int16_t)LOGO_MAX_W,
                            (int16_t)LOGO_MAX_H};
constexpr Rect HOUR_RECT = {(int16_t)CLOCK_X, (int16_t)CLOCK_Y, (int16_t)HOUR_W, (int16_t)HOUR_H};
// Base alinhada com a da hora: CLOCK_Y + HOUR_H - SEC_H.
constexpr Rect SEC_RECT = {(int16_t)(CLOCK_X + HOUR_W + CLOCK_GAP), (int16_t)(CLOCK_Y + HOUR_H - SEC_H),
                           (int16_t)SEC_W, (int16_t)SEC_H};
constexpr Rect DATE_RECT = {(int16_t)crt::SAFE_L, 152, (int16_t)crt::SAFE_W, 16};
constexpr Rect STATUS_RECT = {(int16_t)crt::SAFE_L, 182, (int16_t)crt::SAFE_W, 16};
constexpr Rect TICKER_RECT = {(int16_t)crt::SAFE_L, 202, (int16_t)crt::SAFE_W, 16};

// Quantos caracteres cabem no letreiro (escala 1 = 12 px por célula).
constexpr int TICKER_COLS = crt::SAFE_W / vcrfont::CELL_W; // 22

// Um passo de caractere a cada 500 ms. Lento de propósito: o ponto da tela é o
// relógio, e um letreiro rápido rouba o olho.
constexpr uint32_t TICKER_STEP_MS = 500;

// ---------------------------------------------------------------------------
//  Regiões
// ---------------------------------------------------------------------------

enum Region : uint8_t {
  R_NONE = 0,
  R_LOGO = 1 << 0,
  R_HOUR = 1 << 1,
  R_SEC = 1 << 2,
  R_DATE = 1 << 3,
  R_STATUS = 1 << 4,
  R_TICKER = 1 << 5,
  R_ALL = 0x3F
};

inline Rect regionRect(uint8_t bit) {
  return bit == R_LOGO     ? LOGO_RECT
         : bit == R_HOUR   ? HOUR_RECT
         : bit == R_SEC    ? SEC_RECT
         : bit == R_DATE   ? DATE_RECT
         : bit == R_STATUS ? STATUS_RECT
         : bit == R_TICKER ? TICKER_RECT
                           : Rect{0, 0, 0, 0};
}

// ---------------------------------------------------------------------------
//  Estado exibido
// ---------------------------------------------------------------------------
//
// Struct burra de propósito: esta tela não sabe o que é Wi-Fi, socket ou NTP.
// Quem integra preenche e chama. É o que permite ao probe desenhar qualquer
// combinação sem simular nada.
struct State {
  uint8_t hour = 0, minute = 0, second = 0; // hora LOCAL já resolvida
  uint8_t day = 1, month = 1;
  uint16_t year = 2026;
  uint8_t weekday = 0;       // 0 = domingo ... 6 = sábado
  bool timeValid = false;    // false -> desenha --:-- / --
  const char *stationName = "";  // usado só quando não há DiarioLogo.h
  const char *statusText = "";    // radio::connLabel(): "NO AR", "CONECTANDO"...
  const char *title = "";         // StreamTitle; "" quando não houver
};

// Abreviações pt-BR em ASCII (AGENTS.md 2.7: as fontes não têm acento).
inline const char *weekdayName(uint8_t w) {
  static const char *const N[7] = {"DOM", "SEG", "TER", "QUA", "QUI", "SEX", "SAB"};
  return N[w < 7 ? w : 0];
}
inline const char *monthName(uint8_t m) {
  static const char *const N[12] = {"JAN", "FEV", "MAR", "ABR", "MAI", "JUN",
                                    "JUL", "AGO", "SET", "OUT", "NOV", "DEZ"};
  return N[(m >= 1 && m <= 12) ? m - 1 : 0];
}

// ---------------------------------------------------------------------------
//  Cache da repintura parcial
// ---------------------------------------------------------------------------
//
// Mora no CHAMADOR, não em `static` de função. A armadilha 6 do AGENTS.md é
// exatamente estado estático herdado da visita anterior a uma tela — aqui basta
// zerar o Cache ao entrar (cacheReset) e o problema não existe.
struct Cache {
  bool painted = false;
  uint8_t hour = 255, minute = 255, second = 255;
  uint8_t day = 255, month = 255;
  uint16_t year = 0;
  bool timeValid = false;
  char status[16] = {0};
  uint32_t titleHash = 0;
  int16_t titleLen = 0;
  int16_t tickerPos = 0;
  uint32_t tickerAt = 0;
};

inline void cacheReset(Cache &c) {
  c = Cache();
}

namespace detail {

// FNV-1a de 32 bits. Só serve para detectar "o título mudou"; colisão aqui
// custa um letreiro desatualizado até a próxima música, não um bug.
inline uint32_t hashStr(const char *s) {
  uint32_t h = 2166136261u;
  for (; s && *s; ++s)
    h = (h ^ (uint8_t)*s) * 16777619u;
  return h;
}

inline void clearRect(LovyanGFX *dst, int ox, int oy, const Rect &r) {
  dst->fillRect(ox + r.x, oy + r.y, r.w, r.h, BG);
}

// Duas casas, ou "--" quando o relógio ainda não foi sincronizado.
inline void two(char *dst, int v, bool valid) {
  if (valid)
    snprintf(dst, 3, "%02d", v % 100);
  else {
    dst[0] = '-';
    dst[1] = '-';
    dst[2] = 0;
  }
}

} // namespace detail

// ---------------------------------------------------------------------------
//  Pintores
// ---------------------------------------------------------------------------

// O fundo sangra até a borda do raster: sem tarja preta em volta, senão a
// imagem parece pequena no tubo (AGENTS.md 2.5).
inline void drawBackground(LovyanGFX *dst, int ox, int oy) {
  if (!dst)
    return;
  dst->fillRect(ox, oy, crt::W, crt::H, BG);
}

// Logotipo, ou o nome da estação em texto quando não há o header gerado.
inline void drawLogo(LovyanGFX *dst, int ox, int oy, const State &s) {
  if (!dst)
    return;
  detail::clearRect(dst, ox, oy, LOGO_RECT);
#ifdef RADIOUI_HAVE_LOGO
  const int w = diariologo::WIDTH <= LOGO_MAX_W ? diariologo::WIDTH : LOGO_MAX_W;
  const int h = diariologo::HEIGHT <= LOGO_MAX_H ? diariologo::HEIGHT : LOGO_MAX_H;
  const int x = ox + LOGO_RECT.x + (LOGO_RECT.w - w) / 2;
  const int y = oy + LOGO_RECT.y + (LOGO_RECT.h - h) / 2;
  const lgfx::rgb565_t *px = reinterpret_cast<const lgfx::rgb565_t *>(diariologo::PIXELS);
  if (diariologo::HAS_TRANSPARENT)
    dst->pushImage(x, y, w, h, px, lgfx::rgb565_t(diariologo::TRANSPARENT));
  else
    dst->pushImage(x, y, w, h, px);
#else
  // Sem logotipo: o nome da estação em corpo grosso, centralizado na faixa.
  // Normaliza mesmo vindo de constante — é barato e fecha o caminho.
  char name[24];
  ascii::normalizeUpper(name, sizeof(name), s.stationName && *s.stationName ? s.stationName : "RADIO");
  const int y = LOGO_RECT.y + (LOGO_RECT.h - vcrfont::textHeight(2)) / 2;
  vcrfont::drawTextCentered(dst, name, ox + LOGO_RECT.x, oy + y, LOGO_RECT.w, ACCENT, 2);
#endif
}

// HH:MM. Contorno preto por glifo: no tubo o branco puro sobre azul "sangra" e
// o contorno devolve a borda (é a mesma técnica do OSD do player).
inline void drawHour(LovyanGFX *dst, int ox, int oy, const State &s) {
  if (!dst)
    return;
  detail::clearRect(dst, ox, oy, HOUR_RECT);
  char buf[8];
  detail::two(buf, s.hour, s.timeValid);
  buf[2] = ':';
  detail::two(buf + 3, s.minute, s.timeValid);
  vcrfont::drawText(dst, buf, ox + HOUR_RECT.x, oy + HOUR_RECT.y, INK, HOUR_SCALE, SHADOW);
}

// :SS — a única região que repinta uma vez por segundo, e a menor de todas.
inline void drawSeconds(LovyanGFX *dst, int ox, int oy, const State &s) {
  if (!dst)
    return;
  detail::clearRect(dst, ox, oy, SEC_RECT);
  char buf[8];
  buf[0] = ':';
  detail::two(buf + 1, s.second, s.timeValid);
  vcrfont::drawText(dst, buf, ox + SEC_RECT.x, oy + SEC_RECT.y, ACCENT, SEC_SCALE, SHADOW);
}

inline void drawDate(LovyanGFX *dst, int ox, int oy, const State &s) {
  if (!dst)
    return;
  detail::clearRect(dst, ox, oy, DATE_RECT);
  char buf[24];
  if (s.timeValid)
    snprintf(buf, sizeof(buf), "%s %02u %s %04u", weekdayName(s.weekday), (unsigned)s.day,
             monthName(s.month), (unsigned)s.year);
  else
    snprintf(buf, sizeof(buf), "--- -- --- ----");
  vcrfont::drawTextCentered(dst, buf, ox + DATE_RECT.x, oy + DATE_RECT.y, DATE_RECT.w, DIM, SMALL_SCALE);
}

// Linha de estado. "NO AR" ganha o acento; o resto fica cinza, para que a tela
// no ar não tenha nada competindo com o relógio.
inline void drawStatus(LovyanGFX *dst, int ox, int oy, const State &s) {
  if (!dst)
    return;
  detail::clearRect(dst, ox, oy, STATUS_RECT);
  char buf[20];
  ascii::normalizeUpper(buf, sizeof(buf), s.statusText ? s.statusText : "");
  if (!buf[0])
    return;
  const uint16_t color = strcmp(buf, "NO AR") == 0 ? ACCENT : DIM;
  vcrfont::drawTextCentered(dst, buf, ox + STATUS_RECT.x, oy + STATUS_RECT.y, STATUS_RECT.w, color,
                            SMALL_SCALE);
}

// Janela de TICKER_COLS caracteres do título, começando em `pos`.
//
// Quando o título cabe, `pos` é ignorado e o texto sai centralizado e parado —
// um letreiro que rola sem precisar é só ruído.
inline void tickerWindow(const char *title, int pos, char *dst, size_t cap) {
  char norm[160];
  ascii::normalizeUpper(norm, sizeof(norm), title ? title : "");
  const int n = (int)strlen(norm);
  if (n <= TICKER_COLS) {
    strncpy(dst, norm, cap - 1);
    dst[cap - 1] = 0;
    return;
  }
  // Separador entre o fim e o recomeço, para não emendar palavra com palavra.
  static const char SEP[] = "   ---   ";
  const int sep = (int)sizeof(SEP) - 1;
  const int period = n + sep;
  int p = pos % period;
  if (p < 0)
    p += period;
  size_t j = 0;
  for (int k = 0; k < TICKER_COLS && j + 1 < cap; ++k) {
    const int idx = (p + k) % period;
    dst[j++] = idx < n ? norm[idx] : SEP[idx - n];
  }
  dst[j] = 0;
}

inline void drawTicker(LovyanGFX *dst, int ox, int oy, const State &s, int pos) {
  if (!dst)
    return;
  detail::clearRect(dst, ox, oy, TICKER_RECT);
  if (!s.title || !*s.title)
    return;
  char win[TICKER_COLS + 2];
  tickerWindow(s.title, pos, win, sizeof(win));
  vcrfont::drawTextCentered(dst, win, ox + TICKER_RECT.x, oy + TICKER_RECT.y, TICKER_RECT.w, DIM,
                            SMALL_SCALE);
}

// Repintura completa. É o que as transições do ScreenFx.h chamam e o que
// `tick()` faz na primeira vez.
inline void draw(LovyanGFX *dst, int ox, int oy, const State &s) {
  if (!dst)
    return;
  dst->startWrite();
  drawBackground(dst, ox, oy);
  drawLogo(dst, ox, oy, s);
  drawHour(dst, ox, oy, s);
  drawSeconds(dst, ox, oy, s);
  drawDate(dst, ox, oy, s);
  drawStatus(dst, ox, oy, s);
  drawTicker(dst, ox, oy, s, 0);
  dst->endWrite();
}

// ---------------------------------------------------------------------------
//  Repintura incremental
// ---------------------------------------------------------------------------

// Repinta só o que mudou e devolve a máscara das regiões sujas (0 = nada
// mudou, e nesse caso NADA foi escrito no destino).
//
// `nowMs` é o millis() do chamador e só serve ao passo do letreiro. A
// comparação usa timeReached() porque o millis() dá a volta em ~49 dias — e
// `nowMs > c.tickerAt` cru é justamente o que a AGENTS.md 3.3 proíbe.
inline uint8_t tick(LovyanGFX *dst, int ox, int oy, const State &s, Cache &c, uint32_t nowMs) {
  if (!dst)
    return R_NONE;
  if (!c.painted) {
    draw(dst, ox, oy, s);
    c.painted = true;
    c.hour = s.hour;
    c.minute = s.minute;
    c.second = s.second;
    c.day = s.day;
    c.month = s.month;
    c.year = s.year;
    c.timeValid = s.timeValid;
    ascii::normalizeUpper(c.status, sizeof(c.status), s.statusText ? s.statusText : "");
    c.titleHash = detail::hashStr(s.title);
    c.titleLen = (int16_t)(s.title ? strlen(s.title) : 0);
    c.tickerPos = 0;
    c.tickerAt = nowMs + TICKER_STEP_MS;
    return R_ALL;
  }

  uint8_t dirty = R_NONE;
  const bool validChanged = (c.timeValid != s.timeValid);

  dst->startWrite();

  if (validChanged || c.second != s.second) {
    drawSeconds(dst, ox, oy, s);
    c.second = s.second;
    dirty |= R_SEC;
  }
  if (validChanged || c.minute != s.minute || c.hour != s.hour) {
    drawHour(dst, ox, oy, s);
    c.hour = s.hour;
    c.minute = s.minute;
    dirty |= R_HOUR;
  }
  if (validChanged || c.day != s.day || c.month != s.month || c.year != s.year) {
    drawDate(dst, ox, oy, s);
    c.day = s.day;
    c.month = s.month;
    c.year = s.year;
    dirty |= R_DATE;
  }
  c.timeValid = s.timeValid;

  char status[16];
  ascii::normalizeUpper(status, sizeof(status), s.statusText ? s.statusText : "");
  if (strcmp(status, c.status) != 0) {
    drawStatus(dst, ox, oy, s);
    memcpy(c.status, status, sizeof(status));
    dirty |= R_STATUS;
  }

  const uint32_t h = detail::hashStr(s.title);
  if (h != c.titleHash) {
    // Música nova: o letreiro recomeça do início, senão a primeira volta
    // entraria pelo meio do título.
    c.titleHash = h;
    c.titleLen = (int16_t)(s.title ? strlen(s.title) : 0);
    c.tickerPos = 0;
    c.tickerAt = nowMs + TICKER_STEP_MS;
    drawTicker(dst, ox, oy, s, 0);
    dirty |= R_TICKER;
  } else if (c.titleLen > TICKER_COLS && timeReached(nowMs, c.tickerAt)) {
    ++c.tickerPos;
    c.tickerAt = nowMs + TICKER_STEP_MS;
    drawTicker(dst, ox, oy, s, c.tickerPos);
    dirty |= R_TICKER;
  }

  dst->endWrite();
  return dirty;
}

} // namespace radioui

#pragma once
// ============================================================================
// RadioStream — cliente de rádio pela internet (Icecast/Shoutcast) do Fruit Jam
// Retro TV (fork do M5 RETRO TV).
//
// Entrega PCM 22050 Hz estéreo pelo MESMO contrato do mp3ReadPcm() do
// src/main.cpp, para que a tarefa de áudio não precise de um segundo caminho
// de saída: quem integra troca a fonte do bloco e o resto do audioTask —
// escala de volume, audioout::write(), ritmo pelo relógio de amostras —
// continua igual.
//
// ---------------------------------------------------------------------------
//  Por que cada decisão deste arquivo é assim
// ---------------------------------------------------------------------------
//
// 1. Rede pelo WiFiNINA (fj/Net.h): o Wi-Fi é o ESP32-C6 da placa, falando por
//    SPI1. http:// usa WiFiClient; https:// usa o TLS que roda DENTRO do C6
//    (connectSSL), sem custo de SRAM nem de pilha no RP2350 — ao contrário do
//    ESP32 original, onde um cliente TLS custava dezenas de KB de SRAM e por
//    isso era proibido aqui. A estação da tabela continua http://.
//
//    O SPI1 é um barramento só, disputado pelo loop(), pela previsão, pelo
//    radar e pelo relógio. TODA chamada WiFiNINA daqui roda com net::Lock
//    tomado, e o lock é tomado POR BLOCO lido, nunca pelo stream inteiro:
//    segurá-lo por uma sessão de rádio mataria de fome todo o resto da rede.
//
// 2. O buffer circular mora na PSRAM (QSPI, 8 MB, atrás de um cache de 16 KB).
//    Ele é o ÚNICO bloco grande deste módulo e é alocado com
//    heap_caps_malloc(MALLOC_CAP_SPIRAM); se a alocação falhar o módulo entra
//    em Conn::NoMemory e NÃO tenta a SRAM — cair de pé é melhor do que derrubar
//    o aparelho inteiro.
//
// 3. O de-interleave do icy-metaint acontece ANTES do buffer circular. O que
//    entra no anel é fluxo MP3 puro; o decodificador nunca vê um byte de
//    metadado. Se o bloco de metadado fosse para o anel, o libhelix perderia o
//    sync e o áudio viraria estalo a cada ~8 segundos.
//
// 4. Reconexão com backoff exponencial (1, 2, 4, 8, 16, 30 s). A armadilha 4 do
//    AGENTS.md — "retentativa sem backoff" — já mordeu este projeto: um portão
//    que só avançava no sucesso virava laço apertado criando tarefas HTTP
//    quando a rede caía.
//
// 5. A leitura da rede roda numa tarefa própria (RADIO_ICY) pinada no núcleo 1.
//    No arduino-pico o loop() é uma tarefa FreeRTOS presa ao núcleo 0, junto
//    com a interrupção de linha do DVI; uma chamada WiFiNINA espera o C6 em
//    laço ativo (SpiDrv::waitForSlaveReady não tem prazo nem cede a CPU), e
//    isso não pode acontecer no núcleo do desenho. A pilha é de 8 KB (em BYTES,
//    ver fj/Platform.h) e o maior local da tarefa tem 512 bytes; todo o resto
//    é estado da classe (armadilha 2 do AGENTS.md).
//
// 7. Redirecionamento: 301/302/303/307/308 com Location são seguidos até
//    MAX_REDIRECTS saltos dentro da mesma tentativa, inclusive de http:// para
//    https:// (o TLS é do C6). Cada reconexão recomeça da URL da TABELA, e não
//    do destino do último redirecionamento: servidores de rádio redirecionam
//    para URLs com token que expiram.
//
// 6. A lógica pura (parse de URL, parse de cabeçalho, de-interleave, parse do
//    StreamTitle, backoff) vive fora do #if defined(ARDUINO) e não depende de
//    Arduino, WiFi nem FreeRTOS. É isso que permite testá-la nativamente em
//    sim/probes/radio_stream.cpp com g++ -std=gnu++11.
//
// A parte pura compila em -std=gnu++11 (o upstream m5-retro-tv ainda é C++11 e
// este fork quer continuar puxando correções de lá): todo corpo de constexpr
// aqui é um único return, sem laço e sem variável local (armadilha 1).
// ============================================================================

#include <stddef.h>
#include <stdint.h>
#include <string.h>

#include <atomic>

#include "Ascii.h"   // normalização para ASCII: as fontes bitmap só têm ASCII
#include "UiLogic.h" // timeReached(): millis() dá a volta em ~49 dias

namespace radio {

// ---------------------------------------------------------------------------
//  Tabela de estações (tempo de compilação)
// ---------------------------------------------------------------------------
//
// Uma entrada hoje. A tabela existe desde já para que acrescentar estação seja
// acrescentar uma linha, e não reestruturar o módulo: STATION_COUNT vem do
// sizeof, então nada mais precisa ser tocado.

struct Station {
  const char *name; // rótulo curto, ASCII, para a tela quando não houver logo
  const char *url;  // http:// ou https:// (o TLS roda no ESP32-C6; nota 1)
};

constexpr Station STATIONS[] = {
    {"DIARIO FM", "http://51-222-26-208.webnow.com.br/diario.mp3"},
};

constexpr int STATION_COUNT = (int)(sizeof(STATIONS) / sizeof(STATIONS[0]));

// ---------------------------------------------------------------------------
//  Estado da conexão
// ---------------------------------------------------------------------------
//
// O pré-buffer conta como CONECTANDO de propósito: para quem está na frente da
// TV, "NO AR" tem que significar "já está saindo som", não "o socket abriu".

enum class Conn : uint8_t {
  Idle,       // módulo parado
  Connecting, // resolvendo/conectando/lendo cabeçalho/enchendo o pré-buffer
  OnAir,      // áudio saindo
  NoSignal,   // caiu ou recusou; esperando o backoff
  NoMemory    // PSRAM ou decodificador indisponível — não adianta tentar de novo
};

// Rótulos ASCII sem acento (AGENTS.md 2.7): as fontes bitmap só têm 0x20..0x7E.
inline const char *connLabel(Conn c) {
  return c == Conn::OnAir        ? "NO AR"
         : c == Conn::Connecting ? "CONECTANDO"
         : c == Conn::NoSignal   ? "SEM SINAL"
         : c == Conn::NoMemory   ? "SEM MEMORIA"
                                 : "PARADO";
}

// ---------------------------------------------------------------------------
//  Dimensionamento (ver o relatório de orçamento de memória no README do módulo)
// ---------------------------------------------------------------------------

// 96 kbps = 12.000 bytes/s. 64 KiB = 5,46 s de áudio.
//
// Por que 64 KiB e não mais nem menos: a rede Wi-Fi entrega em rajada e o
// aparelho ainda perde alguns milissegundos por varredura de canal e por
// retransmissão TCP. Meio segundo de anel não sobrevive a isso; 5,5 s
// sobrevivem com folga a uma pausa de rede completa. Mais do que isso só
// aumentaria a latência entre trocar de estação e ouvir som — e a PSRAM,
// apesar de sobrar, é lenta, então não há motivo para exagerar.
constexpr size_t RING_BYTES = 65536;

// Espelha o mp3In[4096] do src/main.cpp: mesma janela de entrada do libhelix.
constexpr size_t MP3_IN_BYTES = 4096;

// Espelha o mp3FramePcm[2304] do src/main.cpp: um frame MPEG1 estéreo (1152x2).
constexpr size_t MP3_PCM_SHORTS = 2304;

// Tudo numa alocação só: um caminho de falha em vez de três.
constexpr size_t PSRAM_BYTES = RING_BYTES + MP3_IN_BYTES + MP3_PCM_SHORTS * 2;

// Só declara OnAir depois de 2 s de áudio no anel. Evita o pior sintoma de
// rádio na internet: começar a tocar e engasgar três segundos depois.
constexpr size_t PREBUFFER_BYTES = 24576;

// Saída fixa do aparelho: o I2S1 é aberto a 22050 Hz estéreo pelo
// initExternalAudio() do src/main.cpp. O resampler linear abaixo leva qualquer
// taxa de origem (44100 na prática, mas lida do primeiro frame) para cá.
constexpr int OUT_RATE = 22050;

// ---------------------------------------------------------------------------
//  Backoff
// ---------------------------------------------------------------------------

constexpr uint32_t BACKOFF_MIN_MS = 1000;
constexpr uint32_t BACKOFF_MAX_MS = 30000;

// 1 s, 2, 4, 8, 16, depois 30 s para sempre. Determinístico de propósito: dá
// para testar (sim/probes/radio_stream.cpp) e, com uma estação só, não há
// rebanho de clientes para dispersar com jitter.
//
// C++11: corpo de constexpr é um único return, sem laço e sem local.
constexpr uint32_t backoffDelayMs(uint32_t attempt) {
  return attempt >= 5 ? BACKOFF_MAX_MS : (BACKOFF_MIN_MS << attempt);
}

// ---------------------------------------------------------------------------
//  Parse da URL
// ---------------------------------------------------------------------------

struct Url {
  char host[80];
  char path[144];
  uint16_t port;
  bool tls; // https://: a conexão é aberta por connectSSL, com o TLS no C6
};

// Aceita "http[s]://host[:porta][/caminho]". Sem esquema vale http://. No
// ESP32 original https:// era recusado (TLS custava SRAM demais); no Fruit Jam
// quem faz o TLS é o ESP32-C6, então ele passa a valer — é o que permite seguir
// um redirecionamento para https. Caminho vazio vira "/".
inline bool parseUrl(const char *url, Url &out) {
  out.host[0] = 0;
  out.path[0] = 0;
  out.port = 80;
  out.tls = false;
  if (!url)
    return false;
  const char *p = url;
  if (strncmp(p, "http://", 7) == 0) {
    p += 7;
  } else if (strncmp(p, "https://", 8) == 0) {
    p += 8;
    out.port = 443;
    out.tls = true;
  } else if (strstr(url, "://")) {
    return false; // esquema desconhecido
  }
  // Authority vai até '/', '?' ou fim.
  size_t h = 0;
  for (; *p && *p != '/' && *p != '?'; ++p) {
    if (*p == ':') {
      ++p;
      uint32_t v = 0;
      for (; *p >= '0' && *p <= '9'; ++p)
        v = v * 10 + (uint32_t)(*p - '0');
      if (!v || v > 65535)
        return false;
      out.port = (uint16_t)v;
      break;
    }
    if (h + 1 < sizeof(out.host))
      out.host[h++] = *p;
  }
  out.host[h] = 0;
  if (!h)
    return false;
  // Resto é o caminho (com query, se houver).
  while (*p && *p != '/' && *p != '?')
    ++p;
  size_t j = 0;
  if (*p != '/' && j + 1 < sizeof(out.path))
    out.path[j++] = '/';
  for (; *p && j + 1 < sizeof(out.path); ++p)
    out.path[j++] = *p;
  out.path[j] = 0;
  if (!j) {
    out.path[0] = '/';
    out.path[1] = 0;
  }
  return true;
}

// ---------------------------------------------------------------------------
//  Parse do cabeçalho de resposta
// ---------------------------------------------------------------------------

struct IcyInfo {
  int32_t status;  // código HTTP da linha de status; 0 se não lido
  int32_t metaint; // -1 quando o servidor não manda icy-metaint
  char name[40];   // icy-name  (ex.: "DIARIO FM")
  char desc[80];   // icy-description, quando houver
  // Location de um 3xx, CRU (não normalizado: é URL, não texto de tela). Vazio
  // quando não veio ou quando não coube inteiro — URL truncada é URL errada, e
  // seguir uma URL errada é pior do que desistir e cair no backoff.
  char location[sizeof(Url::host) + sizeof(Url::path) + 16];
  bool audio; // Content-Type é audio/mpeg (ou mp3)
};

inline void icyInfoInit(IcyInfo &i) {
  i.status = 0;
  i.metaint = -1;
  i.name[0] = 0;
  i.desc[0] = 0;
  i.location[0] = 0;
  i.audio = false;
}

// Códigos que mandam seguir o Location. 300 e 304 ficam de fora: não dizem
// para onde ir.
inline bool isRedirectStatus(int32_t status) {
  return status == 301 || status == 302 || status == 303 || status == 307 || status == 308;
}

namespace detail {

inline bool iEqPrefix(const char *s, const char *prefix) {
  for (size_t i = 0; prefix[i]; ++i) {
    const char a = s[i] >= 'A' && s[i] <= 'Z' ? (char)(s[i] + 32) : s[i];
    const char b = prefix[i] >= 'A' && prefix[i] <= 'Z' ? (char)(prefix[i] + 32) : prefix[i];
    if (!s[i] || a != b)
      return false;
  }
  return true;
}

inline const char *skipSpace(const char *s) {
  while (*s == ' ' || *s == '\t')
    ++s;
  return s;
}

// Copia já normalizado para ASCII: icy-name e icy-description vêm de fora e o
// AGENTS.md 2.7 exige normalizar tudo que venha de fora antes de desenhar.
inline void copyAscii(char *dst, size_t cap, const char *src) {
  ascii::normalize(dst, cap, src);
}

} // namespace detail

// Interpreta UMA linha de cabeçalho já sem o CRLF. Chamada pelo HeaderParser,
// exposta porque é o que o probe exercita diretamente.
inline void parseHeaderLine(const char *line, IcyInfo &out) {
  if (!line || !*line)
    return;
  if (detail::iEqPrefix(line, "HTTP/") || detail::iEqPrefix(line, "ICY ")) {
    // "HTTP/1.1 200 OK" ou "ICY 200 OK" (Shoutcast antigo).
    const char *p = line;
    while (*p && *p != ' ')
      ++p;
    p = detail::skipSpace(p);
    int32_t v = 0;
    while (*p >= '0' && *p <= '9')
      v = v * 10 + (*p++ - '0');
    out.status = v;
    return;
  }
  const char *colon = strchr(line, ':');
  if (!colon)
    return;
  const char *value = detail::skipSpace(colon + 1);
  if (detail::iEqPrefix(line, "icy-metaint:")) {
    int32_t v = 0;
    for (const char *p = value; *p >= '0' && *p <= '9'; ++p)
      v = v * 10 + (*p - '0');
    // metaint zero ou absurdo é tratado como "sem metadado": melhor perder o
    // título do que picotar o fluxo MP3 num intervalo errado.
    out.metaint = (v > 0 && v <= 1024 * 1024) ? v : -1;
  } else if (detail::iEqPrefix(line, "icy-name:")) {
    detail::copyAscii(out.name, sizeof(out.name), value);
  } else if (detail::iEqPrefix(line, "icy-description:")) {
    detail::copyAscii(out.desc, sizeof(out.desc), value);
  } else if (detail::iEqPrefix(line, "content-type:")) {
    out.audio = detail::iEqPrefix(value, "audio/mpeg") || detail::iEqPrefix(value, "audio/mp3") ||
                detail::iEqPrefix(value, "application/octet-stream");
  } else if (detail::iEqPrefix(line, "location:")) {
    size_t n = strlen(value);
    while (n && (value[n - 1] == ' ' || value[n - 1] == '\t'))
      --n;
    if (n && n < sizeof(out.location)) {
      memcpy(out.location, value, n);
      out.location[n] = 0;
    } else {
      out.location[0] = 0; // longa demais: não segue (ver IcyInfo::location)
    }
  }
}

// Resolve o Location de um redirecionamento contra a URL atual. Aceita URL
// absoluta (http:// ou https://) e caminho absoluto ("/novo"), que mantém
// host, porta e esquema. Recusa o resto (relativo sem barra, "//host", vazio):
// é raro em servidor de rádio e errar aqui seria conectar no lugar errado.
inline bool resolveRedirect(const Url &current, const char *location, Url &out) {
  if (!location || !*location)
    return false;
  if (location[0] == '/') {
    if (location[1] == '/')
      return false; // "//host/caminho": sem esquema, não arrisca
    out = current;
    size_t j = 0;
    for (const char *p = location; *p && j + 1 < sizeof(out.path); ++p)
      out.path[j++] = *p;
    out.path[j] = 0;
    return location[j] == 0; // caminho truncado = recusa
  }
  if (strncmp(location, "http://", 7) != 0 && strncmp(location, "https://", 8) != 0)
    return false;
  return parseUrl(location, out);
}

// Consome bytes do socket até o fim do cabeçalho (CRLF CRLF ou LF LF).
//
// Trabalha byte a byte porque o cabeçalho e o áudio chegam no MESMO read(): a
// função precisa devolver exatamente quantos bytes eram do cabeçalho para que
// o primeiro byte de áudio não seja perdido nem contado errado no metaint.
class HeaderParser {
public:
  void reset() {
    len_ = 0;
    cut_ = false;
    done_ = false;
    ok_ = false;
    redirect_ = false;
    icyInfoInit(info_);
  }

  // Devolve quantos bytes de `data` pertenciam ao cabeçalho. Se done(), o resto
  // (n - consumidos) já é o corpo e deve ir para o de-interleaver.
  size_t feed(const uint8_t *data, size_t n) {
    size_t i = 0;
    for (; i < n && !done_; ++i) {
      const char c = (char)data[i];
      if (c == '\r')
        continue; // CR é ignorado: trata CRLF e LF do mesmo jeito
      if (c != '\n') {
        if (size_t(len_) + 1 < sizeof(line_))
          line_[len_++] = c;
        else
          cut_ = true;
        continue;
      }
      line_[len_] = 0;
      if (!len_) {
        // Linha vazia: fim do cabeçalho.
        done_ = true;
        ok_ = (info_.status == 200) && info_.audio;
        redirect_ = isRedirectStatus(info_.status) && info_.location[0];
        ++i;
        break;
      }
      parseHeaderLine(line_, info_);
      // Linha cortada: icy-name e afins perdem so o fim, mas uma URL cortada
      // e uma URL ERRADA. Location truncado e descartado (ver IcyInfo).
      if (cut_ && detail::iEqPrefix(line_, "location:"))
        info_.location[0] = 0;
      cut_ = false;
      len_ = 0;
    }
    return i;
  }

  bool done() const { return done_; }
  bool ok() const { return ok_; }
  // 3xx com Location utilizável: o chamador resolve com resolveRedirect().
  bool redirect() const { return redirect_; }
  const IcyInfo &info() const { return info_; }

private:
  // 256 bytes: cabe icy-url, icy-genre e um Location com token. Uma linha mais
  // longa é truncada — o que se perde é o fim do valor, nunca o sincronismo do
  // fluxo, porque o corte é só na cópia e o byte continua sendo consumido.
  char line_[256];
  uint16_t len_ = 0;
  bool cut_ = false; // a linha em curso passou de line_ e foi truncada
  bool done_ = false;
  bool ok_ = false;
  bool redirect_ = false;
  IcyInfo info_;
};

// ---------------------------------------------------------------------------
//  StreamTitle
// ---------------------------------------------------------------------------

// Extrai o valor de StreamTitle='...'; de um bloco de metadados ICY.
//
// A regra do Icecast/Shoutcast é que o valor termina na sequência "';" — aspa
// simples SEGUIDA de ponto-e-vírgula. Uma aspa solta no meio é conteúdo, e é
// comum ("ROCK N' ROLL"). Cortar na primeira aspa truncaria esses títulos.
// Servidores que omitem o ';' final também existem: aí vale até o fim.
//
// Escreve em `dst` já normalizado para ASCII. Devolve true se achou o campo.
inline bool parseStreamTitle(const char *meta, char *dst, size_t cap) {
  if (!dst || !cap)
    return false;
  dst[0] = 0;
  if (!meta)
    return false;
  const char *k = strstr(meta, "StreamTitle='");
  if (!k)
    return false;
  const char *v = k + 13; // strlen("StreamTitle='")
  const char *e = strstr(v, "';");
  size_t n;
  if (e) {
    n = (size_t)(e - v);
  } else {
    // Sem o ';' final o valor vale ate o fim -- mas a aspa que FECHA o campo
    // ainda esta la e nao faz parte do titulo. Sem esta poda, um servidor que
    // manda StreamTitle='FULANO' sem ponto e virgula deixava a aspa sobrando
    // na tela. So a ultima e podada: uma aspa no meio e conteudo ("ROCK N'
    // ROLL") e continua intacta.
    n = strlen(v);
    if (n && v[n - 1] == '\'')
      --n;
  }
  // Buffer temporário pequeno e limitado: o título vive num campo de tela, não
  // faz sentido guardar mais do que cabe nele.
  char raw[160];
  if (n >= sizeof(raw))
    n = sizeof(raw) - 1;
  memcpy(raw, v, n);
  raw[n] = 0;
  ascii::normalize(dst, cap, raw);
  return true;
}

// ---------------------------------------------------------------------------
//  De-interleave do icy-metaint
// ---------------------------------------------------------------------------

// O servidor intercala, a cada `metaint` bytes de áudio, um bloco de metadado:
// um byte de comprimento (em unidades de 16 bytes) seguido de len*16 bytes de
// texto. Comprimento zero — o caso mais comum — significa "nada mudou".
//
// Esta máquina de estados devolve SÓ os bytes de áudio, contíguos, e não se
// importa com onde a leitura do socket cortou: um bloco de metadado partido
// entre duas leituras é retomado no ponto exato.
//
// `out` PODE ser o mesmo ponteiro que `in`: os bytes de áudio só andam para a
// esquerda, então a cópia in-place é segura e é o que a tarefa de rede usa para
// gastar 256 bytes de pilha em vez de 512.
class MetaSplitter {
public:
  void begin(int32_t metaint) {
    metaint_ = metaint;
    audioLeft_ = metaint > 0 ? (uint32_t)metaint : 0;
    stage_ = metaint > 0 ? Stage::Audio : Stage::Passthrough;
    metaLeft_ = 0;
    bufLen_ = 0;
    blocks_ = 0;
    titleNew_ = false;
    title_[0] = 0;
  }

  size_t split(const uint8_t *in, size_t n, uint8_t *out) {
    size_t w = 0, i = 0;
    if (stage_ == Stage::Passthrough) {
      if (out != in)
        memmove(out, in, n);
      return n;
    }
    while (i < n) {
      if (stage_ == Stage::Audio) {
        size_t k = n - i;
        if (k > audioLeft_)
          k = audioLeft_;
        if (k) {
          memmove(out + w, in + i, k);
          w += k;
          i += k;
          audioLeft_ -= (uint32_t)k;
        }
        if (!audioLeft_)
          stage_ = Stage::Length;
        continue;
      }
      if (stage_ == Stage::Length) {
        metaLeft_ = (uint32_t)in[i++] * 16u;
        bufLen_ = 0;
        ++blocks_;
        if (!metaLeft_)
          rearm();
        else
          stage_ = Stage::Meta;
        continue;
      }
      // Stage::Meta
      size_t k = n - i;
      if (k > metaLeft_)
        k = metaLeft_;
      for (size_t j = 0; j < k; ++j) {
        // Guarda só o começo do bloco. Um bloco ICY pode ter até 4080 bytes,
        // mas o StreamTitle vem primeiro e um título maior que isto não cabe na
        // tela de qualquer jeito. O RESTO CONTINUA SENDO CONSUMIDO — é isso que
        // mantém o de-interleave correto sem gastar 4 KB de SRAM.
        if (size_t(bufLen_) + 1 < sizeof(buf_))
          buf_[bufLen_++] = (char)in[i + j];
      }
      i += k;
      metaLeft_ -= (uint32_t)k;
      if (!metaLeft_) {
        buf_[bufLen_] = 0;
        char t[128];
        if (parseStreamTitle(buf_, t, sizeof(t))) {
          if (strcmp(t, title_) != 0) {
            memcpy(title_, t, sizeof(t));
            titleNew_ = true;
          }
        }
        rearm();
      }
    }
    return w;
  }

  const char *title() const { return title_; }
  bool takeTitleFlag() {
    const bool v = titleNew_;
    titleNew_ = false;
    return v;
  }
  uint32_t blocks() const { return blocks_; }
  int32_t metaint() const { return metaint_; }

private:
  enum class Stage : uint8_t { Passthrough, Audio, Length, Meta };

  void rearm() {
    audioLeft_ = (uint32_t)metaint_;
    stage_ = Stage::Audio;
  }

  int32_t metaint_ = -1;
  uint32_t audioLeft_ = 0;
  uint32_t metaLeft_ = 0;
  uint32_t blocks_ = 0;
  Stage stage_ = Stage::Passthrough;
  bool titleNew_ = false;
  uint16_t bufLen_ = 0;
  char buf_[224];  // janela de captura do bloco de metadado
  char title_[128]; // já normalizado para ASCII
};

// ---------------------------------------------------------------------------
//  Anel produtor-consumidor (um escritor, um leitor)
// ---------------------------------------------------------------------------
//
// A tarefa de rede (RADIO_ICY) escreve; a tarefa de áudio lê. Um índice
// por lado, cada um escrito por um único dono: não precisa de mutex, e não usar
// mutex aqui é de propósito — o áudio não pode nunca ficar esperando a rede.
class Ring {
public:
  void attach(uint8_t *mem, size_t size) {
    buf_ = mem;
    size_ = size;
    clear();
  }
  void clear() {
    head_.store(0, std::memory_order_relaxed);
    tail_.store(0, std::memory_order_relaxed);
  }
  size_t capacity() const { return size_; }
  size_t used() const {
    const size_t h = head_.load(std::memory_order_acquire);
    const size_t t = tail_.load(std::memory_order_acquire);
    return h >= t ? h - t : size_ - (t - h);
  }
  // Uma posição fica sempre vaga para distinguir cheio de vazio.
  size_t space() const { return size_ ? size_ - used() - 1 : 0; }

  size_t write(const uint8_t *src, size_t n) {
    if (!buf_)
      return 0;
    size_t free = space();
    if (n > free)
      n = free;
    size_t h = head_.load(std::memory_order_relaxed);
    const size_t first = (h + n <= size_) ? n : size_ - h;
    memcpy(buf_ + h, src, first);
    if (n > first)
      memcpy(buf_, src + first, n - first);
    h += n;
    if (h >= size_)
      h -= size_;
    head_.store(h, std::memory_order_release);
    return n;
  }

  size_t read(uint8_t *dst, size_t n) {
    if (!buf_)
      return 0;
    size_t avail = used();
    if (n > avail)
      n = avail;
    size_t t = tail_.load(std::memory_order_relaxed);
    const size_t first = (t + n <= size_) ? n : size_ - t;
    memcpy(dst, buf_ + t, first);
    if (n > first)
      memcpy(dst + first, buf_, n - first);
    t += n;
    if (t >= size_)
      t -= size_;
    tail_.store(t, std::memory_order_release);
    return n;
  }

private:
  uint8_t *buf_ = nullptr;
  size_t size_ = 0;
  std::atomic<size_t> head_;
  std::atomic<size_t> tail_;
};

} // namespace radio

// ===========================================================================
//  Daqui para baixo: só no aparelho (Arduino + WiFi + FreeRTOS + libhelix).
//  O simulador e os probes compilam apenas a lógica pura acima.
// ===========================================================================
#if defined(ARDUINO)

#include <Arduino.h>

// NUNCA <WiFi.h> aqui: o arduino-pico traz uma biblioteca WiFi própria (lwIP,
// para o CYW43 do Pico W) com classes WiFiClient/WiFiServer de mesmo nome. Com
// lib_ldf_mode = chain+, incluir as duas quebra o link em símbolo duplicado. A
// rede do Fruit Jam é o WiFiNINA, e ele chega por fj/Net.h.
#include "fj/Net.h"      // WiFiClient do WiFiNINA + net::Lock
#include "fj/Platform.h" // heap_caps_*, xTaskCreatePinnedToCore (pilha em BYTES)

#include "libhelix-mp3/mp3dec.h"

namespace radio {

// Timeouts. Todos comparados com timeReached() (aritmética sem sinal): o
// millis() é de 32 bits e dá a volta em ~49 dias (AGENTS.md 3.3).
//
// Não há timeout de conexão aqui: o connect do WiFiNINA é UMA transação SPI
// síncrona — o C6 resolve o nome, abre o TCP (e faz o handshake TLS, se for
// https) e só então responde. O prazo é o do firmware NINA (~3 s de TCP, mais o
// DNS). Não dá para cortar essa transação no meio: fj/Net.h explica por quê.
constexpr uint32_t HEADER_TIMEOUT_MS = 6000;
constexpr uint32_t STALL_TIMEOUT_MS = 6000; // socket aberto mas mudo: derruba

// Saltos de redirecionamento por tentativa (nota 7). Quatro cobrem http->https
// mais um balanceador; mais que isso é laço de configuração do servidor.
constexpr int MAX_REDIRECTS = 4;

// Leitura por bloco. O WiFiNINA traz até 1500 B do C6 por transação para um
// buffer próprio (WiFiSocketBuffer); ler 512 de cada vez esvazia esse buffer em
// três voltas sem SPI novo, e cada volta devolve o net::Lock a quem espera.
constexpr size_t NET_CHUNK = 512;

// Espera quando o socket está vazio. 96 kbps são 12 KB/s: 15 ms de sono ainda
// deixam o buffer do socket longe de encher, e cada consulta vazia a menos é
// uma transação SPI a menos na frente do loop() e das outras tarefas de rede.
constexpr uint32_t IDLE_POLL_MS = 15;

// Tarefa de rede. Pilha em BYTES (fj/Platform.h). Núcleo 1: o 0 é do loop() e
// da interrupção de linha do DVI, e o WiFiNINA espera o C6 em laço ativo.
// Prioridade 1: acima das tarefas ociosas e das de prioridade 0 (previsão,
// radar), abaixo do loop() e do áudio; o mutex do net::Lock herda prioridade,
// então o loop() nunca fica atrás desta tarefa por mais de um bloco.
constexpr uint32_t NET_TASK_STACK = 8192;
constexpr UBaseType_t NET_TASK_PRIO = 1;
constexpr BaseType_t NET_TASK_CORE = 1;

class Stream {
public:
  // -- ciclo de vida (chamado pelo loop()) ----------------------------------

  // Empresta buffers de trabalho em SRAM para o decodificador. `in` precisa de
  // MP3_IN_BYTES bytes e `pcm` de MP3_PCM_SHORTS int16. Chamar ANTES de
  // begin(). Sem isto os dois caem na PSRAM e o audio arrasta.
  void useWorkBuffers(uint8_t *in, size_t inCap, int16_t *pcm, size_t pcmShorts) {
    extIn_ = (in && inCap >= MP3_IN_BYTES) ? in : nullptr;
    extPcm_ = (pcm && pcmShorts >= MP3_PCM_SHORTS) ? pcm : nullptr;
  }

  // Aloca a PSRAM, inicializa o libhelix e cria a tarefa de rede.
  // Não bloqueia esperando a conexão: a tela mostra CONECTANDO enquanto isso.
  bool begin(int stationIndex) {
    if (running_)
      return true;
    if (netAlive_.load()) {
      // A tarefa da sessão anterior ainda está presa numa transação do NINA
      // (ver end()) e continua dona dos buffers. Recomeçar agora faria duas
      // tarefas escreverem no mesmo anel. A tela mostra SEM SINAL; entrar de
      // novo na tela daqui a pouco funciona.
      conn_.store((uint8_t)Conn::NoSignal);
      Serial.println("[M5RETRO] Radio: sessao anterior ainda encerrando");
      return false;
    }
    if (stationIndex < 0 || stationIndex >= STATION_COUNT)
      return false;
    station_ = stationIndex;
    if (!parseUrl(STATIONS[station_].url, url_)) {
      conn_.store((uint8_t)Conn::NoMemory);
      return false;
    }
    // O ANEL pode ficar na PSRAM: e escrito e lido em blocos grandes, e o
    // custo por byte da PSRAM se dilui na cópia. Os buffers de TRABALHO do
    // decodificador, nao: o libhelix le o fluxo de bits byte a byte da entrada
    // e escreve 4.608 B de PCM por quadro, e na PSRAM (acesso aleatorio atras
    // de um cache de 16 KB) ele nao acompanha 44100 Hz estereo. Era essa a
    // causa do audio arrastado no aparelho original -- o player de MP3 local
    // toca liso com o MESMO decoder porque os buffers dele sao estaticos em SRAM.
    //
    // Quem chama empresta os buffers do player local por useWorkBuffers(): os
    // dois nunca tocam ao mesmo tempo, entao custa zero de SRAM nova. Sem esse
    // emprestimo, cai na PSRAM e volta a arrastar.
    const bool trabalhoExterno = extIn_ && extPcm_;
    const size_t bytes = trabalhoExterno ? RING_BYTES : PSRAM_BYTES;
    psram_ = (uint8_t *)heap_caps_malloc(bytes, MALLOC_CAP_SPIRAM);
    if (!psram_) {
      conn_.store((uint8_t)Conn::NoMemory);
      Serial.println("[M5RETRO] Radio: sem PSRAM para o buffer");
      return false;
    }
    ring_.attach(psram_, RING_BYTES);
    if (trabalhoExterno) {
      mp3In_ = extIn_;
      mp3Pcm_ = extPcm_;
    } else {
      mp3In_ = psram_ + RING_BYTES;
      mp3Pcm_ = (int16_t *)(psram_ + RING_BYTES + MP3_IN_BYTES);
      Serial.println("[M5RETRO] Radio: buffers de trabalho na PSRAM (vai arrastar)");
    }
    // No RP2350 o alocador do libhelix (AllocatorExt) cai no malloc comum: os
    // ~25 KB de estado do decodificador ficam na SRAM, o que ajuda a vazão.
    dec_ = MP3InitDecoder();
    if (!dec_) {
      heap_caps_free(psram_);
      psram_ = nullptr;
      mp3In_ = nullptr;
      mp3Pcm_ = nullptr;
      ring_.attach(nullptr, 0);
      conn_.store((uint8_t)Conn::NoMemory);
      Serial.println("[M5RETRO] Radio: sem memoria para o decodificador MP3");
      return false;
    }
    resetDecoder();
    ascii::normalize(name_, sizeof(name_), STATIONS[station_].name);
    icyName_[0] = 0;
    title_[0] = 0;
    conn_.store((uint8_t)Conn::Connecting);
    stop_.store(false);
    orphan_.store(false);
    netAlive_.store(true);
    running_ = true;
    if (xTaskCreatePinnedToCore(netTaskEntry, "RADIO_ICY", NET_TASK_STACK, this, NET_TASK_PRIO,
                                nullptr, NET_TASK_CORE) != pdPASS) {
      netAlive_.store(false);
      running_ = false;
      releaseBuffers();
      conn_.store((uint8_t)Conn::NoMemory);
      return false;
    }
    return true;
  }

  // Encerra tudo. O chamador DEVE ter parado de chamar readPcm() antes (ou
  // seja: desligar o modo rádio do audioTask primeiro).
  //
  // Todas as esperas aqui têm prazo. A armadilha 3 do AGENTS.md foi exatamente
  // uma espera sem prazo que congelou o aparelho para sempre.
  //
  // O prazo de 3 s pode vencer com a tarefa ainda presa num connect do NINA
  // (DNS + TCP + TLS podem passar disso). Liberar os buffers nesse caso seria
  // uso depois de liberar quando a tarefa voltasse: então ela vira "órfã" e
  // libera sozinha ao sair. O acordo é um exchange atômico em `orphan_`, que
  // garante que exatamente um dos dois lados libera.
  void end() {
    if (!running_)
      return;
    stop_.store(true);
    const uint32_t limit = millis() + 3000;
    while (netAlive_.load() && !timeReached(millis(), limit))
      delay(10);
    const uint32_t limit2 = millis() + 500;
    while (pcmBusy_.load() && !timeReached(millis(), limit2))
      delay(5);
    running_ = false;
    conn_.store((uint8_t)Conn::Idle);
    if (netAlive_.load()) {
      orphan_.store(true);
      // Segunda olhada: a tarefa pode ter saído entre o load e o store. Quem
      // ganhar o exchange libera; se a tarefa já levou, não há o que fazer.
      if (netAlive_.load() || !orphan_.exchange(false)) {
        Serial.println("[M5RETRO] Radio: tarefa presa no NINA; ela libera ao sair");
        return;
      }
    }
    releaseBuffers();
  }

  // -- consumo de áudio (chamado pela tarefa de áudio) ----------------------

  // MESMO contrato do mp3ReadPcm() do src/main.cpp: escreve `samples` shorts
  // (pares L/R) a 22050 Hz e devolve quantos escreveu.
  //
  // Diferença de propósito em relação ao arquivo: quando o anel seca, isto
  // devolve SILÊNCIO em vez de 0. Devolver 0 faria o audioTask marcar
  // playbackFinished e derrubar a reprodução — e num rádio um engasgo de rede
  // não é fim de faixa.
  size_t readPcm(int16_t *dst, size_t samples) {
    pcmBusy_.store(true);
    size_t produced = 0;
    if (running_ && dec_ && conn_.load() == (uint8_t)Conn::OnAir)
      produced = decodeInto(dst, samples);
    // Zera a cauda so por higiene (o chamador nao vai escrever ali), e devolve
    // o que REALMENTE foi produzido -- nao `samples`.
    //
    // Devolver o total pedido fazia o chamador pacear um bloco inteiro mesmo
    // quando o decodificador tinha entregue um pedaco, e a diferenca ia para a
    // saida como SILENCIO no meio do som. Era isso que se ouvia como arrasto.
    // Um retorno honesto deixa o chamador escrever menos e esperar menos, e faz
    // o ramo `if (!amostras)` dele finalmente existir.
    for (size_t i = produced; i < samples; ++i)
      dst[i] = 0;
    pcmBusy_.store(false);
    return produced;
  }

  // -- leitura de estado (qualquer núcleo) ----------------------------------

  Conn state() const { return (Conn)conn_.load(); }
  const char *stateLabel() const { return connLabel(state()); }
  bool active() const { return running_; }
  int station() const { return station_; }

  // Nome da estação: o icy-name quando o servidor mandou, senão o da tabela.
  const char *stationName() const { return icyName_[0] ? icyName_ : name_; }

  // Título corrente (StreamTitle), já ASCII. String vazia quando não há.
  // Copiado sob uma trava curta porque a tarefa de rede pode reescrevê-lo.
  void copyTitle(char *dst, size_t cap) const {
    if (!dst || !cap)
      return;
    titleLock_.store(true);
    strncpy(dst, title_, cap - 1);
    dst[cap - 1] = 0;
    titleLock_.store(false);
  }

  uint32_t reconnects() const { return reconnects_.load(); }
  uint32_t bytesReceived() const { return bytesIn_.load(); }
  // 0..100: quanto do anel está cheio. Útil no `diag status`.
  uint8_t bufferPercent() const {
    return ring_.capacity() ? (uint8_t)((uint64_t)ring_.used() * 100 / ring_.capacity()) : 0;
  }
  // Taxa real lida do primeiro frame decodificado (não presumida).
  int sourceRate() const { return mp3Rate_; }
  int sourceChannels() const { return mp3Chans_; }
  int bitrateKbps() const { return bitrate_; }

private:
  void releaseBuffers() {
    if (dec_) {
      MP3FreeDecoder(dec_);
      dec_ = nullptr;
    }
    if (psram_) {
      heap_caps_free(psram_);
      psram_ = nullptr;
    }
    mp3In_ = nullptr;
    mp3Pcm_ = nullptr;
    ring_.attach(nullptr, 0);
  }

  // -- decodificação (espelha mp3ReadPcm do src/main.cpp) -------------------

  void resetDecoder() {
    mp3InLen_ = 0;
    mp3PcmCount_ = 0;
    phaseQ16_ = 0;
    mp3Rate_ = 44100;
    mp3Chans_ = 2;
  }

  size_t decodeInto(int16_t *dst, size_t samples) {
    size_t produced = 0;
    while (produced + 1 < samples) {
      if (mp3PcmCount_ == 0) {
        if (mp3InLen_ < 2048) {
          const size_t got = ring_.read(mp3In_ + mp3InLen_, MP3_IN_BYTES - mp3InLen_);
          if (!got && mp3InLen_ == 0)
            break; // anel seco: o chamador completa com silêncio
          mp3InLen_ += got;
        }
        unsigned char *in = mp3In_;
        int bytesLeft = (int)mp3InLen_;
        // MP3Decode devolve código de erro; a CONTAGEM de amostras vem de
        // MP3GetLastFrameInfo().outputSamps — igual ao src/main.cpp.
        const int err = MP3Decode(dec_, &in, &bytesLeft, mp3Pcm_, 0);
        const size_t consumed = (size_t)(in - mp3In_);
        if (consumed > 0) {
          memmove(mp3In_, in, mp3InLen_ - consumed);
          mp3InLen_ -= consumed;
        }
        if (err == 0) {
          MP3FrameInfo info;
          MP3GetLastFrameInfo(dec_, &info);
          mp3PcmCount_ = (size_t)info.outputSamps;
          phaseQ16_ = 0;
          mp3Rate_ = info.samprate; // taxa REAL do fluxo, não presumida
          mp3Chans_ = info.nChans;
          // O passo so muda quando o cabecalho do frame muda, entao sai do laco
          // interno -- era uma divisao dupla POR AMOSTRA. 44100 -> 22050 da 2.0.
          stepQ16_ = (uint32_t)(((uint64_t)mp3Rate_ << 16) / (uint32_t)OUT_RATE);
          if (info.bitrate > 0)
            bitrate_ = info.bitrate / 1000;
        } else if (consumed == 0) {
          // Não avançou: frame corrompido ou desincronizado. Descarta 1 byte e
          // tenta ressincronizar, sem laço apertado.
          if (mp3InLen_ > 0) {
            memmove(mp3In_, mp3In_ + 1, mp3InLen_ - 1);
            --mp3InLen_;
          } else {
            break;
          }
          continue;
        } else {
          continue; // consumiu mas falhou: tenta o próximo frame
        }
      }
      const int ch = mp3Chans_;
      const int framesIn = (int)(mp3PcmCount_ / ch);
      const int idx = (int)(phaseQ16_ >> 16);
      if (idx >= framesIn - 1) {
        mp3PcmCount_ = 0;
        continue;
      }
      const int32_t frac = (int32_t)(phaseQ16_ & 0xFFFFu);
      const int16_t *p0 = mp3Pcm_ + (size_t)idx * ch;
      const int16_t *p1 = p0 + ch;
      // MONO: mistura os dois canais ANTES de interpolar e escreve o mesmo
      // valor nas duas saidas -- uma interpolacao em vez de duas. Misturar
      // antes ou depois da o mesmo resultado, porque a interpolacao e linear.
      int32_t a, b;
      if (ch == 1) {
        a = p0[0];
        b = p1[0];
      } else {
        a = ((int32_t)p0[0] + (int32_t)p0[1]) / 2;
        b = ((int32_t)p1[0] + (int32_t)p1[1]) / 2;
      }
      // / 65536 e nao >> 16: (b - a) tem sinal, e o deslocamento arredondaria
      // para -infinito injetando DC (armadilha 12 do AGENTS.md).
      const int16_t v = (int16_t)(a + (b - a) * frac / 65536);
      dst[produced++] = v;
      dst[produced++] = v;
      phaseQ16_ += stepQ16_;
    }
    return produced;
  }

  // -- tarefa de rede -------------------------------------------------------

  static void netTaskEntry(void *self) {
    static_cast<Stream *>(self)->netTask();
  }

  void netTask() {
    uint32_t attempt = 0;
    while (!stop_.load()) {
      if (sessionOnce())
        attempt = 0; // sessão útil: o próximo tropeço recomeça do 1 s
      if (stop_.load())
        break;
      conn_.store((uint8_t)Conn::NoSignal);
      // Backoff: dorme em fatias para continuar respondendo ao end().
      const uint32_t wait = backoffDelayMs(attempt);
      const uint32_t until = millis() + wait;
      Serial.printf("[M5RETRO] Radio: reconecta em %lums\n", (unsigned long)wait);
      while (!stop_.load() && !timeReached(millis(), until))
        vTaskDelay(pdMS_TO_TICKS(100));
      if (attempt < 5)
        ++attempt;
      reconnects_.fetch_add(1);
    }
    netAlive_.store(false);
    // end() desistiu de esperar e deixou a limpeza para cá (ver end()).
    if (orphan_.exchange(false))
      releaseBuffers();
    vTaskDelete(nullptr);
  }

  // Fecha o socket no NINA. Sem isto o C6 fica com o slot ocupado — ele tem
  // poucos (CONFIG_LWIP_MAX_SOCKETS), divididos com a previsão e o radar. Se
  // connected() já tinha visto a queda, stop() não faz nada: o próprio NINA
  // liberou o slot naquela consulta.
  static void closeClient(WiFiClient &client) {
    net::Lock lock;
    client.stop();
  }

  // Lê um bloco com o lock tomado SÓ durante a leitura. `alive` diz se o socket
  // continua de pé. Depois de alive == false o WiFiClient não pode mais ser
  // lido: o connected() do WiFiNINA já pôs o socket em 255, e read() não confere
  // isso (indexaria o WiFiSocketBuffer fora da tabela).
  static int readBlock(WiFiClient &client, uint8_t *buf, size_t cap, bool &alive) {
    net::Lock lock;
    const int n = client.read(buf, cap);
    alive = n > 0 || client.connected();
    return n;
  }

  enum class Header : uint8_t { Audio, Redirect, Fail };

  // Conecta em cur_, manda o GET e consome o cabeçalho. Em Header::Audio o
  // socket fica aberto e a sobra do último read já foi para o anel; nos outros
  // casos ele já foi fechado.
  Header openAndReadHeader(WiFiClient &client, uint8_t *buf) {
    header_.reset();
    int ok;
    {
      // O lock fica tomado durante o connect inteiro (DNS + TCP + TLS no C6):
      // entre reservar o socket e abri-lo nenhuma outra tarefa pode falar com o
      // NINA, senao ela pegaria o mesmo numero de socket.
      net::Lock lock;
      ok = cur_.tls ? client.connectSSL(cur_.host, cur_.port) : client.connect(cur_.host, cur_.port);
      if (!ok)
        client.stop(); // se o NINA chegou a reservar o socket, devolve
    }
    if (!ok) {
      Serial.printf("[M5RETRO] Radio: falha ao conectar em %s:%u%s\n", cur_.host,
                    (unsigned)cur_.port, cur_.tls ? " (TLS)" : "");
      return Header::Fail;
    }
    // Host leva a porta quando ela não é a padrão do esquema (RFC 9110 7.2).
    char hostPort[8] = {0};
    if (cur_.port != (cur_.tls ? 443 : 80))
      snprintf(hostPort, sizeof(hostPort), ":%u", (unsigned)cur_.port);
    // Icy-MetaData: 1 pede o título da música. Connection: close porque não há
    // reuso a fazer — este socket fica aberto até cair. O pedido é montado no
    // próprio buffer de leitura: um local a menos na pilha da tarefa.
    const int len = snprintf((char *)buf, NET_CHUNK,
                             "GET %s HTTP/1.1\r\n"
                             "Host: %s%s\r\n"
                             "User-Agent: RetroTV/1.0 (Fruit Jam)\r\n"
                             "Icy-MetaData: 1\r\n"
                             "Connection: close\r\n"
                             "\r\n",
                             cur_.path, cur_.host, hostPort);
    if (len <= 0 || (size_t)len >= NET_CHUNK) {
      closeClient(client);
      return Header::Fail;
    }
    size_t sent;
    {
      net::Lock lock;
      sent = client.write(buf, (size_t)len);
    }
    if (sent != (size_t)len) {
      closeClient(client);
      return Header::Fail;
    }

    const uint32_t hdrDeadline = millis() + HEADER_TIMEOUT_MS;
    while (!stop_.load() && !header_.done()) {
      if (timeReached(millis(), hdrDeadline)) {
        closeClient(client);
        return Header::Fail;
      }
      bool alive = false;
      const int n = readBlock(client, buf, NET_CHUNK, alive);
      if (n <= 0) {
        if (!alive) {
          closeClient(client);
          return Header::Fail;
        }
        vTaskDelay(pdMS_TO_TICKS(IDLE_POLL_MS));
        continue;
      }
      const size_t used = header_.feed(buf, (size_t)n);
      if (!header_.done())
        continue;
      if (header_.redirect()) {
        closeClient(client);
        return Header::Redirect;
      }
      if (!header_.ok()) {
        Serial.printf("[M5RETRO] Radio: resposta invalida (status %ld)\n",
                      (long)header_.info().status);
        closeClient(client);
        return Header::Fail;
      }
      const IcyInfo &icy = header_.info();
      if (icy.name[0]) {
        strncpy(icyName_, icy.name, sizeof(icyName_) - 1);
        icyName_[sizeof(icyName_) - 1] = 0;
      }
      splitter_.begin(icy.metaint);
      Serial.printf("[M5RETRO] Radio: %s metaint:%ld\n", stationName(), (long)icy.metaint);
      // A sobra do MESMO read já é corpo: passa pelo de-interleave in-place.
      if ((size_t)n > used) {
        const size_t got = splitter_.split(buf + used, (size_t)n - used, buf);
        ring_.write(buf, got);
        bytesIn_.fetch_add((uint32_t)got);
      }
      return Header::Audio;
    }
    closeClient(client); // end() pediu para parar
    return Header::Fail;
  }

  // Uma sessão HTTP completa. Devolve true se chegou a entrar no ar.
  //
  // Locais: `buf[512]` e uma Url. A pilha desta tarefa é de 8 KB e duas tarefas
  // já a estouraram no upstream (AGENTS.md 2.3) — nada de array grande aqui.
  bool sessionOnce() {
    conn_.store((uint8_t)Conn::Connecting);
    ring_.clear();
    resetDecoder();
    // Sempre da tabela: um redirecionamento anterior pode ter levado a uma URL
    // com token que já expirou (nota 7).
    cur_ = url_;
    WiFiClient client;
    uint8_t buf[NET_CHUNK]; // único local grande da tarefa
    for (int hop = 0;; ++hop) {
      const Header h = openAndReadHeader(client, buf);
      if (h == Header::Audio)
        break;
      if (h != Header::Redirect || stop_.load())
        return false;
      if (hop >= MAX_REDIRECTS) {
        Serial.println("[M5RETRO] Radio: redirecionamentos demais");
        return false;
      }
      Url next;
      if (!resolveRedirect(cur_, header_.info().location, next)) {
        Serial.printf("[M5RETRO] Radio: redirecionamento recusado (%ld)\n",
                      (long)header_.info().status);
        return false;
      }
      cur_ = next;
      Serial.printf("[M5RETRO] Radio: redirecionado para %s%s:%u%s\n",
                    cur_.tls ? "https://" : "http://", cur_.host, (unsigned)cur_.port, cur_.path);
    }
    if (stop_.load()) {
      closeClient(client);
      return false;
    }

    // --- corpo ---
    uint32_t lastData = millis();
    bool onAir = false;
    while (!stop_.load()) {
      if (timeReached(millis(), lastData + STALL_TIMEOUT_MS)) {
        Serial.println("[M5RETRO] Radio: fluxo mudo, derrubando");
        break;
      }
      // Anel quase cheio: o decodificador está atrasado. Espera em vez de
      // descartar, porque descartar byte de MP3 é estalo garantido. O prazo de
      // silêncio é renovado aqui: quem parou foi o consumidor, não o servidor.
      if (ring_.space() < NET_CHUNK) {
        lastData = millis();
        vTaskDelay(pdMS_TO_TICKS(20));
        continue;
      }
      bool alive = false;
      const int n = readBlock(client, buf, NET_CHUNK, alive);
      if (n <= 0) {
        if (!alive)
          break; // o NINA já soltou o socket; closeClient abaixo é inócuo
        vTaskDelay(pdMS_TO_TICKS(IDLE_POLL_MS));
        continue;
      }
      lastData = millis();
      // in-place: os bytes de áudio só andam para a esquerda.
      const size_t got = splitter_.split(buf, (size_t)n, buf);
      if (got)
        ring_.write(buf, got);
      bytesIn_.fetch_add((uint32_t)got);
      if (splitter_.takeTitleFlag())
        publishTitle(splitter_.title());
      if (!onAir && ring_.used() >= PREBUFFER_BYTES) {
        onAir = true;
        conn_.store((uint8_t)Conn::OnAir);
        Serial.println("[M5RETRO] Radio: no ar");
      }
    }
    closeClient(client);
    return onAir;
  }

  void publishTitle(const char *t) {
    // Trava de ocupado curtíssima: uma cópia de <=128 bytes. Não é um mutex de
    // verdade e não precisa ser — a alternativa (leitor ver meia string) só
    // afetaria um quadro de texto.
    while (titleLock_.load())
      vTaskDelay(1);
    strncpy(title_, t, sizeof(title_) - 1);
    title_[sizeof(title_) - 1] = 0;
    Serial.printf("[M5RETRO] Radio: %s\n", title_);
  }

  // -- estado ---------------------------------------------------------------

  Url url_{};  // da tabela
  Url cur_{};  // da tentativa em curso (pode ser destino de redirecionamento)
  int station_ = 0;
  bool running_ = false;

  uint8_t *psram_ = nullptr;
  Ring ring_;
  unsigned char *mp3In_ = nullptr;
  int16_t *mp3Pcm_ = nullptr;

  HMP3Decoder dec_ = nullptr;
  size_t mp3InLen_ = 0, mp3PcmCount_ = 0;
  int mp3Rate_ = 44100, mp3Chans_ = 2, bitrate_ = 0;
  // Buffers de trabalho emprestados pelo chamador (SRAM). Nao sao liberados
  // aqui: o dono e quem emprestou.
  uint8_t *extIn_ = nullptr;
  int16_t *extPcm_ = nullptr;
  // Fase e passo do reamostrador em Q16 (eram `double`; ver decodeInto).
  uint32_t phaseQ16_ = 0;
  uint32_t stepQ16_ = 1u << 16;

  HeaderParser header_;
  MetaSplitter splitter_;

  char name_[40] = {0};    // da tabela
  char icyName_[40] = {0}; // do servidor
  char title_[128] = {0};

  std::atomic<uint8_t> conn_{(uint8_t)Conn::Idle};
  std::atomic<bool> stop_{false};
  std::atomic<bool> netAlive_{false};
  std::atomic<bool> orphan_{false}; // end() desistiu de esperar: a tarefa libera
  std::atomic<bool> pcmBusy_{false};
  mutable std::atomic<bool> titleLock_{false};
  std::atomic<uint32_t> reconnects_{0};
  std::atomic<uint32_t> bytesIn_{0};
};

} // namespace radio

#endif // ARDUINO

#pragma once
// ============================================================================
// Relogio do Fruit Jam Retro TV: NTP do ESP32-C6 + fuso do Brasil.
//
// O QUE MUDOU EM RELACAO AO M5 RETRO TV
//
// No Core2 havia um BM8563 com bateria: a hora sobrevivia sem Wi-Fi e o NTP so
// a corrigia. O Fruit Jam nao tem RTC nenhum (PORTING.md 1). A unica fonte de
// hora e o NTP que o proprio ESP32-C6 faz sozinho depois de conectar (o
// firmware NINA chama esp_sntp_init com 0/1/2.pool.ntp.org) e que chega aqui
// por net::ntpEpoch() -> WiFi.getTime().
//
// Consequencias:
//
//  1. Sem Wi-Fi a hora e DESCONHECIDA. Nada de chutar 1970 ou 2000: a fonte
//     fica SOURCE_NONE, synced()/hasTime() devolvem false e a interface mostra
//     "--:--". O time() do sistema continua abaixo de 2024, e os testes do
//     main.cpp (`time(nullptr) >= 1704067200`) seguem valendo sem mudanca.
//  2. Os servidores passados a configTimeBrazil() sao IGNORADOS: o NINA nao
//     expoe como troca-los. A assinatura fica para o main.cpp nao mudar.
//  3. A consulta ao NINA passa pelo SPI1, dividido com o radio, a previsao e o
//     radar sob net::Lock. Uma consulta HTTPS de outra tarefa segura esse lock
//     por segundos. Se o loop() perguntasse a hora direto, congelaria junto.
//     Por isso a pergunta roda numa tarefa curta (RTC_NTP) que consulta,
//     publica por std::atomic e morre — o mesmo padrao das tarefas
//     WEATHER_HTTP e RADAR_HTTPS (AGENTS.md 3.2). O loop() so le o atomico.
//
// COMO FUNCIONA
//
//   setup  -> begin()             aplica o fuso; nao ha hora ainda
//   rede   -> configTimeBrazil()  aplica o fuso e LIGA as consultas
//   loop   -> poll()              no maximo 1x/s: aplica a hora que a tarefa
//                                 trouxe (settimeofday) ou dispara outra
//
// Enquanto o NINA ainda nao sincronizou (WiFi.getTime() devolve 0), as
// consultas seguem com backoff de 2, 4, 8, 16, 32 e 60 s — nunca laco apertado
// criando tarefa (armadilha 4 do AGENTS.md). Depois do primeiro acerto, uma
// nova consulta a cada 6 h corrige a deriva do cristal do RP2350.
//
// O fuso e aplicado pela libc (newlib do arduino-pico), via TZ + tzset(). A
// conversao data->epoch continua em aritmetica pura (algoritmo de dias civis),
// sem mktime e sem mexer em TZ no meio do caminho.
//
// CUSTO
//
// Estado num unico `static` de funcao (< 40 bytes de SRAM) mais tres atomicos.
// A tarefa RTC_NTP existe so durante uma consulta (3 KB de pilha, transitorios).
//
// C++11 na parte pura (sim/probes/rtc_clock.cpp). ASCII puro no texto de tela.
// ============================================================================

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#if defined(ARDUINO)
#define RTCCLOCK_HARDWARE 1
#include <Arduino.h>
#include <sys/time.h>

#include <atomic>

#include "UiLogic.h"     // timeReached(): millis() da a volta em ~49 dias
#include "fj/Net.h"      // net::ntpEpoch(), net::radioReady()
#include "fj/Platform.h" // xTaskCreatePinnedToCore com pilha em bytes
#else
// Compilacao nativa (sim/probes): so a logica pura fica disponivel.
#define RTCCLOCK_HARDWARE 0
#endif

namespace rtcclock {

// --------------------------------------------------------------------------
// Fuso horario
// --------------------------------------------------------------------------

// Horario de Brasilia, UTC-3, SEM horario de verao. O Brasil revogou o horario
// de verao em 2019 (Decreto 9.772/2019), entao nao existe regra de transicao a
// implementar — e inventar uma deixaria o relogio uma hora errado meio ano.
//
// Formato POSIX: o nome entre <> e obrigatorio porque "-03" comeca com sinal, e
// o numero apos o nome e quanto somar a hora LOCAL para chegar em UTC. Logo
// "3" significa UTC-3, nao UTC+3. Sem virgula depois = sem horario de verao.
//
// A forma entre <> e suportada pelo newlib (o parser de `_tzset_unlocked_r`
// compara com '<' e '>'), pelo glibc e pelo tzcode do macOS. Ainda assim
// `applyTimezone()` confere o resultado e cai para "BRT3", que e ASCII
// alfabetico puro, se o parser de alguma versao nao aceitar.
static const char TZ_BRASILIA[] = "<-03>3";
static const char TZ_BRASILIA_FALLBACK[] = "BRT3";

// Deslocamento esperado: -3 h. Serve de criterio do autoteste de TZ.
static const long UTC_OFFSET_SECONDS = -3L * 3600L;

// --------------------------------------------------------------------------
// Janela de plausibilidade
// --------------------------------------------------------------------------

// 2020-01-01T00:00:00Z. Abaixo disto a data e lixo: um ESP32-C6 que ainda nao
// sincronizou marca algo perto de 1970, e o NINA so zera abaixo de 2000. O
// firmware usa 1704067200 (2024) como "houve NTP"; aqui basta rejeitar o lixo.
static const time_t EPOCH_MIN = 1577836800; // 2020-01-01
static const time_t EPOCH_MAX = 4102444800; // 2100-01-01

// De quanto em quanto tempo reconsultar o NINA depois do primeiro acerto. O
// cristal do RP2350 (12 MHz, algumas dezenas de ppm) deriva menos de 1 s nesse
// intervalo; mais vezes so gastaria SPI1.
static const uint32_t RESYNC_INTERVAL_MS = 6UL * 3600UL * 1000UL; // 6 h
// Nome antigo (era a reescrita periodica do BM8563). Fica por compatibilidade.
static const uint32_t REWRITE_INTERVAL_MS = RESYNC_INTERVAL_MS;

// Tolerancia para reaplicar a hora numa ressincronizacao. O NINA devolve
// segundos inteiros; reaplicar abaixo disto so faria o relogio da tela pular
// para tras ate 1 s sem ganho nenhum.
static const int32_t STEP_TOLERANCE_S = 2;

// Backoff das consultas enquanto o NINA ainda nao tem hora: 2, 4, 8, 16, 32 e
// depois 60 s para sempre. C++11: constexpr de um unico return.
static const uint32_t QUERY_BACKOFF_MIN_MS = 2000;
static const uint32_t QUERY_BACKOFF_MAX_MS = 60000;
constexpr uint32_t queryBackoffMs(uint32_t attempt) {
  return attempt >= 5 ? QUERY_BACKOFF_MAX_MS : (QUERY_BACKOFF_MIN_MS << attempt);
}

// --------------------------------------------------------------------------
// Logica pura — testavel no PC (sim/probes/rtc_clock.cpp)
// --------------------------------------------------------------------------

inline int daysInMonth(int year, int month) {
  if (month < 1 || month > 12)
    return 0;
  if (month == 2)
    return ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0) ? 29 : 28;
  const int table[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
  return table[month - 1];
}

// Dias civis desde 1970-01-01 (algoritmo days_from_civil de Howard Hinnant).
// Calendario gregoriano proleptico, sem tabela e sem laco.
inline int64_t daysFromCivil(int year, int month, int day) {
  year -= (month <= 2) ? 1 : 0;
  const int64_t era = (year >= 0 ? year : year - 399) / 400;
  const int64_t yoe = int64_t(year) - era * 400;                       // [0, 399]
  const int64_t doy = (153 * (month + (month > 2 ? -3 : 9)) + 2) / 5 + day - 1;
  const int64_t doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;           // [0, 146096]
  return era * 146097 + doe - 719468;
}

// Data/hora **em UTC** -> epoch. Equivale a `timegm()`, que o newlib nao tem.
inline time_t epochFromUtc(int year, int month, int day, int hour, int minute, int second) {
  return time_t(daysFromCivil(year, month, day) * 86400LL + int64_t(hour) * 3600LL +
                int64_t(minute) * 60LL + int64_t(second));
}

// Criterio de uma data vinda de fora. Era o filtro da leitura do BM8563; fica
// porque a bancada nativa o exercita e porque qualquer fonte futura (GPS, RTC
// externo no STEMMA QT) precisa do mesmo crivo.
inline bool isPlausibleDate(int year, int month, int day, int hour, int minute, int second) {
  if (year < 2020 || year > 2099)
    return false;
  if (month < 1 || month > 12)
    return false;
  if (day < 1 || day > daysInMonth(year, month))
    return false;
  if (hour < 0 || hour > 23)
    return false;
  if (minute < 0 || minute > 59)
    return false;
  if (second < 0 || second > 60) // 60 cobre segundo bissexto
    return false;
  return true;
}

inline bool isPlausibleEpoch(time_t t) { return t >= EPOCH_MIN && t < EPOCH_MAX; }

// --------------------------------------------------------------------------
// Fonte da hora, para a tela SISTEMA
// --------------------------------------------------------------------------

enum Source : uint8_t {
  SOURCE_NONE = 0, // nao ha hora confiavel: a tela mostra --:--
  SOURCE_RTC = 1,  // nunca acontece no Fruit Jam (sem RTC); fica pelo rotulo
  SOURCE_NTP = 2   // acertada pelo NTP do ESP32-C6
};

// ASCII sem acento: vai direto para a tela.
inline const char *sourceLabel(Source s) {
  switch (s) {
  case SOURCE_RTC:
    return "RTC";
  case SOURCE_NTP:
    return "NTP";
  default:
    return "SEM HORA";
  }
}

// --------------------------------------------------------------------------
// Estado (num static de funcao inline: um por programa)
// --------------------------------------------------------------------------

struct State {
  time_t baseEpoch;     // epoch do ultimo acerto
  const char *tz;       // string de TZ que de fato vingou (ponteiro para literal)
  uint32_t baseMs;      // millis() correspondente
  uint32_t lastPollMs;
  uint32_t nextQueryMs; // quando disparar a proxima consulta ao NINA
  uint8_t attempt;      // consultas seguidas sem hora (indice do backoff)
  Source source;
  bool requested; // configTimeBrazil() ja foi chamado: pode consultar
  bool tzApplied;
};

inline State &state() {
  static State s = {0, NULL, 0, 0, 0, 0, SOURCE_NONE, false, false};
  return s;
}

inline Source source() { return state().source; }
inline const char *sourceLabel() { return sourceLabel(state().source); }
inline bool synced() { return state().source != SOURCE_NONE; }
// "Tem hora valida?" — o que as telas perguntam antes de desenhar HH:MM. Falso
// ate o primeiro acerto do NTP nesta sessao: sem RTC, reiniciar zera a hora.
inline bool hasTime() { return synced(); }
// Sem RTC na placa. Ficam para a tela SISTEMA e o `diag status` nao mudarem.
inline bool present() { return false; }
inline bool batteryLow() { return false; }
inline long utcOffsetSeconds() { return UTC_OFFSET_SECONDS; }
// String de TZ em vigor, para a tela SISTEMA e para o `diag status`.
inline const char *timezoneString() { return state().tz ? state().tz : TZ_BRASILIA; }

// --------------------------------------------------------------------------
// TZ
// --------------------------------------------------------------------------

// Confere se o TZ em vigor de fato coloca o horario local 3 h atras do UTC.
// Usa uma data de janeiro so para nao depender de nada: sem horario de verao o
// deslocamento e o mesmo o ano inteiro.
inline bool timezoneOffsetOk() {
  const time_t probe = 1767225600; // 2026-01-01T00:00:00Z
  struct tm local;
  memset(&local, 0, sizeof(local));
  if (!localtime_r(&probe, &local))
    return false;
  const time_t asUtc = epochFromUtc(local.tm_year + 1900, local.tm_mon + 1, local.tm_mday,
                                    local.tm_hour, local.tm_min, local.tm_sec);
  return (long)(asUtc - probe) == UTC_OFFSET_SECONDS;
}

// Impoe o fuso do Brasil. Idempotente e barata: so mexe no ambiente se o TZ
// atual for outro (alguma biblioteca pode reescrever TZ pelas costas; o poll()
// rechama isto de proposito).
inline bool applyTimezone() {
  State &s = state();
  const char *current = getenv("TZ");
  // Caminho rapido, que e o do loop(): se o TZ do ambiente ainda e o que nos
  // instalamos, nao ha nada a fazer e o custo e um strcmp de 6 bytes.
  if (s.tzApplied && current && s.tz && strcmp(current, s.tz) == 0)
    return true;

  setenv("TZ", TZ_BRASILIA, 1);
  tzset();
  if (timezoneOffsetOk()) {
    s.tz = TZ_BRASILIA;
    s.tzApplied = true;
    return true;
  }
  // Parser de TZ sem suporte a <...>: cai para a forma alfabetica.
  setenv("TZ", TZ_BRASILIA_FALLBACK, 1);
  tzset();
  s.tz = TZ_BRASILIA_FALLBACK;
  s.tzApplied = timezoneOffsetOk();
  return s.tzApplied;
}

// --------------------------------------------------------------------------
// Aparelho: NTP do ESP32-C6 pelo NINA
// --------------------------------------------------------------------------

#if RTCCLOCK_HARDWARE

namespace detail {

// Handoff tarefa -> loop(). `phase` diz em que pe esta a consulta; `epoch` e
// `atMs` so valem quando phase == NTP_DONE (a tarefa grava os dois ANTES de
// publicar a fase, com release; o loop le a fase com acquire).
enum : uint8_t { NTP_IDLE = 0, NTP_RUNNING = 1, NTP_DONE = 2 };

struct Handoff {
  std::atomic<uint8_t> phase;
  std::atomic<uint32_t> epoch; // 0 = o NINA ainda nao tem hora
  std::atomic<uint32_t> atMs;  // millis() do instante da consulta
};

inline Handoff &handoff() {
  static Handoff h = {{NTP_IDLE}, {0}, {0}};
  return h;
}

// Pilha em BYTES (fj/Platform.h). net::ntpEpoch() e uma transacao SPI curta e
// nao aloca nada grande; 3 KB deixam folga para o driver do WiFiNINA.
static const uint32_t NTP_TASK_STACK = 3072;

inline void ntpTask(void *) {
  Handoff &h = handoff();
  // net::ntpEpoch() toma o net::Lock sozinho. Se outra tarefa estiver no meio
  // de um HTTPS, e AQUI que se espera — nunca no loop().
  const uint32_t e = net::ntpEpoch();
  h.atMs.store(millis(), std::memory_order_relaxed);
  h.epoch.store(e, std::memory_order_relaxed);
  h.phase.store(NTP_DONE, std::memory_order_release);
  vTaskDelete(nullptr);
}

inline void rebase(time_t epoch) {
  State &s = state();
  s.baseEpoch = epoch;
  s.baseMs = millis();
}

inline void scheduleRetry(uint32_t nowMs) {
  State &s = state();
  s.nextQueryMs = nowMs + queryBackoffMs(s.attempt);
  if (s.attempt < 5)
    ++s.attempt;
}

// Aplica o que a tarefa trouxe. Devolve true se o relogio do sistema mudou.
inline bool consume(uint32_t nowMs) {
  State &s = state();
  Handoff &h = handoff();
  const uint32_t e = h.epoch.load(std::memory_order_relaxed);
  const uint32_t at = h.atMs.load(std::memory_order_relaxed);
  h.phase.store(NTP_IDLE, std::memory_order_relaxed);

  if (!isPlausibleEpoch((time_t)e)) {
    // O NINA ainda nao sincronizou (ou a rede caiu antes): tenta de novo mais
    // tarde, com backoff. A hora que ja havia, se havia, continua valendo.
    if (s.source == SOURCE_NONE)
      scheduleRetry(nowMs);
    else
      s.nextQueryMs = nowMs + QUERY_BACKOFF_MAX_MS;
    return false;
  }
  s.attempt = 0;
  s.nextQueryMs = nowMs + RESYNC_INTERVAL_MS;

  // O epoch foi lido `nowMs - at` ms atras; desconta o atraso ate este poll().
  const uint32_t lag = uint32_t(nowMs - at);
  const time_t exact = (time_t)e + (time_t)(lag / 1000u);
  if (s.source == SOURCE_NTP) {
    const int64_t drift = int64_t(time(NULL)) - int64_t(exact);
    if (drift <= STEP_TOLERANCE_S && drift >= -STEP_TOLERANCE_S) {
      rebase(exact);
      return false; // ja estava certo: nao faz o relogio da tela tremer
    }
  }
  struct timeval tv;
  tv.tv_sec = exact;
  tv.tv_usec = (suseconds_t)((lag % 1000u) * 1000u);
  settimeofday(&tv, NULL);
  rebase(exact);
  s.source = SOURCE_NTP;
  return true;
}

} // namespace detail

// Chamar uma vez no setup(). Sem RTC nao ha o que ler: so aplica o fuso para
// que qualquer localtime_r ja saia em horario de Brasilia. Devolve false porque
// a hora continua desconhecida ate o NTP.
inline bool begin() {
  applyTimezone();
  return false;
}

// Nao ha RTC para gravar. Fica para nao quebrar quem chamava.
inline bool saveToRtc() { return false; }

// Chamado pelo main.cpp quando a rede sobe (era o substituto de configTime).
// Os servidores sao ignorados: quem faz NTP e o firmware NINA, com os servidores
// dele (pool.ntp.org). Nao bloqueia: so aplica o fuso e agenda a primeira
// consulta para o proximo poll().
inline void configTimeBrazil(const char *server1 = "pool.ntp.org",
                             const char *server2 = "time.cloudflare.com",
                             const char *server3 = NULL) {
  (void)server1;
  (void)server2;
  (void)server3;
  State &s = state();
  applyTimezone();
  if (!s.requested) {
    s.requested = true;
    s.attempt = 0;
    // Primeira consulta ja na proxima volta. O NINA costuma levar alguns
    // segundos depois da associacao para acertar; o backoff cobre isso.
    s.nextQueryMs = millis();
  }
}

// Chamar a cada volta do loop(). Fora da janela de 1 s custa um millis(). Nunca
// toca no SPI1: so le o que a tarefa RTC_NTP publicou, ou dispara uma nova.
// Devolve true quando acabou de acertar o relogio do sistema.
inline bool poll() {
  State &s = state();
  const uint32_t nowMs = millis();
  if (uint32_t(nowMs - s.lastPollMs) < 1000u)
    return false;
  s.lastPollMs = nowMs;

  applyTimezone();
  if (!s.requested)
    return false;

  detail::Handoff &h = detail::handoff();
  const uint8_t phase = h.phase.load(std::memory_order_acquire);
  if (phase == detail::NTP_DONE)
    return detail::consume(nowMs);
  if (phase == detail::NTP_RUNNING)
    return false; // a tarefa esta esperando o SPI1; paciencia
  if (!timeReached(nowMs, s.nextQueryMs))
    return false;

  // Coprocessador ainda nao respondeu ao boot: consultar agora so criaria uma
  // tarefa para receber zero.
  if (!net::radioReady()) {
    detail::scheduleRetry(nowMs);
    return false;
  }
  h.phase.store(detail::NTP_RUNNING, std::memory_order_relaxed);
  // Nucleo 1, prioridade 1: fora do nucleo do loop() e do DVI, e acima das
  // tarefas ociosas para nao ficar para tras de um laco de prioridade 0.
  if (xTaskCreatePinnedToCore(detail::ntpTask, "RTC_NTP", detail::NTP_TASK_STACK, nullptr, 1,
                              nullptr, 1) != pdPASS) {
    h.phase.store(detail::NTP_IDLE, std::memory_order_relaxed);
    detail::scheduleRetry(nowMs); // sem memoria para a pilha: tenta depois
  }
  return false;
}

#else // !RTCCLOCK_HARDWARE — compilacao nativa: so a logica pura

inline bool begin() { return false; }
inline bool saveToRtc() { return false; }
inline bool poll() { return false; }
inline void configTimeBrazil(const char * = "pool.ntp.org", const char * = "time.cloudflare.com",
                             const char * = NULL) {
  applyTimezone();
}

#endif // RTCCLOCK_HARDWARE

} // namespace rtcclock

#pragma once
// ============================================================================
// Subtitles — legendas .srt no estilo do closed caption da linha 21 do NTSC.
//
// Por que existe: o par MJPEG+WAV do cartao nao carrega legenda nenhuma. Quem
// prepara o video (tools/prepare_video.py) pode deixar um `.srt` ao lado do
// `.mjpeg`, e este modulo o le enquanto o filme roda.
//
//   /M5RETRO/videos/foo/video.mjpeg  ->  /M5RETRO/videos/foo/video.srt
//
// Vocabulario visual reproduzido — o closed caption de verdade, nao a legenda
// de cinema: caixa preta opaca atras de cada linha, texto branco puro em caixa
// alta, no maximo duas linhas, ancorado na base. Nada de ciano: croma saturado
// (TFT_CYAN / 0x07FF) faz dot crawl na saida composta, e o CC original era
// branco no preto justamente porque era o que sobrevivia ao sinal.
//
// ---------------------------------------------------------------------------
//  Tres decisoes que valem explicacao
// ---------------------------------------------------------------------------
//
// 1) LEITURA SO PARA A FRENTE, SEM INDICE. Um .srt de um filme longo tem
//    milhares de cues; indexar todos custaria dezenas de KB de SRAM, que e o
//    recurso escasso aqui (ver AGENTS.md secao 2.2). Este leitor guarda no
//    maximo DUAS cues: a exibida e a proxima. O resto fica no cartao. Custo:
//    nao da para voltar. Depois de qualquer salto para tras (reiniciar o
//    programa, trocar de video) o chamador faz `arquivo.seek(0)` e `reset()`.
//
// 2) O RELOGIO E O DO AUDIO, NAO O `millis()`. O firmware ja acerta o video por
//    `samplesPlayed` (ver videoTick em src/main.cpp); a legenda usa o mesmo
//    relogio ou desanda junto com o video nos quadros descartados. Por isso a
//    API recebe `positionMs` pronto e nunca chama millis():
//
//      const uint32_t posMs = sampleRate ? uint32_t(uint64_t(samplesPlayed.load())
//                                                   * 1000ULL / sampleRate) : 0;
//
// 3) O CHAMADOR E DONO DO sdMutex. Este header NAO toma o mutex — nao inclui
//    FreeRTOS nem SD, justamente para compilar tambem no simulador de desktop.
//    `update()` recebe o `File&` ja aberto e **exige que o chamador segure o
//    sdMutex durante a chamada** (uma tomada por chamada, devolvida logo
//    depois — nunca segurar por mais tempo, senao o audio passa fome). Em
//    troca, `update()` faz pouquissima leitura: 192 bytes por bloco e no maximo
//    `kCuesPerUpdate` cues por chamada. `draw()` NAO toca no cartao.
//
// ---------------------------------------------------------------------------
//  Orcamento
// ---------------------------------------------------------------------------
//  sizeof(Subtitles) ~ 330 bytes (static_assert abaixo trava em 1 KB), sem
//  alocacao dinamica, sem String e sem LGFX_Sprite. A instancia deve ser
//  global/estatica: um objeto destes na pilha de uma tarefa que faz HTTPS ja
//  seria metade do respiro do handshake (AGENTS.md secao 2.3). `update()` usa
//  ~280 bytes de pilha em buffers locais; roda no loop() (8192), onde cabe.
//
// ---------------------------------------------------------------------------
//  Conflito com o OSD do player
// ---------------------------------------------------------------------------
//  A caixa da legenda ocupa y 168..199, e o OSD de videocassete (VcrOsd.h)
//  ocupa 148..221. Eles se sobrepoem de proposito: os dois querem a base da
//  tela, como na TV de verdade. Quem chama decide a precedencia — o caminho
//  recomendado e esconder a legenda enquanto `drawPlaybackOsd()` estiver
//  visivel (o OSD e transitorio, 3 s), simplesmente nao chamando `draw()`.
//
// ---------------------------------------------------------------------------
//  Limitacao conhecida da fonte
// ---------------------------------------------------------------------------
//  A VcrFont tem 45 glifos: espaco, 0-9, A-Z e : . - / % + ? ! — nao tem
//  virgula. Legenda e texto cheio de virgula, e cada uma sai como um espaco
//  (glyphIndex devolve SPACE para o que nao existe). O texto NAO e alterado
//  aqui de proposito: trocar ',' por '.' seria mentir na pontuacao. Resolver
//  de verdade custa um glifo novo na VcrFont.h (16 linhas de tabela, 32 bytes
//  de flash) e uma entrada em glyphIndex — fora do escopo deste header.
//
// Dependencias: SafeArea.h, VcrFont.h (que traz a LovyanGFX) e Ascii.h. Nada de
// Arduino, SD ou FreeRTOS — o mesmo header compila no firmware (gnu++11) e no
// simulador SDL.
// ============================================================================

#include "Ascii.h"
#include "SafeArea.h"
#include "VcrFont.h"

#include <stddef.h>
#include <stdint.h>
#include <string.h>

namespace subs {

// ---------------------------------------------------------------------------
//  Geometria — ancorada na base da area segura, ACIMA da barra dos botoes
// ---------------------------------------------------------------------------
namespace layout {

constexpr int kScale = 1;                 // 12x16 na tela; CC nunca foi grande
constexpr int kLineH = vcrfont::CELL_H;   // 16
constexpr int kMaxLines = 2;              // o CC da linha 21 tambem parava em 2
constexpr int kPadX = 4;                  // respiro da caixa preta, por lado
constexpr int kGapToBar = 2;              // folga ate a barra de legendas

// Colunas que cabem na largura segura com a caixa preta inclusa:
// (272 - 8) / 12 = 22 caracteres.
constexpr int kMaxCols = (crt::SAFE_W - 2 * kPadX) / (vcrfont::CELL_W * kScale);

constexpr int kBlockH = kMaxLines * kLineH;       // 32
constexpr int kBottom = crt::BAR_Y - kGapToBar;   // 200 — primeira linha livre
constexpr int kTop = kBottom - kBlockH;           // 168

// A celula da VcrFont ja tem 2 px de folga em cima e embaixo, entao a caixa
// preta nao precisa de padding vertical proprio: sai com a altura da celula.
static_assert(kBottom <= crt::BAR_Y, "legenda invade a barra dos botoes");
static_assert(kTop >= crt::SAFE_T, "legenda escapa pelo topo da area segura");
static_assert(kMaxCols >= 10, "area segura estreita demais para uma legenda");

} // namespace layout

// Cores em RGB565, escritas na mao (o header nao depende das macros TFT_*).
// Branco no preto: o par do CC original e o unico que nao sofre dot crawl.
constexpr uint16_t kInk = 0xFFFF;
constexpr uint16_t kBox = 0x0000;

// Retangulo em coordenadas do destino (ja com o deslocamento ox/oy aplicado).
// Sem inicializador de membro de proposito: em C++11 um NSDMI tiraria o status
// de agregado e quebraria a inicializacao por chaves.
struct Rect {
  int x, y, w, h;
};

// Faixa maxima que `draw()` pode tocar. Serve a quem prefere repintar sempre a
// mesma regiao a rastrear o retangulo sujo de cada cue.
inline Rect band() {
  Rect r;
  r.x = crt::SAFE_L;
  r.y = layout::kTop;
  r.w = crt::SAFE_W;
  r.h = layout::kBlockH;
  return r;
}

// Troca a extensao de `videoPath` por ".srt" (o `.srt` mora ao lado do video).
// Sem extensao, anexa. Devolve false se nao couber em `cap`.
inline bool makeSrtPath(const char *videoPath, char *dst, size_t cap) {
  if (!videoPath || !dst || cap < 5)
    return false;
  const size_t n = strlen(videoPath);
  size_t cut = n;
  for (size_t i = n; i > 0; --i) {
    const char c = videoPath[i - 1];
    if (c == '/')
      break; // ponto depois da ultima barra, ou nao vale
    if (c == '.') {
      cut = i - 1;
      break;
    }
  }
  if (cut + 5 > cap)
    return false;
  memcpy(dst, videoPath, cut);
  memcpy(dst + cut, ".srt", 5);
  return true;
}

// ---------------------------------------------------------------------------
//  Leitor + renderizador
// ---------------------------------------------------------------------------
//
// `Stream` e qualquer coisa com `read(uint8_t *, size_t) -> tamanho lido`,
// exatamente o contrato que `playback::MjpegReader` usa: o `File` do Arduino
// serve, e no desktop uma classe de 10 linhas sobre um buffer ou um
// std::istream tambem. E o que torna o parser testavel sem cartao SD.
class Subtitles {
public:
  // Quantas cues no maximo cada `update()` consome. Limita o trabalho (e o
  // tempo com o sdMutex na mao) quando o relogio pula varias cues de uma vez.
  static const int kCuesPerUpdate = 4;
  // Teto de linhas varridas atras de um "-->" numa unica chamada. Um arquivo de
  // lixo nao pode prender o loop; como o fluxo so anda para a frente, cada
  // chamada progride e o EOF encerra.
  static const int kScanPerUpdate = 64;
  // Teto de linhas de texto de UMA cue. Depois disso a cue e fechada onde esta.
  static const int kTextLines = 16;

  Subtitles() { reset(); }

  // Esquece tudo. Use ao abrir outro .srt, ou depois de `arquivo.seek(0)` —
  // este leitor nao volta sozinho.
  void reset() {
    cursor_ = count_ = 0;
    first_ = true;
    eof_ = false;
    haveCur_ = haveNext_ = false;
    lastStart_ = 0;
    started_ = false;
    seq_ = 0;
    cur_.reset();
    next_.reset();
    dirty_.x = dirty_.y = dirty_.w = dirty_.h = 0;
  }

  // Avanca o parser ate a cue correspondente a `positionMs`.
  //
  // PRE-CONDICAO: o chamador segura o sdMutex durante esta chamada (ela le do
  // cartao). Nao chame com o mutex ja tomado por outro caminho, e nao segure o
  // mutex em volta de `draw()` — `draw()` nao le nada.
  template <class Stream> void update(Stream &file, uint32_t positionMs) {
    for (int guard = 0; guard < kCuesPerUpdate; ++guard) {
      if (!haveNext_) {
        if (eof_)
          break;
        if (!parseCue(file, next_))
          break; // EOF, ou orcamento de varredura estourado: tenta na proxima
        haveNext_ = true;
      }
      if (next_.startMs > positionMs)
        break; // a proxima ainda esta no futuro: nada a promover
      cur_ = next_;
      haveCur_ = true;
      haveNext_ = false;
      ++seq_;
    }
  }

  // Ha cue valida cobrindo `positionMs`?
  bool active(uint32_t positionMs) const {
    return haveCur_ && cur_.count && positionMs >= cur_.startMs && positionMs < cur_.endMs;
  }

  // 0 quando nada esta no ar; caso contrario um numero que muda a cada troca de
  // cue. Guarde o valor anterior: mudou, repinte; virou 0, apague.
  uint32_t revision(uint32_t positionMs) const { return active(positionMs) ? seq_ : 0; }

  // Linhas ja normalizadas (ASCII maiusculo) e quebradas. `i` de 0 a 1.
  uint8_t lineCount() const { return cur_.count; }
  const char *line(uint8_t i) const { return i < cur_.count ? cur_.text[i] : ""; }
  uint32_t cueStartMs() const { return cur_.startMs; }
  uint32_t cueEndMs() const { return cur_.endMs; }
  bool finished() const { return eof_ && !haveNext_; }

  // Pinta a legenda sobre a imagem. Nao le o cartao: usa a cue ja em memoria.
  // `ox`/`oy` seguem a convencao dos pintores do repositorio (dst, ox, oy, ...):
  // com deslocamento zero e o desenho normal.
  //
  // Sem cue no ar nao desenha nada E NAO MEXE no retangulo sujo — e assim que o
  // chamador ainda consegue saber o que precisa repintar depois que a cue sai.
  void draw(lgfx::LovyanGFX *dst, int ox, int oy, uint32_t positionMs) {
    if (!dst || !active(positionMs))
      return;
    const int n = cur_.count;
    const int top = layout::kBottom - n * layout::kLineH;
    int minX = crt::W, maxX = 0;
    dst->startWrite();
    for (int i = 0; i < n; ++i) {
      const int w = vcrfont::textWidth(cur_.text[i], layout::kScale);
      const int x = (crt::W - w) / 2; // centro do quadro = centro da area segura
      const int y = top + i * layout::kLineH;
      // Caixa opaca por linha, como no CC de verdade (cada fileira tinha o seu
      // fundo, e nao um bloco unico atras das duas).
      dst->fillRect(ox + x - layout::kPadX, oy + y, w + 2 * layout::kPadX, layout::kLineH, kBox);
      // Sem contorno: a caixa ja da o contraste, e contorno preto sobre preto
      // seria 2,15x os pixels por glifo de graca (ver VcrFont.h).
      vcrfont::drawText(dst, cur_.text[i], ox + x, oy + y, (int32_t)kInk, layout::kScale,
                        vcrfont::NO_OUTLINE);
      if (x - layout::kPadX < minX)
        minX = x - layout::kPadX;
      if (x + w + layout::kPadX > maxX)
        maxX = x + w + layout::kPadX;
    }
    dst->endWrite();
    dirty_.x = ox + minX;
    dirty_.y = oy + top;
    dirty_.w = maxX - minX;
    dirty_.h = n * layout::kLineH;
  }

  // Ultimo retangulo pintado, em coordenadas do destino. `w == 0` = nada sujo.
  // O caminho barato para apaga-lo e deixar o proximo quadro do filme cobrir a
  // area; com o video pausado, redecodifique o quadro (redrawCurrentFrame()).
  Rect dirty() const { return dirty_; }

  // Apaga o retangulo sujo e o zera. Atalho para quando nao ha imagem embaixo
  // (letterbox) — sobre o filme prefira repintar o quadro.
  void clear(lgfx::LovyanGFX *dst, int ox, int oy, uint16_t background = kBox) {
    if (dst && dirty_.w > 0)
      dst->fillRect(dirty_.x + ox, dirty_.y + oy, dirty_.w, dirty_.h, background);
    dirty_.x = dirty_.y = dirty_.w = dirty_.h = 0;
  }

private:
  // Capacidade do texto cru de uma cue depois de tirar as etiquetas e
  // normalizar: 2 linhas de 22 mais folga para a quebra de palavra.
  static const size_t kTextCap = 80;
  static const size_t kLineCap = 128; // linha do arquivo; o excedente e comido

  struct Cue {
    uint32_t startMs, endMs;
    uint8_t count;
    char text[layout::kMaxLines][layout::kMaxCols + 1];
    void reset() {
      startMs = endMs = 0;
      count = 0;
      text[0][0] = text[1][0] = 0;
    }
  };

  uint8_t block_[192];
  size_t cursor_, count_;
  bool first_, eof_;
  bool haveCur_, haveNext_, started_;
  uint32_t lastStart_, seq_;
  Cue cur_, next_;
  Rect dirty_;

  // -------------------------------------------------------------------------
  //  Fluxo de bytes
  // -------------------------------------------------------------------------

  // Proximo byte, ou -1 no fim. Le em blocos para nao pagar uma chamada de
  // sistema por caractere.
  template <class Stream> int nextByte(Stream &file) {
    if (cursor_ == count_) {
      if (eof_)
        return -1;
      const size_t got = file.read(block_, sizeof(block_));
      // `got` grande demais cobre tambem um read() com sinal devolvendo -1.
      if (got == 0 || got > sizeof(block_)) {
        eof_ = true;
        return -1;
      }
      count_ = got;
      cursor_ = 0;
      if (first_) {
        first_ = false;
        // BOM UTF-8: so pode estar nos 3 primeiros bytes do arquivo, entao
        // sempre cai neste primeiro bloco.
        if (count_ >= 3 && block_[0] == 0xEF && block_[1] == 0xBB && block_[2] == 0xBF)
          cursor_ = 3;
        if (cursor_ == count_)
          return nextByte(file);
      }
    }
    return block_[cursor_++];
  }

  // Le uma linha sem o terminador. CRLF, LF e a ultima linha sem quebra valem.
  // Linha maior que `cap` e truncada mas CONSUMIDA ate o fim — e o que garante
  // que um arquivo binario passado por engano nao trave o parser.
  template <class Stream> bool readLine(Stream &file, char *dst, size_t cap) {
    size_t n = 0;
    for (;;) {
      const int c = nextByte(file);
      if (c < 0) {
        dst[n] = 0;
        return n > 0;
      }
      if (c == '\n')
        break;
      if (c == '\r')
        continue;
      if (n + 1 < cap)
        dst[n++] = (char)c;
    }
    dst[n] = 0;
    return true;
  }

  // -------------------------------------------------------------------------
  //  Numeros e tempos
  // -------------------------------------------------------------------------

  static bool isDigit(char c) { return c >= '0' && c <= '9'; }

  // Le digitos a partir de `i`. Devolve quantos leu (0 = nao era numero).
  static int readUInt(const char *s, size_t &i, uint32_t &out) {
    int digits = 0;
    out = 0;
    while (isDigit(s[i])) {
      if (out < 100000000UL) // trava boba contra estouro em lixo do tipo "999999999999"
        out = out * 10 + uint32_t(s[i] - '0');
      ++i;
      ++digits;
    }
    return digits;
  }

  // `HH:MM:SS,mmm` a partir de `i`. Aceita ponto no lugar da virgula (varios
  // conversores geram assim), horas com 1 a 3 digitos e fracao de 1 a 3 casas.
  static bool parseTime(const char *s, size_t &i, uint32_t &ms) {
    while (s[i] == ' ' || s[i] == '\t')
      ++i;
    uint32_t h = 0, m = 0, sec = 0, frac = 0;
    if (!readUInt(s, i, h) || s[i] != ':')
      return false;
    ++i;
    if (!readUInt(s, i, m) || s[i] != ':')
      return false;
    ++i;
    if (!readUInt(s, i, sec))
      return false;
    if (s[i] == ',' || s[i] == '.') {
      ++i;
      const size_t before = i;
      if (!readUInt(s, i, frac))
        return false;
      size_t digits = i - before;
      // Normaliza para milissegundos: "5" = 500 ms, "05" = 50 ms, "005" = 5 ms.
      while (digits < 3) {
        frac *= 10;
        ++digits;
      }
      while (digits > 3) {
        frac /= 10;
        --digits;
      }
    }
    if (h > 999 || m > 59 || sec > 59 || frac > 999)
      return false;
    ms = h * 3600000UL + m * 60000UL + sec * 1000UL + frac;
    return true;
  }

  // Posicao do "-->" na linha, ou -1.
  static int findArrow(const char *s) {
    for (int i = 0; s[i]; ++i)
      if (s[i] == '-' && s[i + 1] == '-' && s[i + 2] == '>')
        return i;
    return -1;
  }

  // Inicio do carimbo de tempo que termina antes da seta. Voltar a partir da
  // seta em vez de comecar da coluna 0 e o que faz "1 00:00:01,000 --> ..."
  // funcionar: ha conversor que gruda o numero de sequencia na mesma linha.
  static size_t timeStart(const char *s, int arrow) {
    size_t i = (size_t)arrow;
    while (i && (s[i - 1] == ' ' || s[i - 1] == '\t'))
      --i;
    while (i && (isDigit(s[i - 1]) || s[i - 1] == ':' || s[i - 1] == ',' || s[i - 1] == '.'))
      --i;
    return i;
  }

  // -------------------------------------------------------------------------
  //  Texto
  // -------------------------------------------------------------------------

  // Tira as etiquetas que o .srt carrega (<i>, </font>, {\an8}) e devolve o
  // texto cru. Roda ANTES da normalizacao: '<', '>', '{' e '}' sao ASCII e
  // nunca aparecem no meio de uma sequencia UTF-8, entao e seguro.
  static void stripTags(const char *src, char *dst, size_t cap) {
    size_t j = 0;
    char closing = 0;
    for (size_t i = 0; src[i] && j + 1 < cap; ++i) {
      const char c = src[i];
      if (closing) {
        if (c == closing)
          closing = 0;
        continue;
      }
      if (c == '<') {
        closing = '>';
        continue;
      }
      if (c == '{') {
        closing = '}';
        continue;
      }
      dst[j++] = c;
    }
    dst[j] = 0;
  }

  // Quebra `text` (ja em ASCII maiusculo, com '\n' separando as linhas do
  // arquivo) em no maximo kMaxLines linhas de kMaxCols colunas. Quebra na
  // ultima folga que couber; palavra maior que a linha e cortada na marra. O
  // que sobrar vira "..." no fim da ultima linha — o CC tambem cortava, mas
  // sem aviso, e aqui o aviso custa 3 caracteres e evita parecer bug.
  static uint8_t wrap(const char *text, char out[layout::kMaxLines][layout::kMaxCols + 1]) {
    uint8_t n = 0;
    size_t i = 0;
    while (n < layout::kMaxLines) {
      while (text[i] == ' ' || text[i] == '\n')
        ++i;
      if (!text[i])
        break;
      size_t take = 0, lastSpace = 0;
      bool haveSpace = false;
      size_t j = i;
      while (text[j] && text[j] != '\n' && take < (size_t)layout::kMaxCols) {
        if (text[j] == ' ') {
          lastSpace = take;
          haveSpace = true;
        }
        ++take;
        ++j;
      }
      // So vale quebrar na folga se a linha realmente continua depois dela.
      size_t adv = take;
      if (text[j] && text[j] != '\n' && haveSpace && lastSpace > 0)
        adv = lastSpace;
      size_t len = adv;
      memcpy(out[n], text + i, len);
      while (len && out[n][len - 1] == ' ')
        --len;
      out[n][len] = 0;
      i += adv;
      if (len)
        ++n;
      else if (adv == 0)
        break; // paranoia: sem avanco nao pode haver segunda volta
    }
    // Sobrou conteudo? Marca o corte na ultima linha.
    while (text[i] == ' ' || text[i] == '\n')
      ++i;
    if (text[i] && n > 0) {
      char *last = out[n - 1];
      size_t len = strlen(last);
      if (len + 3 <= (size_t)layout::kMaxCols) {
        last[len] = last[len + 1] = last[len + 2] = '.';
        last[len + 3] = 0;
      } else if (len >= 3) {
        last[len - 1] = last[len - 2] = last[len - 3] = '.';
      }
    }
    for (uint8_t k = n; k < layout::kMaxLines; ++k)
      out[k][0] = 0;
    return n;
  }

  // -------------------------------------------------------------------------
  //  Uma cue
  // -------------------------------------------------------------------------

  // Le a proxima cue VALIDA. Devolve false no EOF ou quando o orcamento de
  // linhas varridas acabou (nesse caso a proxima chamada continua de onde
  // parou — o fluxo so anda para a frente, entao nao ha laco infinito).
  //
  // Tolerancias, todas exercitadas pelo sim/probes/subtitles.cpp: numero de
  // sequencia ausente, errado ou substituido por lixo; linhas em branco de
  // sobra; CRLF; BOM. Cue com fim <= inicio, com tempo impossivel ou fora de
  // ordem e DESCARTADA — sem legenda e melhor que legenda errada.
  template <class Stream> bool parseCue(Stream &file, Cue &out) {
    char line[kLineCap];
    for (int scanned = 0; scanned < kScanPerUpdate; ++scanned) {
      if (!readLine(file, line, sizeof(line))) {
        eof_ = true;
        return false;
      }
      const int arrow = findArrow(line);
      if (arrow < 0)
        continue; // numero de sequencia, linha em branco ou lixo: ignora
      size_t p = timeStart(line, arrow);
      uint32_t startMs = 0, endMs = 0;
      if (!parseTime(line, p, startMs))
        continue;
      p = (size_t)arrow + 3;
      if (!parseTime(line, p, endMs))
        continue;

      // Texto: ate a linha em branco ou o fim do arquivo. Limitado a kTextLines
      // para que uma cue absurda nao leia o arquivo inteiro numa chamada so; o
      // excedente cai na varredura seguinte e e ignorado por nao ter seta.
      char raw[kTextCap], tmp[kLineCap];
      size_t used = 0;
      raw[0] = 0;
      bool more = true;
      for (int t = 0; more && t < kTextLines; ++t) {
        more = readLine(file, line, sizeof(line));
        if (!more) {
          eof_ = true;
          break;
        }
        // Linha em branco fecha a cue. Tambem fecha se ja apareceu outra seta,
        // caso o arquivo tenha esquecido a separacao (acontece).
        if (!line[0])
          break;
        if (used && findArrow(line) >= 0)
          break;
        stripTags(line, tmp, sizeof(tmp));
        if (used + 1 < sizeof(raw) && used)
          raw[used++] = '\n';
        // normalizeUpper termina em \0 e devolve o que escreveu: da para
        // emendar as linhas da cue sem buffer intermediario.
        used += ::ascii::normalizeUpper(raw + used, sizeof(raw) - used, tmp);
      }

      // Validacao. Ordem crescente exigida porque o leitor nao volta: uma cue
      // que comeca antes da anterior nunca poderia ser exibida mesmo.
      if (endMs <= startMs)
        continue;
      if (started_ && startMs < lastStart_)
        continue;
      out.startMs = startMs;
      out.endMs = endMs;
      out.count = wrap(raw, out.text);
      if (!out.count)
        continue; // cue sem texto util (so etiquetas, ou so acento sem ASCII)
      lastStart_ = startMs;
      started_ = true;
      return true;
    }
    return false;
  }
};

// O orcamento de SRAM em constante, para nao virar comentario desatualizado.
static_assert(sizeof(Subtitles) <= 1024, "Subtitles estourou 1 KB de SRAM");

} // namespace subs

#pragma once
// ============================================================================
// TestPattern.h — carta de ajuste SMPTE, tom de referencia de 1 kHz e as telas
// de "sem sinal" / fim de transmissao.
//
// Serve a duas coisas que nenhuma outra tela deste firmware faz:
//
//   1. CALIBRAR O TUBO. As barras SMPTE sao a unica tela do aparelho que usa o
//      quadro INTEIRO de 320x240, de proposito. Todas as outras respeitam a
//      area segura (SafeArea.h) porque um tubo esconde ~7% de cada borda; aqui
//      o objetivo e justamente MEDIR quanto ele esconde. Quem olha a TV ve onde
//      as barras somem e descobre o overscan do aparelho dele. O unico elemento
//      que continua dentro da caixa segura e o TEXTO: um rotulo que a TV corta
//      nao informa nada.
//   2. ENCERRAR A TRANSMISSAO. Barras + tom de 1 kHz e o par classico de
//      sign-off; e o "sem sinal" (chuvisco ou cartaz) e o que a tela mostra
//      quando nao ha cartao SD.
//
// ---------------------------------------------------------------------------
// O que este arquivo assume sobre o codificador NTSC (medido, nao chutado)
// ---------------------------------------------------------------------------
// Os niveis abaixo saem da tabela NTSC do M5GFX 0.2.29
// (lgfx/v1/platforms/esp32/Panel_CVBS.cpp, struct signal_spec_t):
//
//     blanking = 286 mV  -> 0 IRE
//     black    = 340 mV  -> 7,5 IRE   (setup americano, o mesmo do NTSC-M)
//     white    = 960 mV  -> 94,4 IRE  (abaixo de 100 IRE de PROPOSITO: assim o
//                                      pico de croma do amarelo cai perto de
//                                      100 IRE em vez de estourar)
//
// Consequencias que mudam o desenho:
//
//   * **0x0000 NAO e o nivel de apagamento (blanking).** O codificador ja
//     insere o pedestal de 7,5 IRE, entao o preto do framebuffer sai no nivel
//     de PRETO correto do NTSC. Isso e bom (nao precisamos compensar nada) e
//     tem um preco: **nao existe "mais preto que preto"**. A barra de -4 IRE
//     do PLUGE e impossivel de gerar a partir de pixel; ela e desenhada
//     identica ao preto de referencia e o comentario do PLUGE explica como
//     calibrar mesmo assim.
//   * A escala util e 86,8 IRE para 256 codigos -> **0,3405 IRE por codigo**.
//   * Como o branco esta em 94,4 IRE e nao em 100, uma barra de 75% medida num
//     osciloscopio da ~71,9 IRE em vez dos 76,9 IRE do papel. Nao e erro de
//     conta nossa: e o ganho escolhido pelo M5GFX, e o controle de contraste da
//     TV absorve a diferenca. As PROPORCOES entre as barras, que e o que a
//     carta mede, continuam certas.
//   * O caminho RGB565 -> RGB888 do codificador e `(v5 * 0x21) >> 2` e
//     `(v6 * 0x41) >> 4`, ou seja replicacao de bits. Cada constante de cor
//     abaixo traz, no comentario, o RGB888 que o codificador realmente vai ver.
//
// ---------------------------------------------------------------------------
// Restricoes do projeto respeitadas aqui (ver AGENTS.md)
// ---------------------------------------------------------------------------
//   * **C++11** (`-std=gnu++11`): todo `constexpr` daqui e um unico `return`,
//     sem laco e sem variavel local. Conferir com `make -C sim cxx11`.
//   * **Nada de sprite nem de framebuffer proprio.** O desenho e so `fillRect`;
//     a SRAM e o recurso escasso (heap livre medido: 28-38 KB).
//   * A tabela do tom de 1 kHz tem 882 bytes e vive num `static const` dentro
//     de funcao, ou seja **em flash (.rodata), nao em SRAM**. O estado do
//     gerador sao 4 bytes.
//   * **Este header NAO toca no I2S.** I2S0 e do video composto e o I2S1 tem
//     dono (o `audioTask` do main.cpp). Aqui so se PRODUZ PCM; quem escreve e
//     o dono do barramento.
//   * Texto ASCII, sem acento: as fontes bitmap so tem ASCII.
//
// Dependencias: LovyanGFX (fj/Gfx.h, vem pela VcrFont.h), SafeArea.h e
// Ascii.h. Nada de Arduino, FreeRTOS, SD ou I2S — o destino e um
// `lgfx::LovyanGFX*`, entao o mesmo header serve ao canvas `tv` do aparelho e
// ao painel SDL do simulador.
// ============================================================================

#include "Ascii.h"
#include "SafeArea.h"
#include "VcrFont.h" // traz fj/Gfx.h (LovyanGFX) e a fonte grossa 12x16 do cartaz

#include <stddef.h>
#include <stdint.h>

namespace testpattern {

// ===========================================================================
//  1. Cores
// ===========================================================================

// RGB888 -> RGB565 por truncamento, que e exatamente o que o M5GFX faz em
// color565(). Um unico `return`, para continuar valendo em C++11.
constexpr uint16_t rgb565(int r, int g, int b) {
  return (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | ((b & 0xF8) >> 3));
}

// Niveis de referencia da carta, em codigo de 8 bits.
constexpr int L75 = 191;  // 0,75 * 255 = 191,25 -> 191
constexpr int L100 = 255; // branco de referencia

// --- as sete barras de 75% -------------------------------------------------
// Valor 565 e, entre parenteses, o RGB888 que o codificador reconstroi.
// ATENCAO ao passar qualquer uma destas para o LovyanGFX: o tipo do argumento
// e que decide como a cor e lida. Em misc/colortype.hpp:861-866, uint8_t vira
// RGB332, uint16_t/int16_t/int32_t viram RGB565 e **uint32_t vira RGB888**.
// Um (uint32_t)GRAY75 faz 0xBDF7 ser lido como 0x00BDF7, ou seja R=0, G=189,
// B=247, e a barra cinza sai esverdeada. Era esse o defeito aqui. Passe
// uint16_t, ou lgfx::rgb565_t, nunca uint32_t.
constexpr uint16_t GRAY75 = rgb565(L75, L75, L75);  // 0xBDF7  (189,190,189)
constexpr uint16_t YELLOW75 = rgb565(L75, L75, 0);  // 0xBDE0  (189,190,  0)
constexpr uint16_t CYAN75 = rgb565(0, L75, L75);    // 0x05F7  (  0,190,189)
constexpr uint16_t GREEN75 = rgb565(0, L75, 0);     // 0x05E0  (  0,190,  0)
constexpr uint16_t MAGENTA75 = rgb565(L75, 0, L75); // 0xB817  (189,  0,189)
constexpr uint16_t RED75 = rgb565(L75, 0, 0);       // 0xB800  (189,  0,  0)
constexpr uint16_t BLUE75 = rgb565(0, 0, L75);      // 0x0017  (  0,  0,189)

// --- linha de baixo --------------------------------------------------------
constexpr uint16_t WHITE100 = rgb565(L100, L100, L100); // 0xFFFF  (255,255,255)
constexpr uint16_t BLACK = 0x0000;                      // 7,5 IRE: ver cabecalho

// -I e +Q sao os eixos de croma do NTSC. Os equivalentes RGB usuais da carta
// (croma em amplitude cheia, luma baixa) sao #00214C e #32006A.
constexpr uint16_t MINUS_I = rgb565(0, 33, 76);  // 0x0109  (  0, 32, 72)
constexpr uint16_t PLUS_Q = rgb565(50, 0, 106);  // 0x300D  ( 49,  0,107)

// PLUGE (Picture Line-Up Generating Equipment) — ajuste de brilho.
//
// O papel pede tres barras: -4 / 0 / +4 IRE em torno do preto. Aqui:
//
//   PLUGE_MINUS  impossivel. O pedestal de 7,5 IRE ja esta no codificador e o
//                codigo 0 e o piso; nao da para descer abaixo do preto a partir
//                de pixel. Fica identica ao preto de referencia, DE PROPOSITO.
//   BLACK        preto de referencia, codigo 0 = 7,5 IRE.
//   PLUGE_PLUS   codigo 8 = +2,72 IRE. Em RGB565 os cinzas neutros andam de 8
//                em 8 codigos (R5/B5 tem passo 8), entao +4 IRE (codigo ~12)
//                simplesmente nao existe nesta profundidade: 8 e o degrau
//                imediatamente acima do preto.
//
// Como calibrar com o que da para gerar: abaixe o BRILHO ate as tres barras
// virarem um bloco preto so; suba ate a TERCEIRA (a da direita) aparecer por
// pouco. Nesse ponto as duas primeiras ainda estao fundidas com o fundo — que e
// o mesmo criterio do PLUGE original, so que lido da direita para a esquerda.
constexpr uint16_t PLUGE_MINUS = BLACK;               // recortado no piso
constexpr uint16_t PLUGE_PLUS = rgb565(8, 8, 8);      // 0x0841  (8,8,8)  +2,72 IRE
constexpr uint16_t PLUGE_PLUS_HI = rgb565(16, 16, 16);// 0x1082  (16,16,16) +5,45 IRE
                                                      // degrau alternativo, para
                                                      // tubo muito surrado

// ===========================================================================
//  2. Geometria da carta (SMPTE ECR 1-1978, campo dividido)
// ===========================================================================
//
//   topo   67%  ->  161 px   sete barras de 75%
//   meio    8%  ->   19 px   barras azuis invertidas (castellation)
//   base   25%  ->   60 px   -I / branco 100% / +Q / preto / PLUGE / preto
//
// 240 * 0,67 = 160,8 ; 240 * 0,08 = 19,2 ; 240 * 0,25 = 60. Arredondado para
// 161 + 19 + 60 = 240 exatos, sem linha sobrando.
constexpr int BARS_Y = 0;
constexpr int BARS_H = 161;
constexpr int MID_Y = BARS_Y + BARS_H;  // 161
constexpr int MID_H = 19;
constexpr int BOT_Y = MID_Y + MID_H;    // 180
constexpr int BOT_H = crt::H - BOT_Y;   // 60

// Borda esquerda da barra `i` (0..7). 320/7 = 45,71, entao as barras saem com
// 45 ou 46 px — a diferenca de 1 px some no borrao horizontal do NTSC, e o
// importante (somar 320 exatos, sem coluna orfa na direita) fica garantido.
//   0, 45, 91, 137, 182, 228, 274, 320
constexpr int barX(int i) { return (i * crt::W) / 7; }

static_assert(BARS_H + MID_H + BOT_H == crt::H, "as tres faixas precisam somar 240");
static_assert(barX(0) == 0 && barX(7) == crt::W, "as barras precisam cobrir 0..320");

// O rotulo cai no bloco preto da linha de baixo, entre as barras 3 e 5. Esse
// retangulo e [137,228) x [180,240), e as duas linhas de texto ficam em
// [194,214) — dentro de crt::SAFE_* nos dois eixos, que e a regra para texto.
constexpr int LABEL_X = barX(3);
constexpr int LABEL_W = barX(5) - barX(3); // 91 px
constexpr int LABEL_Y1 = BOT_Y + 14;       // 194
constexpr int LABEL_Y2 = BOT_Y + 26;       // 206

static_assert(LABEL_X >= crt::SAFE_L && LABEL_X + LABEL_W <= crt::SAFE_R,
              "rotulo fora da area segura no eixo X");
static_assert(LABEL_Y1 >= crt::SAFE_T && LABEL_Y2 + 8 <= crt::SAFE_B,
              "rotulo fora da area segura no eixo Y");

// ===========================================================================
//  3. Desenho
// ===========================================================================

namespace detail {

inline void seg(lgfx::LovyanGFX *dst, int ox, int oy, int x0, int x1, int y, int h, uint16_t color) {
  dst->fillRect(ox + x0, oy + y, x1 - x0, h, (uint16_t)color);
}

// Normaliza texto de fora para ASCII antes de desenhar (armadilha 9 do
// AGENTS.md: acento em UTF-8 sao dois bytes sem glifo, viram dois buracos).
inline const char *norm(char *dst, size_t cap, const char *src) {
  if (!cap)
    return "";
  if (!src) {
    dst[0] = 0;
    return dst;
  }
  ascii::normalizeUpper(dst, cap, src);
  return dst;
}

} // namespace detail

// Barras SMPTE no quadro inteiro, com rotulo de emissora.
//
// `l1` / `l2` podem ser nulos (carta limpa, sem texto). Passam por
// ascii::normalizeUpper, entao aceitam texto vindo de fora.
inline void drawBarsLabeled(lgfx::LovyanGFX *dst, int ox, int oy, const char *l1, const char *l2) {
  if (!dst)
    return;

  // Em flash, nao em SRAM: 14 bytes cada.
  static const uint16_t kTop[7] = {GRAY75, YELLOW75, CYAN75, GREEN75, MAGENTA75, RED75, BLUE75};
  // Faixa do meio: as barras azuis invertidas. A ordem existe para que, com o
  // croma da TV desligado (ou so o canal azul ligado), as colunas fiquem com
  // luminancia igual e as bordas sumam — e assim que se ajusta cor/matiz.
  static const uint16_t kMid[7] = {BLUE75, BLACK, MAGENTA75, BLACK, CYAN75, BLACK, GRAY75};

  dst->startWrite();

  for (int i = 0; i < 7; ++i) {
    detail::seg(dst, ox, oy, barX(i), barX(i + 1), BARS_Y, BARS_H, kTop[i]);
    detail::seg(dst, ox, oy, barX(i), barX(i + 1), MID_Y, MID_H, kMid[i]);
  }

  // Linha de baixo. Larguras em unidades de barra: -I 1, branco 1, +Q 1,
  // preto 2, PLUGE 1, preto 1 = 7.
  detail::seg(dst, ox, oy, barX(0), barX(1), BOT_Y, BOT_H, MINUS_I);
  detail::seg(dst, ox, oy, barX(1), barX(2), BOT_Y, BOT_H, WHITE100);
  detail::seg(dst, ox, oy, barX(2), barX(3), BOT_Y, BOT_H, PLUS_Q);
  detail::seg(dst, ox, oy, barX(3), barX(5), BOT_Y, BOT_H, BLACK);

  const int p0 = barX(5), p3 = barX(6);
  const int p1 = p0 + (p3 - p0) / 3, p2 = p0 + ((p3 - p0) * 2) / 3;
  detail::seg(dst, ox, oy, p0, p1, BOT_Y, BOT_H, PLUGE_MINUS);
  detail::seg(dst, ox, oy, p1, p2, BOT_Y, BOT_H, BLACK);
  detail::seg(dst, ox, oy, p2, p3, BOT_Y, BOT_H, PLUGE_PLUS);

  detail::seg(dst, ox, oy, barX(6), barX(7), BOT_Y, BOT_H, BLACK);

  if (l1 || l2) {
    // Font0 tamanho 1 (6x8) de proposito: o rotulo e assinatura, nao conteudo.
    // Grande demais ele roubaria area preta que o PLUGE precisa ter ao lado.
    char b1[16], b2[16];
    dst->setFont(&fonts::Font0);
    dst->setTextSize(1);
    dst->setTextDatum(lgfx::textdatum::top_center);
    dst->setTextColor((uint16_t)GRAY75); // fore == back no LovyanGFX = fundo transparente
    const int cx = ox + LABEL_X + LABEL_W / 2;
    if (l1)
      dst->drawString(detail::norm(b1, sizeof(b1), l1), cx, oy + LABEL_Y1);
    if (l2)
      dst->drawString(detail::norm(b2, sizeof(b2), l2), cx, oy + LABEL_Y2);
    dst->setTextDatum(lgfx::textdatum::top_left);
  }

  dst->endWrite();
}

// Ponto de entrada padrao: mesma assinatura dos outros pintores do projeto,
// entao serve ao painel CVBS e ao LCD sem adaptacao.
inline void drawBars(lgfx::LovyanGFX *dst, int ox, int oy) {
  drawBarsLabeled(dst, ox, oy, "M5 RETRO TV", "SMPTE 75% 1KHZ");
}

// ---------------------------------------------------------------------------
//  Chuvisco ("snow") — o "sem sinal" classico
// ---------------------------------------------------------------------------
//
// Por celula de 8x8, nao por pixel: 40x30 = 1200 fillRect por quadro, contra
// 76.800 escritas de um laco pixel a pixel. O ruido de um tubo sem sinal e
// grosso mesmo, entao a celula nao custa realismo.
//
// O estado e do objeto, nao um `static` escondido (armadilha 6 do AGENTS.md:
// tela que herda o estado da visita anterior). Quem entra na tela chama
// reset().
class Snow {
public:
  static constexpr int CELL = 8;

  constexpr explicit Snow(uint32_t seed = 0x2545F491u) : s_(seed | 1u) {}

  void reset(uint32_t seed = 0x2545F491u) { s_ = seed | 1u; }

  // Um quadro de chuvisco no quadro inteiro. Chame de novo para o proximo.
  void draw(lgfx::LovyanGFX *dst, int ox, int oy, int cell = CELL) {
    if (!dst || cell < 1)
      return;
    dst->startWrite();
    for (int y = 0; y < crt::H; y += cell) {
      const int h = (y + cell > crt::H) ? crt::H - y : cell;
      for (int x = 0; x < crt::W; x += cell) {
        const int w = (x + cell > crt::W) ? crt::W - x : cell;
        const int v = (int)(next() >> 24); // byte alto: o de melhor distribuicao
        dst->fillRect(ox + x, oy + y, w, h, (uint16_t)rgb565(v, v, v));
      }
    }
    dst->endWrite();
  }

private:
  // xorshift32: 3 shifts e 3 XORs por celula. Um rand() da libc aqui custaria
  // chamada de funcao e estado global compartilhado com o resto do firmware.
  uint32_t next() {
    s_ ^= s_ << 13;
    s_ ^= s_ >> 17;
    s_ ^= s_ << 5;
    return s_;
  }
  uint32_t s_;
};

// Instancia de conveniencia para quem so quer um pintor (dst, ox, oy).
// Constante-inicializada (construtor constexpr), entao nao gera guard variable
// nem inicializacao em tempo de boot.
inline Snow &sharedSnow() {
  static Snow s;
  return s;
}

inline void drawSnow(lgfx::LovyanGFX *dst, int ox, int oy) {
  sharedSnow().draw(dst, ox, oy);
}

// ---------------------------------------------------------------------------
//  Cartaz (slate) — "NO SIGNAL" / fim de transmissao
// ---------------------------------------------------------------------------
//
// Barato: fundo preto, moldura e duas linhas de texto. Nada de por a data ou a
// hora aqui — isso obrigaria a repintar o quadro inteiro a cada segundo.
//
// `boxOnly` desenha so a caixa, sem apagar o fundo: e assim que o cartaz entra
// por cima do chuvisco em drawNoSignal().
inline void drawSlateText(lgfx::LovyanGFX *dst, int ox, int oy, const char *title, const char *sub,
                          bool boxOnly = false) {
  if (!dst)
    return;

  // Caixa centralizada e inteiramente dentro da area segura.
  const int bx = crt::SAFE_L;
  const int bw = crt::SAFE_W;
  const int bh = sub ? 84 : 56;
  const int by = (crt::H - bh) / 2;

  char t[24], s[32];
  const char *tt = detail::norm(t, sizeof(t), title ? title : "NO SIGNAL");
  const char *ss = sub ? detail::norm(s, sizeof(s), sub) : (const char *)0;

  dst->startWrite();
  if (!boxOnly)
    dst->fillRect(ox, oy, crt::W, crt::H, (uint16_t)BLACK);
  dst->fillRect(ox + bx, oy + by, bw, bh, (uint16_t)BLACK);
  dst->drawRect(ox + bx, oy + by, bw, bh, (uint16_t)GRAY75);
  dst->drawRect(ox + bx + 1, oy + by + 1, bw - 2, bh - 2, (uint16_t)GRAY75);

  // VcrFont escala 2 = celula 24x32, traco de 4 px: e a unica fonte do projeto
  // que aguenta o borrao horizontal do NTSC em tamanho grande.
  vcrfont::drawTextCentered(dst, tt, ox + bx, oy + by + 12, bw, (int32_t)WHITE100, 2);
  if (ss)
    vcrfont::drawTextCentered(dst, ss, ox + bx, oy + by + 52, bw, (int32_t)GRAY75, 1);
  dst->endWrite();
}

